/**
 * 乙体系 · 体用路线法推演模块
 *
 * 规格依据：《规矩/体用路线法.md》
 * 解耦自排盘底座 engine.mjs，独立承载体用四项、主要矛盾、从格改判与护卫网络推演。
 *
 * 排盘事实底座由 ./engine.mjs 提供。
 */
import {
  STEMS,
  BRANCHES,
  ELEMENTS,
  STEM_ELEMENT,
  STEM_YANG,
  BRANCH_ELEMENT,
  HIDDEN_STEMS_SPEC,
  tenGod,
  twelveStage,
  STEM_COMBINE,
  BRANCH_COMBINE,
  BRANCH_CLASH,
  BRANCH_DESTROY,
  SHENG_MAP,
  KE_MAP,
  seasonState,
  kingOf,
  elementStrength,
  gzRelations,
  castChart,
  tiaohouAssessment,
  elementBranchStage,
  dayMasterSupport,
  relationsOf,
  tenGodStrength,
  tongguanOf,
  specialGejuOf,
  五行字,
  parseBirth,
  parseArgs,
  LUSHEN,
} from './engine.mjs';

/** 体用路线法四项的可读输出（CLI `--tiyong`） */
export function formatTiyong(t) {
  const L = [];
  if (t.覆盖 && t.覆盖.covered === false) {
    L.push('================================================================================');
    L.push(`【本工具看法（乙体系）】⚠ 本体系未覆盖，暂不判断`);
    L.push(`原因：${t.覆盖.原因}`);
    L.push(`依据：${t.覆盖.依据}`);
    L.push('================================================================================');
    L.push('');
  }
  L.push(`【体用路线法四项】${t.题}`);
  L.push(`日主：${t.日主五行}　用神：${t.用神五行 ?? '（未定）'}（${t.用神来源}）`);
  L.push(`宫位分量序：${t.宫位分量序.join(' ＞ ')}　|　${t.作用力度}`);
  if (t.适用前提) L.push(`适用前提：${t.适用前提}`);
  if (t.主要矛盾) {
    const m = t.主要矛盾;
    L.push('');
    L.push('【主要矛盾 → 用神】（用神有多名候选，谁解决主要矛盾谁当家）');
    L.push(`　① 先保命：${m.一_先保命}`);
    if (m.官杀吉凶) {
      const g = m.官杀吉凶;
      L.push(`　　【官杀吉凶】${g.有官杀 ? `有官杀（${g.官杀五行}）落点 ${g.落点.join('、')}；力度【${g.力度档}】；日主担力 **${g.日主担力}**（${g.担力据}）` : ''}`);
      L.push(`　　　${g.判}`);
      if (g.时上一位贵) L.push(`　　　时上一位贵：${g.时上一位贵.成立否 ? '**成立**' : '不成立'}（${g.时上一位贵.条件 ?? g.时上一位贵.说明}）`);
    }
    L.push(`　② 主要矛盾：${m.二_主要矛盾}`);
    L.push(`　③ 次要矛盾：${m.三_次要矛盾}`);
    for (const c of m.四_候选用神) L.push(`　④ 候选：${c.路线} → **${c.字或五行}**（${c.说明}）`
      + (c.可行 === true ? '　✅ 可行' : c.可行 === false ? '　⚠ **不可行**' : '')
      + (c.可行性 ? `｜${c.可行性}` : ''));
    if (m.四之二_取用定案) {
      const d = m.四之二_取用定案;
      L.push(`　④之二 取用定案：官杀为 ${d.官杀为}（担力 ${d.官杀担力 ?? '—'}）⇒ ${d.宜}`);
      L.push(`　　　　${d.判}`);
    }
    L.push(`　⑤ ${m.五_判据}`);
  }
  if (t.从格改判) {
    const g = t.从格改判;
    L.push('');
    L.push(`【从格改判】引擎判「${g.成立者.join('、')}」成立`);
    L.push(`　适用性：${g.适用性}`);
    L.push(`　${g.改判}`);
    for (const x of g.所从之势_两说) L.push(`　所从之势（${x.口径}）：**${x.五行}**（${x.值}）`);
    L.push(`　日主特性：${g.日主特性}`);
    L.push(`　⚠ ${g.待核定}`);
  }
  if (t.从儿分析?.属于从儿) {
    L.push('');
    L.push('【从儿格流通与比劫研判】（P-016 判据）');
    L.push(`　结论：${t.从儿分析.综合结论}`);
    L.push(`　比劫判定：【${t.从儿分析.比劫判定.角色}】${t.从儿分析.比劫判定.说明}`);
    L.push(`　流通归宿：${t.从儿分析.流通归宿}`);
    L.push(`　破格检验：印绶【${t.从儿分析.印绶判定.角色}】；官杀【${t.从儿分析.官杀判定.角色}】`);
  }
  if (t.格局成破) {
    const g = t.格局成破;
    L.push('');
    L.push('【子平八格成破救应】（P-021 · D-042 裁定）');
    L.push(`　定格：${g.格局}（格神【${g.格神字}】${g.格神十神}，${g.透干 ? '天干透出' : '月令本气藏伏'}）`);
    L.push(`　研判结论：**【${g.格局} · ${g.状态}】**`);
    if (g.状态 === '成格') L.push(`　成格因：${g.成格因}`);
    if (g.破格因) L.push(`　破格因：${g.破格因}`);
    if (g.救应因) L.push(`　救应因：${g.救应因}`);
    L.push(`　法理出处：${g.法理出处}`);
  }
  const t1 = t.第一_财官威胁;
  const t2 = t.第二_印比有情;
  const t3 = t.第三_用神护卫;
  const t4 = t.第四_结构稳定;
  L.push('');
  L.push('① 财官是否构成威胁');
  L.push(`　官杀：${t1.官杀.安危}`);
  L.push(`　压力：${t1.官杀.压力?.说明 ?? '—'}`);
  L.push(`　财　：${t1.财.安危}`);
  L.push(`　压力：${t1.财.压力说明 ?? '—'}`);
  L.push('');
  L.push('② 印比是否对我有情');
  L.push(`　${t2.结论}`);
  if (t2.与用神的关系) {
    for (const r of t2.与用神的关系) {
      L.push(`　· ${r.五行}（${r.与用神}${r.有情否 ? '／对日主有情' : ''}）落点：`
        + `透干${r.落点层次.透干}、支本气${r.落点层次.支中本气}、支藏${r.落点层次.支中藏干}`
        + `　⇒ ${r.判语短}`);
    }
  }
  L.push('');
  L.push('③ 用神是否有护卫');
  if (t3) {
    L.push(`　安危：${t3.安危}`);
    L.push(`　有效护卫：${t3.有效护卫.length ? t3.有效护卫.map(护名字).join('；') : '无'}`);
    L.push(`　护神自身：${t3.护神自身.有损
      ? t3.护神自身.明细.map((x) => `${x.护神}[${x.受损.join('/')}]`).join('、')
      : '未被冲刑合破牵制'}`);
    if (t.第三之链_护卫链?.全景通路) {
      const p = t.第三之链_护卫链.全景通路;
      L.push(`　全景通路：【${p.状态定性}】（剩余有效路数：${p.剩余有效路数}，替代解：${p.替代解}）`);
      L.push(`　· 隔途通关（${p.隔途.护神}）：${p.隔途.状态}（落点：${p.隔途.落点.join('、') || '无'}）`);
      L.push(`　· 制途护卫（${p.制途.护神}）：${p.制途.状态}（落点：${p.制途.落点.join('、') || '无'}）`);
      if (p.衰竭警报) L.push(`　⚠ ${p.警报说明}`);
    }
    L.push(`　岁运警示：${t3.岁运警示}`);
  } else {
    L.push('　（未声明用神，无法判护卫——请用 --yongshen 声明）');
  }
  L.push('');
  L.push('④ 结构是否稳定');
  L.push(`　${t4.结论}`);
  if (t4.岁运) L.push(`　岁运：${t4.岁运.结论}`);
  if (t4.多重仲裁) {
    const a = t4.多重仲裁;
    L.push('');
    L.push('【干支多重作用力并发仲裁】（D-030 裁定）');
    L.push(`　总评：${a.总评}`);
    for (const z of a.逐支受力) {
      if (z.最终受力 !== '安稳') {
        L.push(`　· ${z.宫位}【${z.字}】受力：**${z.最终受力}**（${z.仲裁依据}）`);
      }
    }
  }
  if (t.承载重估) {
    const z = t.承载重估;
    L.push('');
    L.push('【承载重估】官杀是"贵"还是"杀"，随运而变');
    L.push(`　原局：${z.原局判}（${z.原局据}）`);
    L.push(`　${z.结论}`);
    for (const x of z.逐运) {
      const tag = x.夺根?.有夺根 ? `夺根(${x.夺根.降级定性})` : (x.补根 ? '补根' : (x.补势 ? '仅补势' : '—'));
      L.push(`　· ${x.干支}｜${x.干} ${x.支}｜${tag}（${x.夺根?.有夺根 ? x.夺根.说明 : x.补根据}）⇒ ${x.判.slice(0, 60)}`);
    }
  }
  if (t.相战择优) {
    const z = t.相战择优;
    L.push('');
    L.push(`【相战择优】主要病神＝${z.主要病神}（${z.口径}）`);
    for (const p of z.相战) {
      L.push(`　◆ ${p.相战}（${p.来源}）通关神＝${p.通关神}`);
      for (const m of p.手段) {
        L.push(`　　· ${m.手段} → ${m.五行}${m.在局 ? `｜力度${m.力度档}｜解主矛${m.能否解主要矛盾 ? '是' : '否'}｜新病${Array.isArray(m.会否造成新的更大矛盾) ? m.会否造成新的更大矛盾.join('、') : '否'}` : '｜不在局'} ⇒ ${m.净判}`);
      }
      L.push(`　　⇒ ${p.结论}`);
    }
    L.push(`　★ ${z.总择}`);
  }
  if (t.交叉裁决?.length) {
    L.push('');
    L.push('【交叉裁决】四条参照点不同，同一字角色相反时须并陈：');
    for (const x of t.交叉裁决) L.push(`　· ${x}`);
  }
  // ★（八）结构分析：拆点／犯旺（2026-10-01）—— 使用者须看得见，否则等于没做
  {
    const st = t.第二_印比有情?.结构分析;
    if (st) {
      L.push('');
      L.push('【结构分析 · 拆点】（旧口径的"犯旺"已被 2026-10-04 重定义取代，见 fanwangOf）规格 §一之二（八）——「克用神」本身不是判据，须报四问：');
      L.push(`　① 主要矛盾：${st.主要矛盾.五行}（占 ${st.主要矛盾.占比}%）`
        + (st.次要矛盾 ? `　次要矛盾：**${st.次要矛盾.五行}**（占 ${st.次要矛盾.占比}%）` : '　次要矛盾：未定出'));
      L.push(`　② 支撑点：**${st.支撑点}**（来源：${st.支撑点来源}）`
        + `　落点：${st.支撑点四途.落点.join('、')}　透干：${st.支撑点四途.透干 ? '是' : '否'}`);
      L.push(`　③ 依赖度：${st.依赖度档}`);
      L.push(`　　 据：${st.依赖度据}`);
      L.push(`　④ 拆点：${st.拆点判.态} —— ${st.拆点判.因}`);
      if (st.拆点判.分档据) L.push(`　　 分档据：${st.拆点判.分档据}`);
      L.push(`　　 忌对其制力：${typeof st.支撑点四途.忌对其制力 === 'object'
        ? (st.支撑点四途.忌对其制力.结论 || '').replace(/\*\*/g, '')
        : st.支撑点四途.忌对其制力}`);
      L.push(`　　 柱位旁证：${st.柱位旁证.贴身直克 ? '柱位亦贴身直克' : '柱位不贴身'}`
        + `（⚠ ${st.柱位旁证.注}）`);
      L.push(`　★ 判忌门槛：${st.判忌门槛}`);
      // ★ 全盘判忌扫描：逐字循环只走印比，「克用神者」未必落在印比 ⇒ 必须让使用者看见全盘
      if (Array.isArray(st.全盘判忌) && st.全盘判忌.length) {
        L.push(`　★ 全盘判忌扫描（**印比之外也算**——规格忌神定义"任一十神皆可"）：`
          + `克用神者＝${st.克用神者十神 ?? '（未定）'}`
          + (st.克用神者在印比之外 ? '　⛔ **在印比之外**（逐字循环不覆盖，须由调用方另判）' : '　（在印比之内）'));
        for (const r of st.全盘判忌) {
          L.push(`　　· ${r.十神}${r.五行}｜${r.状态}｜逐字层：${r.逐字层能否判}`);
        }
      }
      if (st.口径矛盾) L.push('　⛔ **口径矛盾**：传入的用神／忌神自相矛盾 ⇒ 按规格（七）2 要求核定，**不得据此判忌**。');
      L.push(`　※ 次要矛盾处理：${st.次要矛盾处理}`);
      L.push(`　※ 未判项（引擎不编造）：${st.未判项.join('；')}`);
      L.push(`　※ 据：${st.据}`);
    }
  }
  L.push('');
  if (t.犯旺) {
    L.push('【犯旺】使用者 2026-10-04 重定义：**旺极之五行被大运／流年冲克**（未给岁运则不报）');
    L.push(`　${t.犯旺.结论}`);
    if (t.犯旺.旺极者?.length) L.push(`　局中旺极者：${t.犯旺.旺极者.join('；')}`);
    L.push(`　※ ${t.犯旺.注}`);
    L.push(`　※ 据：${t.犯旺.据}`);
    L.push('');
  }
  if (t.自合暗合 && t.自合暗合.判定 !== '无暗合') {
    L.push('【干支自合与暗合做功】（P-015 · D-029 裁定）');
    L.push(`　判定：**${t.自合暗合.判定}**`);
    L.push(`　说明：${t.自合暗合.说明}`);
    L.push('');
  }
  if (t.双轨意象 && t.双轨意象.条目数 > 0) {
    L.push('【全干支作用关系 · 双轨意象分析】（D-031 裁定）');
    L.push(`　总评：${t.双轨意象.总评}`);
    for (const r of t.双轨意象.关系条目.slice(0, 8)) {
      L.push(`　· 【${r.类别}】${r.pair} ⇒ **${r.定性}**（${r.依据}）`);
      L.push(`　　应象：${r.动态应象}`);
    }
    L.push('');
  }
  L.push('【禁令】');
  for (const x of t.禁令) L.push(`　· ${x}`);
  L.push('');
  L.push('注：用神未由调用方声明时，本输出按《穷通宝鉴》调候表暂取，**须核定后使用**；'
    + '四条只报关系与路径，不作吉凶判断。');
  return L.join('\n');
}


/* ================================================================== *
 * 二十、体用路线法：宫位权重 · 位置路径 · 四条关键
 * ------------------------------------------------------------------
 * 规格见仓库根 `体用路线法.md`（该文优先级高于工具默认流程）。
 * 本节只生产**事实与关系**，不作吉凶判断。
 *
 * 全部判据建立在一条统一机制上（《滴天髓》通关章／坎离章
 * 「成不独成，而有相持者在」）：
 *   若「克者 → 受克者」之间有一个 X 使「克者生 X、X 生受克者」，
 *   则克者之气被 X **引通**去生受克者 —— **克化为生**，克不到。
 *
 * ★ 与既有 `tongguanOf` 的分工：
 *   `tongguanOf` 只在**五行层面**判（两方占比皆过阈值即取通关神），**完全不看宫位**；
 *   本节按**宫位路径**判：**桥须两头贴身**（见 `proximityOf`）。
 * ================================================================== */

const TP_PILLARS = ['年', '月', '日', '时'];

const 生我者 = (el) => Object.keys(SHENG_MAP).find((k) => SHENG_MAP[k] === el);
const 克我者 = (el) => Object.keys(KE_MAP).find((k) => KE_MAP[k] === el);
const 此字五行 = (ch) => (STEMS.includes(ch)
  ? ELEMENTS[STEM_ELEMENT[STEMS.indexOf(ch)]]
  : ELEMENTS[BRANCH_ELEMENT[BRANCHES.indexOf(ch)]]);
const stemAt = (p) => p.stem ?? STEMS[p.stemIndex];
const branchAt = (p) => p.branch ?? BRANCHES[p.branchIndex];

/**
 * **轴甲 · 宫位分量** —— 该宫位**本身**在局中的轻重（0–1）。
 *
 * 使用者已定两条：「**月令最大，时支其次**」。
 * 余者使用者未逐一列举，据**轴乙**「**贴身力度大，隔位力度低**」推得：
 *   日支与日主**同一柱**（贴身）⇒ 分量高于年支（隔月柱，隔位）；天干整体轻于地支。
 * ⚠ **序关系是判据，具体数值是引擎操作化**（见 `GONG_WEIGHT_NOTE`）。
 * 日干为调用者自身，无分量可言，故为 `null`。
 */
export const GONG_WEIGHT = {
  年干: 0.30, 月干: 0.55, 日干: null, 时干: 0.45,
  年支: 0.40, 月支: 1.00, 日支: 0.70, 时支: 0.80,
};

/** 宫位分量的**序**（判据本身，供断言用）。 */
export const GONG_RANK = ['月支', '时支', '日支', '月干', '时干', '年支', '年干'];

export const GONG_WEIGHT_NOTE =
  '轴甲（宫位分量）：使用者已定「月令最大，时支其次」两条；'
  + '其余位次据轴乙「贴身力度大，隔位力度低」推得（日支与日主同一柱 ⇒ 高于隔位之年支）。'
  + '**序**为判据，**数值**为引擎操作化，待核定。轴乙（作用力度）见 proximityOf。';

/**
 * **轴乙 · 作用力度** —— 一个字对另一个字的力，随**相距几柱**衰减。
 *
 * 使用者：「**贴身力度大，隔位力度低。**」
 *   同柱(0)／邻柱(1) → **贴身**，系数 1.00
 *   隔一柱(2)（如 年↔日）→ **隔位**，系数 0.55
 *   隔两柱(3)（即 年↔时）→ **遥隔**，系数 0.25
 *
 * ★ 本条同时决定**通关神能不能当桥**：**桥须两头贴身**
 *   （通关神与克者柱差 ≤ 1 **且** 与受克者柱差 ≤ 1）。
 *   于是 **年 → 时 之间无论放谁都够不着两头 ⇒ 遥隔永无通关**（然其克力本已最低）。
 *   而「相邻则无中间柱可容」并不排除**同柱**引化：
 *   官在月干、印在月支 → 杀印相生，此即经典「化杀」。
 *
 * @param {string} 宫A 如 '月干' | '日支' | '月'
 * @param {string} 宫B 如 '日干' | '年支'
 */
export function proximityOf(宫A, 宫B) {
  const a = TP_PILLARS.indexOf(String(宫A)[0]);
  const b = TP_PILLARS.indexOf(String(宫B)[0]);
  if (a < 0 || b < 0) throw new Error(`proximityOf: 宫位须以 年/月/日/时 起首，收到「${宫A}」「${宫B}」`);
  const 柱差 = Math.abs(a - b);
  const 档 = 柱差 === 0 ? '同柱' : 柱差 === 1 ? '贴身' : 柱差 === 2 ? '隔位' : '遥隔';
  const 系数 = 柱差 <= 1 ? 1 : 柱差 === 2 ? 0.55 : 0.25;
  return { 宫A, 宫B, 柱差, 档, 系数, 可容中间柱: 柱差 >= 2 };
}

/**
 * 某五行在局中的**全部落点**（宫位级）。
 *
 * `层` 区分：`天干` / `地支本气` / `地支藏干`。
 * 日干是调用者自身，默认排除（`includeDayStem: true` 可取回，用于「日主被克」）。
 * `宫位分量`：天干取轴甲原值；地支本气取原值，**藏干折半**（藏者力减）。
 */
export function occupantsOf(chart, el, opts = {}) {
  const { includeDayStem = false } = opts;
  const out = [];
  for (let i = 0; i < 4; i++) {
    const p = chart.pillars[i];
    const 宫 = TP_PILLARS[i];
    const stem = stemAt(p);
    const branch = branchAt(p);
    if ((includeDayStem || i !== 2) && 此字五行(stem) === el) {
      out.push({
        五行: el, 宫位: `${宫}干`, 柱序: i, 层: '天干', 字: stem,
        宫位分量: GONG_WEIGHT[`${宫}干`],
        性质: i === 2 ? '日主自身' : '透干',
      });
    }
    HIDDEN_STEMS_SPEC[BRANCHES.indexOf(branch)].forEach((h, k) => {
      if (此字五行(h[0]) !== el) return;
      out.push({
        五行: el, 宫位: `${宫}支`, 柱序: i, 层: k === 0 ? '地支本气' : '地支藏干',
        字: branch, 藏: `${h[1]}${h[0]}`,
        宫位分量: Number(((GONG_WEIGHT[`${宫}支`] ?? 0) * (k === 0 ? 1 : 0.5)).toFixed(3)),
        性质: k === 0 ? '本气' : `藏干（${h[1]}${h[0]}）`,
      });
    });
  }
  return out;
}

/** 某五行被**合**（绊）的情况：天干五合与地支六合。 */
export function combinedAwayOf(chart, el) {
  const stems = chart.pillars.map(stemAt);
  const branches = chart.pillars.map(branchAt);
  const 合 = [];
  for (let i = 0; i < 4; i++) {
    for (let j = i + 1; j < 4; j++) {
      const a = stems[i], b = stems[j];
      const hua = STEM_COMBINE[a + b] ?? STEM_COMBINE[b + a];
      if (hua && (此字五行(a) === el || 此字五行(b) === el)) {
        合.push({
          途径: '天干五合', 二宫: `${TP_PILLARS[i]}干${a} — ${TP_PILLARS[j]}干${b}`, 化: hua,
          被合者: 此字五行(a) === el ? `${TP_PILLARS[i]}干${a}` : `${TP_PILLARS[j]}干${b}`,
          注: '合化须看月令与化神是否得地；合而未化则只是"绊住"',
        });
      }
      const a2 = branches[i], b2 = branches[j];
      const hua2 = BRANCH_COMBINE[a2 + b2] ?? BRANCH_COMBINE[b2 + a2];
      if (hua2 && (此字五行(a2) === el || 此字五行(b2) === el)) {
        const 又破 = BRANCH_DESTROY.includes(a2 + b2) || BRANCH_DESTROY.includes(b2 + a2);
        合.push({
          途径: '地支六合', 二宫: `${TP_PILLARS[i]}支${a2} — ${TP_PILLARS[j]}支${b2}`, 化: hua2,
          被合者: 此字五行(a2) === el ? `${TP_PILLARS[i]}支${a2}` : `${TP_PILLARS[j]}支${b2}`,
          注: 又破 ? '⚠ 同一对地支既六合又相破（寅亥、巳申），合与破孰主为**分歧点**' : '合化须看月令与化神是否得地',
          分歧: 又破 || undefined,
        });
      }
    }
  }
  return 合;
}

/** 某字（宫位＋字）在原局关联网络中**受损**的情况。天干与地支各查各的关系桶。 */
function 受损Of(relations, 宫位, 字, 层) {
  const label = `${宫位[0]}${字}`;
  const keys = 层 === '天干'
    ? [['天干五合', '合'], ['天干相冲', '冲'], ['天干相克', '克']]
    : [['地支六合', '合'], ['地支六冲', '冲'], ['地支相刑', '刑'], ['地支相害', '穿'], ['地支相破', '破']];
  const out = [];
  for (const [k, kind] of keys) {
    for (const e of relations[k] ?? []) if (String(e.pair).includes(label)) out.push({ 途: kind, 关系: e.pair });
  }
  return out;
}
const 受损文字 = (arr) => arr.map((x) => `${x.途}（${x.关系}）`);

/**
 * **五行实际力度**（不是"在不在"，而是"有多大"）。
 *
 * 使用者原话：「**能不能制住／化尽／合住，看五行在当月的力量、人元司令、大运配合。**」
 * 故本函数把四样东西合起来给一个**档位**：
 *   ① **月令令态**（最重）——`seasonState`，旺／次旺／相／休／囚／死
 *   ② **人元司令**——该五行是否正是当月**司令之神**（得令之实际体现；四柱模式无时刻，不可计）
 *   ③ **通根透干**——地支本气／中气／余气，与天干透出
 *   ④ **宫位分量**——见 `GONG_WEIGHT`（轴甲）
 *   ⑤ **牵制**——被合冲刑害破（合而未化只是羁绊，见 `canBindOf`）
 *   ⑥ **大运配合**——可传 `岁运` 两字干支
 *
 * ⚠ **不合成单一数值评分**（项目原则：引擎不作吉凶评分），只给**档位 + 逐项依据**。
 * 档位沿用 `tenGodStrength` 的 **极／强／中／弱**，以便两处互相印证。
 *
 * @param {object} chart
 * @param {string} el 五行
 * @param {{岁运?: string}} [opts]
 */
export function powerOf(chart, el, opts = {}) {
  const { 岁运 = null } = opts;
  const pillars = chart.pillars;
  const monthBranch = branchAt(pillars[1]);
  const silingEl = kingOf(chart);           // 人元司令之神；四柱模式为 undefined
  const s = elementStrength(pillars, monthBranch, silingEl);

  const 令态 = s.令态[el];
  const 占比 = s.percent[el];
  const 是司令 = silingEl ? silingEl === el : null;

  const 落点 = occupantsOf(chart, el);
  const 干 = 落点.filter((o) => o.层 === '天干');
  const 本气根 = 落点.filter((o) => o.层 === '地支本气');
  const 中余气根 = 落点.filter((o) => o.层 === '地支藏干');
  const 根 = [...本气根, ...中余气根];

  // 牵制：合冲刑害破
  const 受损 = 落点.map((o) => ({ 落点: `${o.宫位}${o.字}`, 损: 受损Of(relationsOf(pillars), o.宫位, o.字, o.层) }))
    .filter((x) => x.损.length);
  const 被合 = combinedAwayOf(chart, el);

  // 大运／岁运配合
  let 岁运段 = null;
  if (岁运) {
    const gz = String(岁运);
    const si = STEMS.indexOf(gz[0]);
    const bi = BRANCHES.indexOf(gz[1]);
    if (si < 0 || bi < 0 || gz.length !== 2) throw new Error(`powerOf: 岁运须为两字干支，收到「${岁运}」`);
    const 岁运五行 = new Set([此字五行(gz[0]), 此字五行(gz[1])]);
    const 生此者 = 生我者(el);
    const 克此者 = 克我者(el);
    const 补 = [...岁运五行].some((x) => x === el || x === 生此者);
    const 助敌 = [...岁运五行].some((x) => x === 克此者);   // 岁运带克我者 ⇒ 助敌
    岁运段 = {
      干支: 岁运, 岁运五行: [...岁运五行],
      补我: 补, 助我之克者: 助敌,
      说明: 补 && !助敌 ? `岁运${岁运}带${[...岁运五行].join('、')}，**补${el}**（或补其源${生此者}），力度加分。`
        : !补 && 助敌 ? `岁运${岁运}带${[...岁运五行].join('、')}，**不补${el}且助其克者${克此者}**，力度减分。`
          : `岁运${岁运}带${[...岁运五行].join('、')}，与${el}关系平（${补 ? '补我但亦助敌' : '不补我亦不助敌'}）。`,
    };
  }

  // 档位（沿用 tenGodStrength 口径）
  let 档;
  if (是司令 || 令态 === '旺') 档 = 本气根.length ? '极' : '强';
  else if (本气根.length) 档 = 令态 === '相' || 令态 === '次旺' ? '强' : '中';
  else if (干.length || 中余气根.length) 档 = 令态 === '休' || 令态 === '囚' || 令态 === '死' ? '弱' : '中';
  else 档 = '弱';

  const 依据 = [
    `月令${monthBranch}对${el}为「**${令态}**」`,
    是司令 === null ? '**人元司令未计**（四柱模式无出生时刻，只能按月支本气估）'
      : 是司令 ? `**${el}正是当月司令之神**（人元用事）` : `当月司令为${silingEl}，非${el}`,
    `透干 ${干.length ? 干.map((o) => `${o.宫位}${o.字}`).join('、') : '**无**'}`,
    `通根 ${根.length ? 根.map((o) => `${o.宫位}${o.字}${o.藏 ? `(${o.藏})` : ''}·${o.性质}`).join('、') : '**无根**'}`,
    `占比 ${占比}%`,
  ];
  if (受损.length) 依据.push(`被牵制：${受损.map((x) => `${x.落点}←${受损文字(x.损).join('、')}`).join('；')}`);
  if (被合.length) 依据.push(`被合：${被合.map((x) => `${x.被合者}（${x.途径}${x.化 ? '化' + x.化 : ''}）`).join('、')}`);
  if (岁运段) 依据.push(岁运段.说明);

  // 「虚露失垣」：只透干而全无根 —— 《八字提要》「虚露失垣之庚，不能制裁旺盛之木」
  const 虚露失垣 = 干.length > 0 && 根.length === 0;
  // ★★ 源头（2026-10-04 使用者口径）：**无自根 ≠ 无力**——还须看"谁在生它"（生我者）够不够力。
  //   使用者原话：「官有财作为地支的气，如果财旺（位置、力量等等），那么这个官即使地支无根，
  //   那它也是有力量的。其他的十神以此类推」「力量看源头是否有力（源头的宫位、是否被月令支持、
  //   源头数量等等）……宫位力量要去考虑的，比如时支力量也比较高」「综合考虑」。
  //   ⇒「源头有力」＝ 源头**在局有落点** **且**（令态支持 **或** 宫位分量合计够重）。
  //   ⚠ 必须先有"在局"这一条：否则会出现"**水在盘里一个落点都没有，却因酉月金生水而令态得相**"
  //     被判有力——那是虚的（实测：乙酉 己酉 甲戌 庚午 就是此例）。
  //   ⚠ 阈值 0.80 ＝ 一个「时支」的分量（GONG_WEIGHT.时支）——**引擎操作化、且未校准**，
  //     与 60%／15个百分点 同规；不得当作古籍明文。
  const 源头五行 = 生我者(el);
  const 源头落点 = 源头五行 ? occupantsOf(chart, 源头五行) : [];
  const 源头宫位和 = Number(源头落点.reduce((a, o) => a + (o.宫位分量 ?? 0), 0).toFixed(3));
  const 源头令态 = 源头五行 ? s.令态[源头五行] : null;
  const 源头在局 = 源头落点.length > 0;
  const 源头月令支持 = 源头令态 != null && ['旺', '次旺', '相'].includes(源头令态);
  const 源头宫位档 = 源头宫位和 >= 1.2 ? '极' : 源头宫位和 >= 0.8 ? '强' : 源头宫位和 >= 0.5 ? '中' : '弱';
  const 源头有力 = 源头在局 && (源头月令支持 || 源头宫位档 === '强' || 源头宫位档 === '极');
  // ⛔ 唯一会自指的情形：el 正是「日主所生」⇒ 源头即日主本字。此时不递归，只报已算出的档。
  const 源头即日主 = !!源头五行 && 源头五行 === dayMasterOf(chart).element;
  /** 「真正虚浮」＝自无根 **且** 源头亦无力（原 `虚露失垣` 只查自根，会把"有源无根"误杀） */
  const 真正虚浮 = 虚露失垣 && !源头有力;

  return {
    五行: el, 档,
    令态, 是司令之神: 是司令, 月支: monthBranch, 司令五行: silingEl ?? null,
    占比, 透干: 干.map((o) => `${o.宫位}${o.字}`),
    通根: 根.map((o) => `${o.宫位}${o.字}${o.藏 ? `(${o.藏})` : ''}·${o.性质}`),
    本气根数: 本气根.length, 根数: 根.length,
    虚露失垣,
    // ★ 源头一组（使用者 2026-10-04）：自无根时看"谁在生我"
    源头五行, 源头令态, 源头月令支持, 源头宫位和, 源头宫位档, 源头在局, 源头有力, 源头即日主,
    真正虚浮,
    宫位分量合计: Number(落点.reduce((a, o) => a + (o.宫位分量 ?? 0), 0).toFixed(3)),
    被牵制: 受损, 被合,
    岁运: 岁运段,
    依据,
    断语: 档 === '极' || 档 === '强'
      ? `${el}在局中「**${档}**」——有力，可当制／化／合之任。`
      : 档 === '中'
        ? `${el}在局中「**中**」——**力不足以独任**：能起点作用，但不能独当制／化／合之全责。`
        : `${el}在局中「**弱**」——**无力**${真正虚浮
          ? `（**真虚浮**：自无根、源头${源头五行 ?? '—'}亦无力｜宫位和 ${源头宫位和}／令态 ${源头令态 ?? '—'}）`
          : 虚露失垣 ? `（虽**只透干无自根**，但源头${源头五行}**有力**——宫位和 ${源头宫位和}／令态 ${源头令态 ?? '—'}／档 ${源头宫位档}，故**不算虚浮**）` : ''}，不足以制／化／合。`,
    说明: '档位沿用 `tenGodStrength` 之极／强／中／弱口径，便于两处互证。'
      + '**不合成单一数值评分**；月令为大，人元司令为次，通根透干为实，宫位分量与牵制为余。',
    据: '使用者「能不能制住／化尽／合住，看五行在当月的力量、人元司令、大运配合」；'
      + '《三命通会》人元司事；《八字提要》「虚露失垣……不能制」',
  };
}

/**
 * **位置路径**：判「克者」能否**克到**「受克者」。
 *
 * 统一机制：`通关神 X = 生[克者]`，且须 `生[X] === 受克者`。
 * X 只要在局中，且**与克者贴身、又与受克者贴身**（桥须两头够得着），
 * 则该路**克化为生**，克力记 0；否则**直克**。
 *
 * ⚠ 「有桥 ⇒ 克力 0」只解决**安危**；**压力仍在**（护卫 ≠ 化解，见规格 §一之二 ②），
 * 故每路同时报 `压力系数`（纯按宫位分量与距离计，不叠五行力量）。
 *
 * @param {object} chart
 * @param {string} 克者五行 五者之一
 * @param {string} 受克者五行 五者之一
 * @param {object} [opts]
 * @param {string} [opts.克者宫位] 限定克者落点，如 '月干'
 * @param {string} [opts.受克者宫位] 限定受克者落点，如 '日干'
 * @param {boolean} [opts.受克者含日主=true]
 */
export function pathOf(chart, 克者五行, 受克者五行, opts = {}) {
  const { 克者宫位 = null, 受克者宫位 = null, 受克者含日主 = true } = opts;
  const X = SHENG_MAP[克者五行];
  const 通关五行成立 = SHENG_MAP[X] === 受克者五行;
  const 克方 = occupantsOf(chart, 克者五行, { includeDayStem: false }).filter((o) => !克者宫位 || o.宫位 === 克者宫位);
  const 受方 = occupantsOf(chart, 受克者五行, { includeDayStem: 受克者含日主 }).filter((o) => !受克者宫位 || o.宫位 === 受克者宫位);
  const 通方 = 通关五行成立 ? occupantsOf(chart, X, { includeDayStem: false }) : [];

  const 路 = [];
  for (const k of 克方) {
    for (const s of 受方) {
      if (k.宫位 === s.宫位) continue;
      const 两者 = proximityOf(k.宫位, s.宫位);
      const 桥 = [];
      for (const t of 通方) {
        // 桥可以是**同宫之另一字**（如丑中辛金为克者、丑中癸水为桥）：
        // 同支藏干本自相生，故不排除同宫，只排除「桥即克者本身／即受克者本身」的退化情形。
        // ⚠ 地支落点的 `字` 是**支名**，故同一支内不同藏干须以 `藏` 区分，不可只比 `字`+`层`。
        const 键 = (o) => `${o.宫位}|${o.藏 ?? o.字}|${o.层}`;
        if (键(t) === 键(k) || 键(t) === 键(s)) continue;
        const p1 = proximityOf(t.宫位, k.宫位);
        const p2 = proximityOf(t.宫位, s.宫位);
        if (p1.柱差 > 1 || p2.柱差 > 1) continue;
        const 严格居中 = Math.min(k.柱序, s.柱序) < t.柱序 && t.柱序 < Math.max(k.柱序, s.柱序);
        桥.push({
          宫位: t.宫位, 字: t.字, 层: t.层, 藏: t.藏, 宫位分量: t.宫位分量,
          严格居中, 近克者: p1.档, 近受者: p2.档,
          形态: 严格居中 ? '夹在中间'
            : (t.宫位 === k.宫位 || t.宫位 === s.宫位) ? '同宫引化'
              : '贴身引化',
        });
      }
      const 通 = 桥.length > 0;
      const 压力 = Number(((k.宫位分量 ?? 0) * 两者.系数).toFixed(3));
      路.push({
        克者: `${k.宫位}${k.字}`,
        克者层: k.层,
        受克者: `${s.宫位}${s.字}${s.性质 === '日主自身' ? '（日主）' : ''}`,
        受克者层: s.层,
        两者: 两者.档,
        柱差: 两者.柱差,
        直接可克: !通,
        通关神: 通关五行成立 ? X : null,
        桥,
        结论: 通
          ? `${k.宫位}${k.字}(${克者五行})克${s.宫位}${s.字}(${受克者五行})，而${X}在${桥.map((b) => `${b.宫位}${b.字}(${b.形态})`).join('、')}：`
            + `${克者五行}生${X}、${X}生${受克者五行}，**克化为生，克不到**。`
          : `${k.宫位}${k.字}(${克者五行})与${s.宫位}${s.字}(${受克者五行})相距「${两者.档}」，`
            + (通关五行成立
              ? 通方.length ? `局中之${X}（${通方.map((t) => t.宫位).join('、')}）**够不着两头，不成桥**，故**直克**。` : `局中**无${X}**，故**直克**。`
              : `${克者五行}生${X}而${X}不生${受克者五行}，本无通关可言，**直克**。`),
        克力系数: 通 ? 0 : 压力,
        压力系数: 压力,
      });
    }
  }
  return {
    问: `${克者五行}克${受克者五行}`,
    通关神: 通关五行成立 ? X : null,
    通关五行成立,
    克者落点: 克方.map((o) => `${o.宫位}${o.字}${o.藏 ? `(${o.藏})` : ''}`),
    受克者落点: 受方.map((o) => `${o.宫位}${o.字}${o.藏 ? `(${o.藏})` : ''}`),
    通关神落点: 通方.map((o) => `${o.宫位}${o.字}${o.藏 ? `(${o.藏})` : ''}`),
    路,
    有路可直克: 路.some((x) => x.直接可克),
    贴身可直克: 路.some((x) => x.直接可克 && x.柱差 <= 1),
    力弱之直克: 路.filter((x) => x.直接可克 && x.柱差 >= 2).map((x) => `${x.克者}→${x.受克者}（${x.两者}，系数${x.克力系数}）`),
    // ★ 桥不是"有个字就算"——该字自己有没有力，见 powerOf（使用者：看当月力量、人元司令、大运配合）
    通关神力度: 通关五行成立 ? powerOf(chart, X) : null,
    威胁判据: '**贴身直克（柱差 ≤ 1）方计为构成威胁**；隔位／遥隔之直克力弱，另列 `力弱之直克`，'
      + '是否作威胁须调用方按本派定（使用者：「贴身力度大，隔位力度低」）。',
    说明: '「克力系数」是有桥时记 0（克化为生）后的值；「压力系数」始终保留——'
      + '**护卫 ≠ 化解**：有护卫则不怕被克，但压力仍须待岁运的通关之神到位方能消除（规格 §一之二 ②）。'
      + '两系数**只按宫位分量与距离计**，不叠五行力量。'
      + '⚠ 桥的形态分三种：**夹在中间**（克者与受克者之间确有中宫）、**贴身引化**（桥与两者皆邻柱）、'
      + '**同宫引化**（桥与克者同处一支，如申中庚金为克者而同支壬水为桥——人元之间本自相生）。'
      + '一说「同宫引化」力薄、不当作全化；本引擎仍记其克力为 0，但**同时给出压力系数**，'
      + '由调用方按本派取舍（分歧并陈，不选边）。',
    据: '《滴天髓》通关章／坎离章「成不独成，而有相持者在」；规格 §一之三',
  };
}

/* ------------------------------------------------------------------ *
 * 二十之一、四象配五行 · 十二月配象（两系并列）· 「有救」的阈值
 *   全部经古籍检索落实，凡未检得者明写"未检得"，凡两说并存者并列不调和。
 * ------------------------------------------------------------------ */

/**
 * **太少四象 → 五行**（三书一致，可直接引用）。
 *   水＝太阴／火＝太阳／木＝少阳／金＝少阴／**土＝阴阳老少冲气所结，不入四象**。
 */
export const SI_XIANG_WUXING = { 水: '太阴', 火: '太阳', 木: '少阳', 金: '少阴', 土: '冲气所结（不入四象）' };

export const SI_XIANG_YUAN = {
  主要: '《命理探源》袁树珊（转引山阴沈孝瞻《子平真诠》）：「有老少，遂分四象。老者极动静之时，是为太阳太阴；'
    + '少者初动初静之际，是为少阴少阳。有是四象，而五行具于其中矣。**水者，太阴也；火者，太阳也；木者，少阳也；'
    + '金者，少阴也；土者，阴阳老少、木火金水冲气所结也。**」',
  旁证一: '《古法三命·五行精纪》（引《广录》）：「火為太陽……木為少陽……水為太陰……金為少陰……**土無常性，視四時所乘**」',
  旁证二: '《千里命稿》韦千里：金「**属少阴**」、木「**属少阳**」、水「**属太阴**」、火「**属太阳**」、'
    + '「**土无常性，视四时所乘**」',
  名目差异: '★《子平真诠》（转引）与《白虎通》用「**太阳／太阴**」；《盲派与象法》用「**老阳／老阴**」。'
    + '二者所指同位（老者＝极＝太＝老），**名目不同而实指一**。',
  反对说: '★《太极图说与易图明辨》胡渭：「**易有四象而無五行**」——'
    + '易学系统内「四象」是蓍策过揲之数（九六七八），与五行无涉。'
    + '故「太少配五行」属**另一系统（《月令》—郑玄—沈孝瞻）**，**不能以《易》为据**（胡渭述郑玄「以木火金水为四象实本于此（《月令》）」）。',
};

/**
 * **十二月配象**——古籍有**两套法，方向部分相反，并列不调和**。
 */
export const SI_XIANG_MONTH_SYSTEMS = {
  法一_白虎通系: {
    名称: '《白虎通》系（每象各据三支）',
    据: '《命理探源》袁树珊（转引《五行大义》所引《白虎通》）：「**少阳见于寅，盛于卯，衰于辰**……'
      + '**太阳见于巳，壮盛于午，衰于未**……**少阴见于申，壮于酉，衰于戌**……**太阴见于亥，壮于子，衰于丑**」',
    少阳: ['寅', '卯', '辰'], 太阳: ['巳', '午', '未'], 少阴: ['申', '酉', '戌'], 太阴: ['亥', '子', '丑'],
  },
  法二_盲派系: {
    名称: '《盲派与象法》系（寅申各只一月；卯酉辰戌另立名目）',
    据: '《盲派与象法》：「十二月阴阳按"**老阴（亥子丑）→少阳（寅）→阴阳同旺（卯）→交接（辰）→'
      + '老阳（巳午未）→少阴（申）→阴阳同旺（酉）→交接（戌）**"循环」',
    老阴: ['亥', '子', '丑'], 少阳: ['寅'], 阴阳同旺: ['卯', '酉'], 交接: ['辰', '戌'],
    老阳: ['巳', '午', '未'], 少阴: ['申'],
  },
  一致之处: '两法**皆以「寅＝少阳」「申＝少阴」**；差别在：法一每象各铺三支（卯酉辰戌各有归属），'
    + '法二只给寅申为「少」，卯酉辰戌另立「阴阳同旺／交接」之名。',
  冲突: '★ **申月之义两说相反**：法一作「**少阴见于申**」（阴之始生，其日庚辛属金）；'
    + '法二作「申月｜**老阳向少阴转化，先天阳旺**｜**以阳为体**」，且该派主张「**阳旺用阴**」⇒ **申月取阴**。'
    + '规格 §5.3 已裁定取法一，并判法二"不适用"；此处只**并陈**，引擎不代判。',
};

/**
 * 由月支查四象：**两套法并列返回**，并标出一致与冲突之处。
 * @param {string} monthBranch 月支，如 '申'
 */
export function siXiangOf(monthBranch) {
  const b = String(monthBranch);
  const find = (sys) => Object.entries(sys).find(([k, v]) => Array.isArray(v) && v.includes(b));
  const 一 = find(SI_XIANG_MONTH_SYSTEMS.法一_白虎通系);
  const 二 = find(SI_XIANG_MONTH_SYSTEMS.法二_盲派系);
  const 象名 = (x) => (x ? x[0].replace(/_/g, '') : null);
  const 一致 = !!一 && !!二 && 象名(一) === 象名(二);
  return {
    月支: b,
    法一: { 象: 象名(一), 据: SI_XIANG_MONTH_SYSTEMS.法一_白虎通系.据 },
    法二: { 象: 象名(二), 据: SI_XIANG_MONTH_SYSTEMS.法二_盲派系.据 },
    两法一致: 一致,
    五行: { 说明: `四象→五行：${Object.entries(SI_XIANG_WUXING).map(([k, v]) => `${v}＝${k}`).join('、')}`,
      据: SI_XIANG_YUAN.主要, 反对说: SI_XIANG_YUAN.反对说 },
    结论: 一致
      ? `两法皆以${b}为「**${象名(一)}**」；据《命理探源》四象配五行，${象名(一)}＝**${Object.keys(SI_XIANG_WUXING).find((k) => SI_XIANG_WUXING[k] === 象名(一))}**。`
      : `★ **两法不一致**：法一作「${象名(一) ?? '（不属）'}」，法二作「${象名(二) ?? '（不属）'}」。`
        + `**并列，不调和**——须由调用方声明采用哪一派。`,
    未检得: [
      '「老少相配」连语——**未检得**',
      '「少阴喜老阳」／「少阴喜老阳平衡」——**未检得**（全库 grep 无命中）',
      '「孤阴不生，独阳不长」八字连语——**未检得**（仅见「孤阳失辅」，义为丙火无壬水，非四象老少）',
    ],
    说明: '四象配十二月有**两套法**，本函数**并列返回**；'
      + '四象配五行有**三书一致**之据，但另有《易图明辨》「易有四象而无五行」之**否认说**，一并附上。',
    据: '《命理探源》《五行精纪》《千里命稿》《盲派与象法》《太极图说与易图明辨》；'
      + '检索报告见 `体用路线法.md` §八',
  };
}

/**
 * **根之轻重** —— 《子平真诠》给出的**唯一可折算的层级**（《滴天髓》同）。
 *
 * > 《子平真诠》：「得一比肩，**不如得支中一墓库**（如甲逢未、丙逢戌）……
 * > 得二比肩，**不如得一余气**（如乙逢辰、丁逢未）……
 * > 得三比肩，**不如得一长生禄刃**（如甲逢亥子寅卯）」；「**干多不如根重**」
 * > （比劫如朋友相扶，通根如室家可住）。
 *
 * ⇒ 序：**天干一比肩 ＜ 地支一余气墓库 ＜ 天干二比肩 ＜ 地支一长生禄旺**。
 *
 * ⚠ **此序有反对说，须并陈**：
 *   · 《穷通宝鉴》「**透干为上，藏支为中**」（与"干多不如根重"方向相反）；
 *   · 《御定子平》八宫中「虽透出一字**不论**，只以乘气为主」（透干分量＝0）；
 *   · 《神峰通考·骨髓歌》「**四柱无根，得时为旺**」（无根亦可因得时而旺）。
 *
 * @param {object} chart
 * @param {string} el 五行
 */
export function genWeightOf(chart, el) {
  const 落点 = occupantsOf(chart, el);
  const 干 = 落点.filter((o) => o.层 === '天干');
  const 本气 = 落点.filter((o) => o.层 === '地支本气');
  const 中余 = 落点.filter((o) => o.层 === '地支藏干');
  const stages = 本气.concat(中余).map((o) => ({
    宫位: o.宫位, 字: o.字, 藏: o.藏, 层: o.层,
    十二宫: elementBranchStage(el, BRANCHES.indexOf(o.字)),
  }));
  const 长生禄旺 = stages.filter((x) => ['长生', '临官', '帝旺'].includes(x.十二宫));
  const 墓库 = stages.filter((x) => x.十二宫 === '墓');
  const 档 = 长生禄旺.length ? '重（有长生／禄／刃）'
    : 本气.length ? '重（本气根）'
      : 中余.length ? '轻（仅余气墓库）'
        : 干.length ? '**仅虚露**（有透无根，效力几等于无）'
          : '**无根**';
  return {
    五行: el,
    透干数: 干.length, 本气根数: 本气.length, 中余气根数: 中余.length,
    透干: 干.map((o) => `${o.宫位}${o.字}`),
    本气根: 本气.map((o) => `${o.宫位}${o.字}`),
    中余气根: 中余.map((o) => `${o.宫位}${o.字}${o.藏 ? `(${o.藏})` : ''}`),
    长生禄旺: 长生禄旺.map((x) => `${x.宫位}${x.字}·${x.十二宫}`),
    墓库: 墓库.map((x) => `${x.宫位}${x.字}`),
    根之轻重: 档,
    序: '天干一比肩 ＜ 地支一余气墓库 ＜ 天干二比肩 ＜ 地支一长生禄旺',
    据: '《子平真诠》「得一比肩，不如得支中一墓库……得三比肩，不如得一长生禄刃」「**干多不如根重**」；'
      + '《滴天髓》「天干得一比肩 ＜ 地支得一余气墓库；得二比肩 ＜ 支中得一长生禄旺」',
    反对说: [
      '《穷通宝鉴》「**透干为上，藏支为中**」——与"干多不如根重"**方向相反**',
      '《御定子平》「八宫中虽透出一字**不论**，只以乘气为主」——透干分量＝0',
      '《神峰通考·骨髓歌》「**四柱无根，得时为旺**」——无根亦可因得时而旺',
    ],
    未检得: '任何一书把「有根／透干／得地」三者并列后给出**权重、成数或百分比**——**未检得**；'
      + '库中三者只以**序关系**（如上）或**分档**（《千里命稿》最强／中强／次强）出现。',
  };
}

/**
 * **「有救」的阈值** —— 规格 6.3 只给了定性（有根／透干／得地），未定权重。
 *
 * 古籍检索结论（见 `genWeightOf`）：**库内无权重数值，只有序关系**。
 * 故本函数：
 *   ① 按可引的**序关系**给档：**得令 ＞ 得地 ＞ 透干**（并附《千里命稿》分档）；
 *   ② 凡有反对说者**一律并陈**，不静默取一。
 *
 * @param {object} chart
 * @param {string} el 待判之五行（通常为用神）
 */
export function youJiuOf(chart, el) {
  const g = genWeightOf(chart, el);
  const p = powerOf(chart, el);
  const 有根 = g.本气根数 + g.中余气根数 > 0;
  const 透干 = g.透干数 > 0;
  // 序：得令 ＞ 得地（有根）＞ 透干 —— 见《千里命稿》最强／中强／次强三档
  const 档 = (['旺', '次旺'].includes(p.令态) && 有根) ? '最强（当令又多帮扶）'
    : (有根 && !['旺', '次旺', '相'].includes(p.令态)) ? '次强（不当令而得地）'
      : (!有根 && 透干) ? '**虚露**（有透无根，效力几等于无）'
        : (!有根 && !透干) ? '**无救**（不现于局）'
          : '中强（得令而少帮扶）';
  const 有序 = 有根 || 透干;
  return {
    五行: el,
    档,
    有救: 有序,
    得令: ['旺', '次旺'].includes(p.令态),
    令态: p.令态,
    得地: 有根,
    透干,
    根之轻重: g,
    序关系: '**得令 ＞ 得地（有根）＞ 透干**；且有根之内再分：**长生禄旺 ＞ 墓库余气**',
    分档据: '《千里命稿》「身强之构成：得时（月令）、得势（党众）、得地（通根）」；'
      + '又分「最强＝既当令又多帮扶／中强＝仅多帮扶而失令 或 仅得令而少帮扶／次强＝不当令又少帮扶但年日时支得气」',
    结论: 档.startsWith('最强') ? `**有救且有力**：${el}当令又有根（${g.根之轻重}）。`
      : 档.startsWith('次强') ? `**有救**：${el}虽不当令，但**得地**（${g.根之轻重}）——按《千里命稿》属"次强"，` 
        + `**生月不值令而年时值禄旺，不可便作衰看**。`
        : 档.startsWith('中强') ? `**有救但力减**：${el}得令而少帮扶。`
          : 档.startsWith('**虚露**') ? `**救而无力**：${el}只透干无根——`
            + `《八字提要》「大凡所喜之神，**必欲通根得地方佳，否则效力几等于无**」。`
            : `**无救**：${el}不现于局——须待岁运补。`,
    反对说: [
      '《穷通宝鉴》「**透干为上，藏支为中**」——若从此说，则"透干"一档须**上提**至有根之上',
      '《神峰通考·骨髓歌》「**四柱无根，得时为旺**」——若从此说，则"虚露"亦可因得时而作旺论',
      '《御定子平》「八宫中虽透出一字不论」——若从此说，则"透干"一档**分量为零**',
    ],
    说明: '★ **库内无权重数值，只有序关系**——规格 6.3 若要定权重，**古籍无据可依**，'
      + '故本函数**只给序与档，不给数字**，并把三处反对说一律并陈。',
    据: '《子平真诠》《滴天髓》《千里命稿》《八字提要》《穷通宝鉴》《神峰通考》《御定子平》；'
      + '检索报告见 `体用路线法.md` §八',
  };
}

/**
 * **能否制住** —— 使用者：「能不能**制住**……看五行在当月的力量、人元司令、大运配合。」
 *
 * "有制神"不等于"制得住"。逐条判，每条带可复核出处：
 *
 * | # | 判据 | 出处（原文） |
 * |---|---|---|
 * | 1 | 制者须**有根**；只透无根＝**虚露失垣**，不能制 | 《八字提要》「虚露失垣之庚，**不能制**裁旺盛之木」 |
 * | 2 | 原局**无根**者，岁运逢之亦**不能制** | 《神峰通考》「四柱中**原无一点金气，虽逢金亦不能制，根在苗先**」 |
 * | 3 | 制者**休囚死**则力不足 | 月令令态（人元司令在内） |
 * | 4 | **势不敌则反克**：被制者远强于制者 | 《神峰通考》「**木多金少，不能制伏**」；《八字提要》B13「火旺可制水」 |
 * | 5 | **湿土不能制水**：辰丑不作戊论，惟戌与戊同功 | 《造化元钥》「辰丑皆湿土，**不能制水**……**惟戌与戊土同功**」 |
 * | 6 | 制者自身**被合**则制之不成 | 《御定子平》「凡合者，遇岁运不能伤克」 |
 * | 7 | 被制者**被合住**则岁运的制神**制不了它** | 《御定子平》「偏官**无故而合**，逢食运食岁，**食不能制**也。**遇制不制，反受其殃**」 |
 * | 8 | 制**太过**（尽法无民）与**不及**（奴欺主）皆非 | 《神峰通考》「擒制**太过，则为尽法无民**……擒制之**不及，则奴欺主**矣」 |
 *
 * @param {object} chart
 * @param {string} 制者五行
 * @param {string} 被制者五行
 * @param {{岁运?: string}} [opts]
 */
export function canControlOf(chart, 制者五行, 被制者五行, opts = {}) {
  const { 岁运 = null } = opts;
  const Z = 制者五行, T = 被制者五行;
  if (KE_MAP[Z] !== T) throw new Error(`canControlOf: ${Z}并不克${T}（${Z}所克为${KE_MAP[Z]}）`);

  const pz = powerOf(chart, Z, { 岁运 });
  const pt = powerOf(chart, T);
  const pillars = chart.pillars;
  const 落 = occupantsOf(chart, Z);
  const checks = [];
  const 加 = (名, 过, 说, 据) => checks.push({ 判据: 名, 通过: 过, 说明: 说, 据 });

  // 1 / 2 有根
  const 在局 = 落.length > 0;
  加('制者在局', 在局, 在局 ? `${Z}落点：${pz.透干.concat(pz.通根).join('、')}` : `局中全无${Z}`, '《神峰通考》「根在苗先」');
  加('制者有根（非虚露失垣）', !pz.真正虚浮,
    pz.真正虚浮 ? `${Z}**只透干而全无根**、且**源头${pz.源头五行 ?? '—'}亦无力**（真虚浮）⇒ **不能制**`
      : pz.虚露失垣
        ? `${Z}虽只透干无自根，但**源头${pz.源头五行}有力**（宫位和 ${pz.源头宫位和}／令态 ${pz.源头令态 ?? '—'}）⇒ 非虚浮，**可制**`
        : `${Z}通根 ${pz.根数} 处`,
    '《八字提要》「虚露失垣之庚，不能制裁旺盛之木」＋ 使用者 2026-10-04「无根但源头有力者，不算虚浮」');

  // 3 令态
  const 得令 = ['旺', '次旺', '相'].includes(pz.令态);
  加('制者得令', 得令,
    `月令${pz.月支}对${Z}为「${pz.令态}」${pz.是司令之神 ? '，且**正是当月司令之神**（人元用事）' : pz.是司令之神 === null ? '（**人元司令未计**：四柱模式无时刻）' : ''}`,
    '人元司令；月令为大');

  // 4 势不敌（反克）—— 阈值 15 个百分点为引擎操作化
  const 差 = Number((pt.占比 - pz.占比).toFixed(1));
  const 势不敌 = 差 >= 15;
  const 临界 = 差 >= 8 && 差 < 15;
  加('势足以敌（不被反克）', !势不敌,
    `被制者${T}占 ${pt.占比}%，制者${Z}占 ${pz.占比}%（差 ${差} 个百分点）`
    + (势不敌 ? ' ⇒ **势不敌**，不但不能制，**反被反克**'
      : 临界 ? ' ⇒ 势可相敌，但**已近临界**（阈值 15 个百分点，为引擎操作化），两说宜并陈'
        : ' ⇒ 势可相敌'),
    '《神峰通考》「木多金少，不能制伏」；《八字提要》B13「火旺可制水」（阈值 15% 为引擎操作化）');

  // 5 湿土不能制水
  let 湿土忌 = false;
  if (Z === '土' && T === '水') {
    const 燥 = 落.some((o) => (o.层 === '天干' && o.字 === '戊') || (o.层 !== '天干' && ['戌', '未'].includes(o.字)));
    const 湿 = 落.some((o) => o.层 !== '天干' && ['辰', '丑'].includes(o.字));
    湿土忌 = 湿 && !燥;
    加('土能制水（非湿土）', !湿土忌,
      湿土忌 ? `${Z}只见于辰／丑（**湿土**）且无戊透、无戌未 ⇒ **不能制水**`
        : 燥 ? `${Z}有戊透或戌未（燥土）⇒ 可制水` : `${Z}非仅辰丑之湿土`,
      '《造化元钥》「辰丑皆湿土，不能制水……惟戌与戊土同功」');
  }

  // 6 制者自身被合：**全部落点被合**才是致命；部分被合只打折
  const 制者被合 = combinedAwayOf(chart, Z);
  const 制者未合落点 = 落.filter((o) => o.层 !== '地支藏干'
    && !制者被合.some((x) => x.被合者 === `${o.宫位}${o.字}`));
  const 制者全合 = 落.some((o) => o.层 !== '地支藏干') && 制者未合落点.length === 0;
  加('制者未被合住', !制者全合,
    制者被合.length
      ? `${Z}被合：${制者被合.map((x) => `${x.被合者}（${x.途径}${x.化 ? '化' + x.化 : ''}）`).join('、')}`
        + (制者全合 ? ' ⇒ **制者全部落点被合，制之不成**'
          : ` ⇒ 尚有未合之落点（**${制者未合落点.map((o) => `${o.宫位}${o.字}`).join('、')}**），**制力须打折**`)
      : `${Z}未被合`,
    '《御定子平》「凡合者，遇岁运不能伤克」');

  // 7 被制者被合住 ⇒ 岁运之制反不能施
  const 被制者被合 = combinedAwayOf(chart, T);
  const 被制者主要落点 = occupantsOf(chart, T).filter((o) => o.层 !== '地支藏干');
  const 被制者全合 = 被制者主要落点.length > 0
    && 被制者主要落点.every((o) => 被制者被合.some((x) => x.被合者 === `${o.宫位}${o.字}`));
  加('被制者未被合住', !被制者全合,
    被制者被合.length
      ? `${T}被合：${被制者被合.map((x) => `${x.被合者}（${x.途径}${x.化 ? '化' + x.化 : ''}）`).join('、')}`
        + (被制者全合 ? ' ⇒ **被合住的忌神，岁运的制神制不了它**（"遇制不制，反受其殃"）'
          : ' ⇒ 尚有未合之落点，岁运之制仍可施于未合者')
      : `${T}未被合`,
    '《御定子平》「偏官无故而合，逢食运食岁，食不能制也。遇制不制，反受其殃」');

  // 8 制过 / 不及
  const 制过 = (pz.档 === '极' || pz.档 === '强') && pt.档 === '弱' && pt.根数 === 0;
  const 不及 = pz.档 === '弱' || pz.档 === '中' || !得令;
  const 程度 = 制过 ? '制过（尽法无民）' : 不及 ? '制之不及（奴欺主）' : '制得其宜';
  加('制得其宜（不过不不及）', !制过 && !不及,
    `制者档「${pz.档}」（令态「${pz.令态}」），被制者档「${pt.档}」 ⇒ **${程度}**`,
    '《神峰通考》「擒制太过，则为尽法无民……擒制之不及，则奴欺主矣」');

  const 硬伤 = checks.filter((x) => !x.通过);
  // 致命＝「在局／有根／势可敌／非湿土／制者全被合／被制者全被合」
  //   末一条据《御定子平》：「偏官无故而合，逢食运食岁，**食不能制也**」——
  //   忌神既被合住，制神便够不着它（此与"合是否为我所用"是两个问题）。
  const 致命 = 硬伤.filter((x) => [
    '制者在局', '制者有根（非虚露失垣）', '势足以敌（不被反克）', '土能制水（非湿土）',    '制者未被合住', '被制者未被合住',
  ].includes(x.判据));
  const 结论 = !硬伤.length
    ? `**能制住**：${Z}制${T}，判据皆过，制得其宜。`
    : 致命.length
      ? `**不能制**：${致命.map((x) => x.说明).join('；')}。`
      : `**制而不足**：${硬伤.map((x) => `${x.判据}不合——${x.说明}`).join('；')}`
        + ` ⇒ **有制之名而无制之实**，须并陈两说。`;

  return {
    问: `${Z}能否制住${T}`,
    制者: pz, 被制者: pt, checks, 结论,
    致命伤: 致命.map((x) => x.判据),
    程度,
    说明: '「在局且有根」是前提（"根在苗先"：**原局无根者，岁运逢之亦不能制**）；'
      + '「势不敌」与「湿土」是硬伤；「制过／不及」是分寸。'
      + '**引擎只报能否，不替调用方裁定该不该制。**',
    据: '使用者「能不能制住……看五行在当月的力量、人元司令、大运配合」；'
      + '《神峰通考》《八字提要》《造化元钥》《御定子平》',
  };
}

/**
 * **能否化尽** —— 使用者：「能不能……**化尽**……看五行在当月的力量、人元司令、大运配合。」
 *
 * | # | 判据 | 出处（原文） |
 * |---|---|---|
 * | 1 | **得时者为真化，失令者为假化** | 《命理探源》「化气有得时失令之不同……得时者为真化，失令者为假化」 |
 * | 2 | **化神贵生旺，忌死绝** | 《命理约言》「不特化神贵生旺，忌死绝」 |
 * | 3 | 四柱**无克化神者** | 《千里命稿》「时在仲秋，化神得令，**四柱无火之克破**」 |
 * | 4 | **真化而经破伤者，不啻真化**（盗泄／损伤） | 《命理探源》「暗地化金，**盗泄土气**……暗地化木，**损伤土质**」 |
 * | 5 | 地支**互相冲掣则不成化局** | 《命理约言》「四支虽皆土气，然**互相冲掣，不成化局**」 |
 * | 6 | **岁运之合不作化** | 《千里命稿》「如甲日逢己运或己岁，应以**正财**论，**不作化土论**」 |
 * | 7 | **宾主**：日干逢合可化，他干逢合不能化 | 《千里命稿》「日干逢合则可化……他干逢合不能化」 |
 *
 * @param {object} chart
 * @param {string} 化神五行 合化后所成之五行
 * @param {{岁运?: string, 日干逢合?: boolean}} [opts] `日干逢合` 由调用方声明宾主
 */
export function canTransformOf(chart, 化神五行, opts = {}) {
  const { 岁运 = null, 日干逢合 = null } = opts;
  const H = 化神五行;
  const pH = powerOf(chart, H, { 岁运 });
  const pillars = chart.pillars;
  const monthBranch = branchAt(pillars[1]);
  const s = elementStrength(pillars, monthBranch, kingOf(chart));
  const checks = [];
  const 加 = (名, 过, 说, 据) => checks.push({ 判据: 名, 通过: 过, 说明: 说, 据 });

  // 1 得时 / 失令 —— 以《命理探源》所列「化神得时之月」（三合局月 + 正月）为准
  const 化时月 = {
    木: ['亥', '卯', '未', '寅'],
    火: ['寅', '午', '戌'],
    土: ['辰', '戌', '丑', '未'],
    金: ['巳', '酉', '丑'],
    水: ['申', '子', '辰'],
  };
  const 得时 = (化时月[H] ?? []).includes(pH.月支);
  const 令态旁证 = ['旺', '次旺', '相'].includes(pH.令态);
  加('化神得时（真化）', 得时,
    `月令${pH.月支}${得时 ? '**属**' : '**不属**'}化${H}之得时月（${(化时月[H] ?? []).join('、')}）；`
    + `令态旁证：${H}在${pH.月支}为「${pH.令态}」（${令态旁证 ? '得气' : '失气'}）；`
    + `${pH.是司令之神 === null ? '**人元司令未计**（四柱模式无时刻）' : pH.是司令之神 ? '且**正是当月司令之神**' : `当月司令为${pH.司令五行}`}`
    + ` ⇒ **${得时 ? '真化' : '假化'}**`
    + (得时 !== 令态旁证 ? '　⚠ **得时月与令态旁证不一致**，两说宜并陈' : ''),
    '《命理探源》「化土于季月为得时……化木为亥卯未月，及正月，为得时，反此皆为失令。得时者为真化，失令者为假化」');

  // 2 化神有根（★ 2026-10-04 与「制者有根」统一口径：**判据是"真虚浮"，不是"有无自根"**）
  加('化神生旺有根', !pH.真正虚浮,
    pH.真正虚浮 ? `化神${H}只透干无根、且源头亦无力 ⇒ 化而无力`
      : pH.虚露失垣 ? `化神${H}虽只透干无自根，但**源头有力**（宫位和 ${pH.源头宫位和}）⇒ 非虚浮`
        : `化神通根 ${pH.根数} 处`,
    '《命理约言》「化神贵生旺，忌死绝」');

  // 3 无克化神者
  const 克化神者 = 克我者(H);
  const 克神落点 = occupantsOf(chart, 克化神者);
  加('四柱无克化神者', 克神落点.length === 0,
    克神落点.length ? `局中有${克化神者}（${克神落点.map((o) => `${o.宫位}${o.字}`).join('、')}）克化神 ⇒ **不能化气推**`
      : `局中无${克化神者}克化神`,
    '《千里命稿》「化神得令，四柱无火之克破」');

  // 4 盗泄 / 损伤
  const 泄化神者 = SHENG_MAP[H];
  const 泄落点 = occupantsOf(chart, 泄化神者);
  加('无盗泄化神者（真化未经破伤）', 泄落点.length === 0,
    泄落点.length ? `局中有${泄化神者}（${泄落点.map((o) => `${o.宫位}${o.字}`).join('、')}），为化神${H}所生 ⇒ **盗泄化神之气**，属"真化而经破伤"`
      : `局中无${泄化神者}盗泄`,
    '《命理探源》「暗地化金，盗泄土气……损伤土质」');

  // 5 地支互相冲掣 —— 但「合破并见」（寅亥、巳申）本身是分歧点，不可径判"不成化局"
  const r = relationsOf(pillars);
  const 冲掣 = [...(r.地支六冲 ?? []), ...(r.地支相刑 ?? []), ...(r.地支相破 ?? [])]
    .filter((e) => e && e.pair);
  const 合破并见 = 冲掣.filter((e) => (r.地支六合 ?? []).some((h) => h.pair === e.pair));
  加('地支不互相冲掣', 合破并见.length ? null : 冲掣.length === 0,
    冲掣.length
      ? `地支有冲／刑／破 ${冲掣.map((e) => e.pair).join('、')}`
        + (合破并见.length
          ? `，其中 ${合破并见.map((e) => e.pair).join('、')} **既六合又相破**——合与破孰主为**分歧点**，`
            + `故只报"冲掣并见"，**不径判不成化局**`
          : ' ⇒ **四支互相冲掣，不成化局**')
      : '地支无冲刑破',
    '《命理约言》「四支虽皆土气，然互相冲掣，不成化局」；合破并见见 relationsOf 之「地支六合／相破」');

  // 6 岁运之合不作化
  if (岁运) {
    const gz = String(岁运);
    加('岁运之合不作化', true,
      `《千里命稿》明定：日主逢${gz}合，**应以本气（如正财）论，不作化论**`
      + `——故岁运之合**不改原局本体**，只可作"扶助／羁绊"看`,
      '《千里命稿·补充篇·干合而化》「如甲日逢己运或己岁，应以正财论，不作化土论」');
  }

  // 7 宾主
  if (日干逢合 !== null) {
    加('宾主（日干逢合方可化）', 日干逢合 === true,
      日干逢合 ? '**日干逢合** ⇒ 可化（日干为命之主）'
        : '**他干逢合** ⇒ 不能化（他干为命之宾）',
      '《千里命稿》「日干逢合则可化……他干逢合不能化」');
  }

  const 硬伤 = checks.filter((x) => x.通过 === false);
  const 未定 = checks.filter((x) => x.通过 === null);
  const 化名 = !硬伤.length ? (未定.length ? '真化（地支合破并见，待定）' : '真化')
    : 硬伤.some((x) => x.判据 === '四柱无克化神者') ? '必不可化'
      : 硬伤.some((x) => x.判据 === '无盗泄化神者（真化未经破伤）') ? '真化而经破伤'
        : 硬伤.some((x) => x.判据 === '地支不互相冲掣') ? '不成化局（地支冲掣）'
          : 硬伤.some((x) => x.判据 === '化神得时（真化）') ? '假化'
            : '化而无力';
  const 结论 = 化名.startsWith('真化')
    ? `**化尽**：化神${H}得时、有根、无克无泄、地支不冲掣 ⇒ 真化。`
      + (未定.length ? `（地支合破并见，**"合与破孰主"为分歧点**，故保留待定）` : '')
    : 化名 === '假化'
      ? `**化而未尽**（假化）：化神${H}失令 ⇒ 虽合而化气不真，`
        + `**须并陈"行运助化亦能荣达、但此运过后仍不利"两说**（《命理约言》）。`
      : `**不能化尽**（${化名}）：${硬伤.map((x) => x.说明).join('；')}。`
        + `⚠ 此时按《御定子平》：「**干头合而不化者，只做象，不可竟作本体论**」。`;

  return {
    问: `能否化尽为${H}`,
    化神: pH, checks, 结论,
    化名,
    硬伤: 硬伤.map((x) => x.判据),
    待定判据: 未定.map((x) => x.判据),
    三派分歧: {
      得时月: '《命理探源》：化木＝亥卯未月及正月，化火＝寅午戌，化金＝巳酉丑，化水＝申子辰，化土＝季月；**得时为真化**',
      不问月令: '《子平真诠》：**化气唯以日干合月／时干论，不别求月令**',
      指定月: '《御定子平》：丁壬必要逢寅、戊癸必须逢午、乙庚必须逢酉、丙辛必要逢申',
      处理: '**三说并列，不调和**（本引擎按《命理探源》判真／假化，另两说一并在案）。',
    },
    合而不化之处理: 化名.startsWith('真化') ? '已真化，以化神论生克。'
      : '**只作象，不作本体论**——不可把合的两干径当化神五行使用（《御定子平》「甲己只做土象，不可竟作土论」）。',
    说明: '《滴天髓》另有一层：**合而化则有情变为无情，合而不化则有情**——'
      + '故"化尽"未必是好事、"合而不化"未必是坏事，须按日主喜忌定，**引擎不代判**。'
      + '另：`specialGejuOf` 的「化气格」与此函数**同源而异用**——前者判"是否成化气格"（含破败三类），'
      + '后者判"合化能不能化尽"；两者若给出不同答案，**以并陈处理，不互相覆盖**。',
    据: '使用者「能不能……化尽……看五行在当月的力量、人元司令、大运配合」；'
      + '《命理探源》《命理约言》《千里命稿》《御定子平》《滴天髓》',
  };
}

/**
 * **能否合住**（合＝绊）—— 使用者：「能不能……**合住**……」
 *
 * | # | 判据 | 出处（原文） |
 * |---|---|---|
 * | 1 | **合而化**则变本体；**合而不化**则**只是羁绊** | 《滴天髓》「合而能化，喜金则吉；**合而不化反为羁绊**」 |
 * | 2 | 合而不化者**只作象，不可竟作本体论** | 《御定子平》「甲己只做土象，**不可竟作土论**」 |
 * | 3 | ★ **有故而合者反受保护；无故而合者反受其殃** | 《御定子平》「财星**有故而合**，逢劫运劫岁**不能劫**也……偏官**无故而合**，逢食运食岁，**食不能制**也」 |
 * | 4 | **吉神不宜合、凶神宜合** | 《御定子平》「吉神不宜合、凶神宜合」「有故而合最妙、无故作合必伤」 |
 * | 5 | 合住者，**岁运不能伤克** | 《御定子平》「凡合者，遇岁运不能伤克」 |
 *
 * ⚠ 「有故／无故」与「吉神／凶神」**皆属意图与角色判断，须调用方声明**；
 * 未声明时本函数**并陈两说**，不代判。
 *
 * @param {object} chart
 * @param {string} el 被合之五行
 * @param {{有故?: boolean, 吉神?: boolean}} [opts]
 */
export function canBindOf(chart, el, opts = {}) {
  const { 有故 = null, 吉神 = null } = opts;
  const 合 = combinedAwayOf(chart, el);
  if (!合.length) {
    return {
      问: `${el}能否被合住`, 合: [], 结论: `**未合**：局中无以${el}为一方之合，无从谈合住。`,
      说明: '无合则无绊；该五行可自由接受岁运的制／化。', 据: '《御定子平》',
    };
  }
  const 化者 = 合.filter((x) => x.化);
  const checks = [];
  const 加 = (名, 过, 说, 据) => checks.push({ 判据: 名, 通过: 过, 说明: 说, 据 });

  // ★★ 使用者 2026-09-27 更正：「**合不需要完全力量大于对方，合的目的是让他为我所用。**」
  //    故本函数**不以力度大小作门槛**——只把双方力度作信息报出，供参考。
  const p此 = powerOf(chart, el);
  加('合已成立（**不以力度大小为门槛**）', true,
    `${el}参与 ${合.length} 组合：${合.map((x) => `${x.被合者}（${x.途径}${x.化 ? '化' + x.化 : ''}）`).join('、')}。`
    + `**合是"牵住他、让他为我所用"，不是"压住他"**，故不论双方孰强孰弱。`
    + `（参考信息：${el}档「${p此.档}」，占比 ${p此.占比}%——**仅作参考，不参与判定**。）`,
    '使用者「合不需要完全力量大于对方，合的目的是让他为我所用」；'
    + '《御定子平》「凡合者，遇岁运不能伤克」；'
    + '《八字提要》「乙与庚合，**财来就我**」；《千里命稿》「丙运，**合杀最美**，权爵更显」');

  // 合而化 vs 合而不化（只决定"本体是否变"，不决定"合住与否"）
  const 化神评定 = 化者.length ? [...new Set(化者.map((x) => x.化))].map((h) => canTransformOf(chart, h)) : [];
  const 真化 = 化神评定.filter((x) => x.化名.startsWith('真化'));
  加('合而能化（变本体）', 真化.length > 0,
    化者.length
      ? `合化之神：${化神评定.map((x) => `${x.化神.五行}→**${x.化名}**`).join('、')}`
        + (真化.length ? ' ⇒ 化则**变本体**，以化神论生克' : ' ⇒ 未真化，**只作象，不变本体**')
      : '此合无化神（纯绊，不变本体）',
    '《滴天髓》「合而能化……合而不化反为羁绊」；《御定子平》「甲己只做土象，不可竟作土论」');

  // ★ 核心：合的目的＝**为我所用**
  const 为我所用 = 有故 === null ? null : 有故 === true;
  if (为我所用 !== null) {
    加('合是否为我所用', 为我所用,
      为我所用
        ? '**有故而合 ⇒ 为我所用**：逢劫运劫岁**不能劫**（遇劫不劫，**反可增财**），逢食运食岁**不能制** —— **该字被收编，反成我用**'
        : '**无故而合 ⇒ 反受其殃**：遇制不制（岁运的制神制不了它），该字**不受我驱使**',
      '《御定子平》「财星**有故而合**，逢劫运劫岁，不能劫也。**遇劫不劫，反可增财**。'
      + '如偏官**无故而合**，逢食运食岁，食不能制也。**遇制不制，反受其殃**」');
  } else {
    checks.push({
      判据: '合是否为我所用', 通过: null,
      说明: '**未声明，两说并陈**：合之成立**与力度无关**（合本即"牵住"），'
        + '但"牵住之后是为我所用还是反受其殃"须看**有故／无故**——《御定子平》两途方向相反。',
      据: '《御定子平》「有故而合最妙、无故作合必伤」',
    });
  }

  if (吉神 !== null) {
    加('吉神不宜合／凶神宜合', true,
      吉神 ? '此为**吉神** ⇒ 「**吉神不宜合**」，被合则逢吉不为吉' : '此为**凶神** ⇒ 「**凶神宜合**」，被合则**收为我用**，反为好事',
      '《御定子平》「吉神不宜合、凶神宜合」；《滴天髓》「**合官留杀**格：合而不化反喜其合」');
  } else {
    checks.push({
      判据: '吉神／凶神', 通过: null,
      说明: '**未声明，两说并陈**：「吉神不宜合（合则逢吉不为吉）」与「凶神宜合（收为我用）」方向相反。',
      据: '《御定子平》',
    });
  }

  // 合住者不受岁运伤克 —— **无条件成立**，不以真化或力度为条件
  加('合住者岁运不能伤克', true,
    '合既成立，则**该字不再接受岁运的克伤**（与真化与否、力度大小**皆无关**）',
    '《御定子平》「凡合者，遇岁运不能伤克」');

  const 未定 = checks.filter((x) => x.通过 === null);
  const 结论 = 为我所用 === true
    ? `**合住且为我所用**：${el}之合成立 ⇒ 该字**被收编**（逢劫不劫、逢制不制），岁运不能伤克。`
    : 为我所用 === false
      ? `**合住而不为我所用**：${el}之合成立 ⇒ 该字**仍不受我驱使**（遇制不制），`
        + `须防「无故作合必伤」；但**它同样不再接受岁运的克伤**。`
      : `**合已成立（牵住）**，但"为我所用还是反受其殃"**两说并陈**：`
        + `《御定子平》分「有故而合→为我所用、遇劫不劫反可增财」与「无故而合→反受其殃」两途。`
        + `${真化.length ? '' : '另：此合未真化，**只作象，不可竟作本体论**。'}`;
  return {
    问: `${el}能否被合住`,
    合: 合.map((x) => `${x.被合者}（${x.途径}${x.化 ? '化' + x.化 : ''}）`),
    合成立: true,
    为我所用,
    合破并见: 合.filter((x) => x.分歧).map((x) => x.二宫),
    合之明细: 合, 化神评定: 化神评定.map((x) => ({ 化神: x.化神.五行, 化名: x.化名, 结论: x.结论 })),
    双方力度: { 被合者: { 五行: el, 档: p此.档, 占比: p此.占比 }, 参考: '**仅作参考——合不以力度大小为门槛**' },
    checks, 结论, 未定判据: 未定.map((x) => x.判据),
    说明: '★ **合不需要完全力量大于对方，合的目的是让他为我所用**（使用者原话）。'
      + '故三者是**三个独立问题**：①**合住与否**不看力度；②"为我所用／反受其殃"看**有故无故**；'
      + '③"本体是否改变"看**真化与否**。'
      + '此外「逢吉不为吉」（《子平真诠》）与「凡合者遇岁运不能伤克」（《御定子平》）'
      + '是**并存的两说**，方向不同，须并陈，不得径取。',
    据: '使用者「合不需要完全力量大于对方，合的目的是让他为我所用」；'
      + '《御定子平·口授碎金炉》《滴天髓》《八字提要》《千里命稿》',
  };
}

/**
 * **第 1 条 · 财官是否构成威胁**（支持规格 §一之二）。
 *
 * 逐途查四种「不构成威胁」的途径（使用者：「不一定是被克」）：
 *   ① **被阻隔**（通关）→ 走 `pathOf`，桥须两头贴身
 *   ② **被制**（克）→ 局中有无克「克者」之神
 *   ③ **被合**（绊）→ `combinedAwayOf`
 *   ④ **被化** → 即 ① 的特例（克者之气被通关神吸收），不另立
 *
 * ⚠ 财与官**性质不同**：官是**克我**（直克），财是**我克**（属**耗**，非克）。
 *   故财另报「经官之路」——财生官、官若被印引通，则财官之气皆归身（此即
 *   使用者「财官旺，但中间隔印，那财官也不为忌」的确解）。
 *
 * 输出两档（使用者要求）：**①是否构成威胁（安危）** / **②压力大小**。
 */
/**
 * 取日主信息，**缺 `chart.dayMaster` 时自动从 pillars 推导**。
 *
 * 背景（踩过的坑）：`castChart` 产出的 chart 带 `dayMaster` 对象，但引擎另有大量函数
 * 也接受「裸 chart」`{pillars:[...]}`（自检、手工验证脚本、以及 `pillarsMode` 之外的调用方）。
 * 那些函数原先直接读 `chart.dayMaster.element`，**裸 chart 下会抛
 * `Cannot read properties of undefined (reading 'element')`** ——
 * 本轮即因此在 `yongshenArbiterOf` 里静默吞掉了「体用」与「调候」两项。
 *
 * 故统一走本函数：**能算的就自己算，不依赖调用方是否附带 `dayMaster`**。
 */
function dayMasterOf(chart) {
  if (chart?.dayMaster?.element) return chart.dayMaster;
  const p = chart?.pillars?.[2];
  if (!p) throw new Error('dayMasterOf: 无法取日主（chart.pillars[2] 缺失）');
  const si = p.stemIndex ?? STEMS.indexOf(p.stem);
  if (si < 0) throw new Error(`dayMasterOf: 日柱天干「${p.stem}」非法`);
  const el = ELEMENTS[STEM_ELEMENT[si]];
  const mb = chart.pillars[1]?.branch ?? BRANCHES[chart.pillars[1]?.branchIndex];
  return {
    stem: STEMS[si],
    element: el,
    yinYang: STEM_YANG[si] ? '阳' : '阴',
    bornMonthBranch: mb,
    stageInMonth: twelveStage(si, BRANCHES.indexOf(mb)),
    season: seasonState(el, mb, kingOf(chart)),
  };
}

/**
 * 输出两档（使用者要求）：**①是否构成威胁（安危）** / **②压力大小**。
 */
/**
 * `canControlOf` 结论的**判定词**（「能制住」／「不能制」／「制而不足」）——供安危文案取标题。
 * ⚠ 2026-10-05：`结论`（硬伤裁决）与 `程度`（分寸裁决）是**两把尺子**，不得互相充当注脚。
 *   （体检表 R8：旧版把 `程度` 当注脚 ⇒ 出现「制不足（制得其宜）」「制不足（制过（尽法无民））」
 *    这类一句话自相矛盾的文案，实测 105/500＝21%。）
 */
function 制力标题(力) {
  const t = String(力?.结论 ?? '').replace(/\*\*/g, '').split('：')[0].trim();
  return `**${t || '未判'}**`;
}

/** 制力判定的**理由**：优先列致命伤；无致命伤则取结论自陈的理由（截断），**不再用 `程度` 顶替**。 */
function 制力尾部(力) {
  if (Array.isArray(力?.致命伤) && 力.致命伤.length) return `致命伤：${力.致命伤.join('、')}`;
  const s = String(力?.结论 ?? '').replace(/\*\*/g, '');
  const i = s.indexOf('：');
  return (i >= 0 ? s.slice(i + 1) : s).replace(/。$/, '').slice(0, 80);
}

export function threatOf(chart, opts = {}) {
  const { 岁运 = null } = opts;
  const D = dayMasterOf(chart).element;
  const 官 = 克我者(D);
  const 财 = KE_MAP[D];
  const 印 = 生我者(D);
  const 比 = D;
  const 食 = SHENG_MAP[D];
  const monthBranch = branchAt(chart.pillars[1]);
  const s = elementStrength(chart.pillars, monthBranch, kingOf(chart));
  const 占比 = s.percent;

  // 官的直克路：受者限定为「日干」（日主本身）
  const 官路 = pathOf(chart, 官, D, { 受克者宫位: '日干' });
  const 官被制神 = occupantsOf(chart, 食);   // 食伤制官杀
  const 官被合 = combinedAwayOf(chart, 官);
  const 官被制 = 官被制神.length > 0;
  // ★ 「有制神」≠「制得住」：由 powerOf 的三项（月令力量／人元司令／大运配合）判
  const 制力 = 官被制 ? canControlOf(chart, 食, 官, { 岁运 }) : null;
  // ★ 「有合」≠「合得住」：合而未化只是羁绊，无故而合反受其殃
  const 合之力 = 官被合.length ? canBindOf(chart, 官, {}) : null;
  const 制得住 = !!制力 && 制力.结论.startsWith('**能制住**');
  const 合为我用 = !!合之力 && 合之力.为我所用 === true;
  const 合反受殃 = !!合之力 && 合之力.为我所用 === false;
  const 合未定 = !!合之力 && 合之力.为我所用 === null;
  const 通关有力 = 官路.通关神力度 ? ['极', '强'].includes(官路.通关神力度.档) : false;
  const 有桥 = 官路.路.some((x) => x.桥.length);
  const 通关有名无实 = 有桥 && !通关有力;

  const 官威 = {
    五行: 官,
    十神: '官杀',
    性质: '克我',
    直接路: 官路,
    途径: {
      阻隔: 官路.路.some((x) => x.桥.length)
        ? { 有: true, 神: 官路.通关神, 桥: 官路.路.flatMap((x) => x.桥).map((b) => `${b.宫位}${b.字}`).filter((v, i, a) => a.indexOf(v) === i) }
        : { 有: false, 因: 官路.通关五行成立 ? '局中通关神不够两头贴身' : '无通关五行关系' },
      被制: 官被制 ? { 有: true, 神: 食, 十神: '食伤', 落点: 官被制神.map((o) => `${o.宫位}${o.字}${o.藏 ? `(${o.藏})` : ''}`) } : { 有: false, 因: `局中无${食}（食伤）` },
      被合: 官被合.length ? { 有: true, 合: 官被合 } : { 有: false },
    },
    占比: 占比[官],
    令态: s.令态[官],
    司令: s.司令五行,
    制力, 合之力,
  };
      // ⚠ 2026-10-04 使用者裁「折中：桥虚设 ⇒ 判威胁得到，但写明桥力不足」；实测发现该改法有连锁——
  //   它会把规格 §一之二 一之三 839 点名的那张盘（辛卯 癸巳 戊申 壬戌）的官杀也翻成"威胁"，
  //   从而重新触发"自毁"守卫、把规格明令"**不得拒**"的正解拒掉（selftest 当场 5 项失败）。
  //   ⇒ **暂缓实施，待使用者复裁**（见对话中的 12 号问题）。
  // ★ 2026-10-04（使用者裁「折中」）：**报「桥虚设」者，该途不算"有"**（规格 §一之二（七）1），
  //   故桥虚设时仍判「构成威胁」——但论点里**写清"盘里有桥、只是力不足"**。
  官威.构成威胁 = (官路.贴身可直克 || 通关有名无实) && !制得住 && !合为我用;
  官威.安危 = 官威.构成威胁
            ? `**构成威胁**：${[
      通关有名无实 ? `虽有${官路.通关神}为桥，但其力度仅「${官路.通关神力度?.档}」＝**桥虚设**，按规格（七）1「该途**不算有**」` : null,
      官路.贴身可直克 ? `${官}有贴身直克之路` : null,
      制力 && 制力.致命伤.includes('被制者未被合住') ? `**${官}被合住，${食}够不着它**（"食不能制也"）` : null,
      官被制 && !制得住 ? `虽有${食}制之，但${制力标题(制力)}（${制力尾部(制力)}）` : null,
      合反受殃 ? '虽合而**不受我驱使**（"无故作合必伤"）' : null,
        ].filter(Boolean).join('、') || (合未定 ? '合**未定**（合住已成立，"为我所用／反受其殃"须调用方声明有故／无故）' : '局中无制无合')}。`
    : `**不构成威胁**：${[
                  (官路.路.some((x) => x.桥.length) && !通关有名无实) ? `通关（${官路.通关神}引化，**力度够**）` : null,
      制得住 ? `被${食}（食伤）所制，且**制得住**` : null,
      合为我用 ? `被合**合住且收为我用**（逢劫不劫、逢制不制）` : null,
      官路.力弱之直克.length ? `仅有隔位／遥隔之直克（力弱，不计为威胁：${官路.力弱之直克.join('、')}）` : null,
      // ★ 2026-10-05 修正（体检表 R7：旧版 22/500 输出空句「**不构成威胁**：。」）
    ].filter(Boolean).join('、') || '局中无官杀落点，或官杀与日主之间无路径（又不被制、不被合）'}。`;
  // 分歧并陈：制力／合力的判定结果与"有无"层面相反时，必须并陈
  官威.分歧 = [
    制力 && 制力.致命伤.includes('被制者未被合住')
      ? `**忌神被合住 ⇒ 制神够不着**（《御定子平》「偏官无故而合，逢食运食岁，**食不能制也**」）：`
        + `故"有制神"与"制得住"在此盘**并不同真**。` : null,
    官被制 && !制得住 && !(制力 && 制力.致命伤.includes('被制者未被合住'))
      ? `**有制神而制不足**（${制力.程度}）：`
        + `若按"有制神即不为害"一说则官杀不为忌，若按"制不足则奴欺主"一说则官杀仍肆虐。`
        + `**两说并陈，不选边**（《神峰通考》「擒制之不及，则奴欺主矣」）。` : null,
    通关有名无实 ? `**通关有名无实**：${官路.通关神}虽在局为桥，但其力度仅「${官路.通关神力度.档}」，`
      + `**桥虚设**；是否真能"克化为生"须并陈两说。` : null,
    合未定 ? `**合住已成立，但"为我所用还是反受其殃"未定**：合**不以力度大小为门槛**，`
      + `须由调用方声明有故／无故——有故则收为我用，无故则「遇制不制，反受其殃」，**方向相反**。` : null,
  ].filter(Boolean);
  官威.压力 = {
    五行占比: 占比[官],
    月令令态: 官威.令态,
    最大压力系数: 官路.路.length ? Math.max(...官路.路.map((x) => x.压力系数)) : 0,
    说明: `官杀占全局 ${占比[官]}%，月令令态「${官威.令态}」；压力系数为**宫位分量 × 距离**之积（月令最重）。`
      + `**有护卫则不怕被克，但压力仍在**，须待岁运**${印}**到位通关方能化解。（规格 §一之二 ②：护卫 ≠ 化解）`,
    注: '占比与压力系数**不合成单一评分**——引擎不作吉凶评分（项目原则）。两值并陈，供调用方自行权衡。',
  };

  // 财：我克者，属耗；其威胁经官而显
  const 财落点 = occupantsOf(chart, 财);
  const 耗 = 财落点.map((o) => {
    const prox = proximityOf(o.宫位, '日干');
    return { 宫位: o.宫位, 字: o.字, 藏: o.藏, 距日主: prox.档, 柱差: prox.柱差, 耗力系数: Number(((o.宫位分量 ?? 0) * prox.系数).toFixed(3)) };
  }).sort((a, b) => b.耗力系数 - a.耗力系数);
  const 财被制神 = occupantsOf(chart, 比);
  const 财被合 = combinedAwayOf(chart, 财);
  const 财制力 = 财被制神.length ? canControlOf(chart, 比, 财, { 岁运 }) : null;
  const 财制得住 = !!财制力 && 财制力.结论.startsWith('**能制住**');
  const 财威 = {
    五行: 财,
    十神: '财',
    性质: `**我克**（日主${D}克${财}）⇒ 属下**耗**不属下**克**`,
    耗之路径: 耗,
    制力: 财制力,
    途径: {
      阻隔: 官路.路.some((x) => x.桥.length)
        ? { 有: true, 说明: `${官}（官杀）被${官路.通关神}引化 ⇒ ${财}生${官}、${官}生${官路.通关神}、${官路.通关神}生${D}，**财官之气尽归于身**，故财亦不为忌` }
        : { 有: false, 说明: `经官之路不通（${官}无通关神引化），财之气仍以耗身为主` },
      被制: 财被制神.length ? { 有: true, 神: 比, 十神: '比劫', 落点: 财被制神.map((o) => `${o.宫位}${o.字}`), 说明: '比劫夺财，反护其身' } : { 有: false, 因: `局中无${比}（比劫）` },
      被合: 财被合.length ? { 有: true, 合: 财被合 } : { 有: false },
    },
    占比: 占比[财],
  };
      // ⚠ 2026-10-04 同"官"：桥虚设口径暂缓（见上），此处一并回退原状。
  // ★ 2026-10-04 与"官"同口径：桥虚设（通关有名无实）**不算"途在"**（规格（七）1）。
  财威.构成威胁 = 耗.some((x) => x.柱差 <= 2) && !财制得住 && !(官路.路.some((x) => x.桥.length) && !通关有名无实);
  财威.安危 = 财威.构成威胁
    ? `**构成威胁（耗身）**：${财}贴身或隔位耗身，`
      + `${财被制神.length ? `虽有${比}夺财，但${制力标题(财制力)}（${制力尾部(财制力)}）` : '无比劫夺财'}，`
      + `${通关有名无实 ? `且虽有${官路.通关神}为桥而**力度仅「${官路.通关神力度?.档}」＝桥虚设**（不计为"途在"）` : '且经官之路不通'}。`
    : `**不构成威胁**：${[
      财制得住 ? `被${比}（比劫）所制，且**制得住**` : null,
      官路.路.some((x) => x.桥.length) ? `经官之路被${官路.通关神}引通归身` : null,
      财被合.length ? '被合绊住' : null,
    ].filter(Boolean).join('、') || '财不透不藏于贴身之位'}。`;
  财威.压力说明 = `财占全局 ${占比[财]}%；身弱不任财时，须待${比}（比劫）帮身或${印}（印）生身。`;

  // 日主自身力量，仅作**输入**，不作判据（规格：旺衰在四条里不出现）
  const 日主 = dayMasterSupport(chart);

  return {
    日主五行: D,
    分组条件: {
      得令: 日主.得令, 得地: 日主.得地, 得势: 日主.得势,
      月令令态: 日主.月令令态,
      注: '引擎**只报这三项事实、不判身强身弱**（见 dayMasterSupport 原注）。'
        + '规格要求旺衰**只作分组条件与入手次序的建议，不作判据**（§一之二「逻辑自洽性复盘」第 1 条）。',
    },
    五行占比: 占比,
    官杀: 官威,
    财: 财威,
    结论: `${官威.安危} ${财威.安危}`,
    据: '规格 §一之二「四条的判据」第 1 条；《滴天髓》通关章',
  };
}

/**
 * **第 2 条 · 印比对日主有情／无情**（规格 §一之二）。
 *
 * 判据不是「它是什么十神」，而是「**它在此局有没有替日主处理掉忌神**」：
 *   有情 ＝ 与该字**制住**忌神，或**引化**忌神归身；
 *   无情 ＝ 该字对忌神无作用，或**反而加重**日主之病。
 * ⇒ 故**身弱而印比无情，亦不喜印比**（使用者原话）。
 *
 * `忌神` 可显式声明；未声明时由引擎按「占比最旺而日主不能任」推定，
 * 并在 `口径` 中**明写这是引擎推定**（引擎不作吉凶判断，只相对所声明者发言）。
 *
 * @param {object} chart
 * @param {{忌神五行?: string, 忌神?: string}} [opts]
 */
export function qingOf(chart, opts = {}) {
  const D = dayMasterOf(chart).element;
  const 印 = 生我者(D);
  const 比 = D;
  const 食 = SHENG_MAP[D];
  const 官 = 克我者(D);
  const 财 = KE_MAP[D];
  const monthBranch = branchAt(chart.pillars[1]);
  const s = elementStrength(chart.pillars, monthBranch, kingOf(chart));
  const 占比 = s.percent;

  let 忌 = opts.忌神五行 ?? null;
    // ★ 第 2 条须以**用神**为第二参照，判据是"**看他做了什么**"（使用者 2026-09-28）。
  // ⚠ 2026-10-01 修正：**"克用神"本身不是判据**（使用者：「水灭火那个是打个比方，别太死板」），
  //   不得凭一个布尔（el === 克我者(用神)）就写"本色为忌"；须经（八）结构分析证实，
  //   且「本色为忌」**只在依赖度为「唯一支柱且拆后无解」时成立**（见 体用路线法.md §一之二（八）一、（七）2）。
  //   ⚠ 本函数**尚未**实现"剩余解路数"求值，故 依赖度档 一律标"待定、须人工核"。
  const 用神 = opts.用神五行 ?? null;
  // ★ 2026-10-05 新增（规格 §一之二（七）1 **同字条款**，`:668-674`）：
  //   调用方（`tiyongRouteOf`）把**第 1 条判为「不构成威胁」的财／官五行**传进来。
  //   同一个字若又是（八）意义上的拆点 ⇒ **第 1 条优先**，但须**并陈两读**、
  //   并写明该字同时承担「财官」与「拆点」两种角色。⇒ 本函数对它**不写「本色为忌」**。
  //   ⚠ 只认**同一个字**：另一字若克用神，仍照样判忌（（七）1 作用域限定，`:661-662`）。
  const 第1条豁免 = new Set((Array.isArray(opts.第1条不威胁) ? opts.第1条不威胁 : []).filter(Boolean));
  let 口径;
    if (忌) {
    口径 = `调用方显式声明忌神为「${忌}」。`;
  } else if (用神) {
    // ★ 2026-10-04（使用者裁定「取消推定」）：**不再按"占比最旺者"推定忌神**。
    //   改按规格（七）2「**忌神＝克用神者**」由用神推出——这本就是引擎自己算得出的量。
    忌 = 克我者(用神);
    口径 = `调用方未声明忌神；按规格（七）2「**忌神＝克用神者**」由用神「${用神}」推得忌神「${忌}」。`
      + `（旧版曾按"占比最旺者"推定，与（七）2 守卫结构性不相容，已按使用者 2026-10-04 裁定**取消**。）`;
  } else {
    // 既无忌神、亦无用神 ⇒ 按（七）2 无从定忌神。**不判忌**，不得硬凑一个再报"口径矛盾"。
    口径 = `调用方**既未声明忌神、也未声明用神** ⇒ 按规格（七）2 无从定忌神，本节**不判忌**`
      + `（须先由第 1 条／候选段定出用神）。`
      + `（旧版曾按"占比最旺者"推定并据此判忌，已按使用者 2026-10-04 裁定**取消**。）`;
  }

  /** 某五行若为忌，则「谁是它的对治者」——直接制者与通关引化者。 */
  const 对治者 = (忌五行) => {
    const 直接制 = 克我者(忌五行);                  // 克忌神者
    const 引化 = SHENG_MAP[忌五行];                 // 忌 → 引化 → 日主？
    const 引化归身 = (引化 && SHENG_MAP[引化] === D) ? 引化 : null;
    return { 直接制, 引化归身 };
  };
  const { 直接制: 制忌者, 引化归身: 化忌者 } = 对治者(忌);

  // ════════════════════════════════════════════════════════════════════════
  // ★（八）结构分析：拆点 ／ 犯旺（2026-10-01 新增）
  //
  // 依据：`体用路线法.md` §一之二（八）——使用者 2026-10-01 原话
  //   「关于那个水灭火的判据，**那个是打个比方，你别太死板**」。
  //
  // 规格要求：不得再凭一个布尔（`el === 克我者(用神)`）就写「⇒ 判忌」；
  //   必须报四问——① 主要矛盾 ② 支撑点 ③ 依赖度 ④ 拆点还是犯次要矛盾、拆后还剩几条路。
  //
  // 本节只做**机器可判**的部分；凡本函数算不出的，一律标 '未判'，
  //   不得编造（规格 §一之二（八）「"唯一支柱"不许凭感觉写」）。
  // ════════════════════════════════════════════════════════════════════════
  let 结构分析 = null;
  if (用神 && 忌) {
    const 忌受者 = 克我者(忌);          // 直接制忌神者（＝通常即"用神"）

    // ① 支撑点守不守得住
    //
    // ⚠ 两处刻意"不死板"（使用者 2026-10-01：「那是打个比方，别太死板」）。
    //   以下 (a)(b) 讲的是**通则**；【案例】段是当初引出该通则的那一盘，
    //   **只作说明，不是判据的一部分，也不得当成"标准形态"**：
    //   (a) **通则（不用柱位"贴身"当门槛）**：`pathOf` 的贴身／柱差算的是**柱位**；
    //       而"某五行被另一五行所制"是**五行层面**的事。
    //       在支者在干者亦可构成相制，故本处**只判五行级相制 ＋ 有无真实落点**，
    //       不以柱位贴身为门槛（贴身与否仅作旁证并陈，见 `柱位旁证`）。
    //   (b) **通则（判"能不能真制住"，而非只看"克关系存在"）**：
    //       引擎既有 `canControlOf` 三档（月令力量／通根／占比），据此判制力是否成立。
    //
    //   【验证方法】（不写死任何盘的数值——盘各异，且数值随引擎版本漂移）：
    //     要核 (a)，取任一"克者与被克者分处支与干"的盘，看相制是否成立；
    //     要核 (b)，看 `支撑点四途.忌对其制力` 是否据 `canControlOf` 给出"能制住／不能制"，
    //     并与该盘实际情况比对。**本注释不举具体盘**，以免把某盘形态误当标准。
    const 支撑点 = 用神 ?? 忌受者;   // ★（八）②：支撑点＝用神；未声明用神时本函数已由调用方归一
    // 默认视为"调用方声明"（直调 qingOf 传 用神五行 的场景）；顶层暂取时显式传 false
    const 用神系调用方声明 = opts.用神声明 !== false;
    const 支撑点来源 = 用神系调用方声明 ? '声明之用神'
      // ★ 2026-10-05 接线（体检表 R2）：用神来自「④之二 取用定案」时须如实标注，
      //   不得再写成「按调候表暂取」——否则调用方看不出四条用的是哪一套。（规格 §一之二（二））
      : opts.用神来自定案 ? `按${opts.用神来自定案}；归一为五行「${用神}」；**待调用方核定**`
        : opts.用神暂取 ? `调用方按调候表暂取（原表作「${opts.用神暂取}」，归一为五行「${用神}」；**待核定**）`
          : '由忌神反推（克忌神者）';
    // ⚠（七）2 口径守卫：传入的 用神／忌神 自相矛盾时必须报出来，不得静默择一
    //   判据＝「克用神者 是否就是所声明的忌神」；一般形态举例（**非本盘定论**）：
    //   用神火 ⇒ 忌神水；用神水 ⇒ 忌神土；用神土 ⇒ 忌神木。逐盘不同，不得当常数。
    const 口径矛盾 = !!(用神 && 忌 && (用神 === 忌 || 克我者(支撑点) !== 忌));
    const 克支撑者 = 克我者(支撑点);
    const 支撑落点 = occupantsOf(chart, 支撑点);
    const 忌落点 = occupantsOf(chart, 忌);
    const 支撑有落点 = 支撑落点.length > 0;
    const 忌有落点 = 忌落点.length > 0;
    const 忌透干 = 忌落点.some((o) => o.层 === '天干');
    const 支撑透干 = 支撑落点.some((o) => o.层 === '天干');
    const 支撑被合 = combinedAwayOf(chart, 支撑点);
    // ★ 忌神对支撑点的制力（引擎既有三档；本函数不另造）
    //   ⚠ 关键：判 **忌神（水）能否制住支撑点（火）** —— 这就是"水能不能灭火"本身。
    //   （早先误写成"支撑点的克者 vs 支撑点"，等于拿错的字去判，已改。）
    const 忌制支撑点 = 克我者(支撑点) === 忌;              // 忌神确实克制支撑点（五行级）
    const 制支撑力 = (忌制支撑点 && 支撑有落点 && 忌有落点)
      ? canControlOf(chart, 忌, 支撑点, { 岁运: null }) : null;
    const 制得住支撑 = !!制支撑力 && 制支撑力.结论.startsWith('**能制住**');

        // 拆点**五**态（★ 2026-10-01 按使用者指示把「暗藏」**分档**；旧注释作"四态"、规格旧文作"六态"，皆误）：
    //   已证 ／ **暗藏·轻** ／ **暗藏·重** ／ 拆不到支柱 ／ 口径矛盾
    //   分档依据＝**同一 15 个百分点阈值**（与 `canControlOf` 第 4 关「势不敌」同源，不另造刻度）：
    //     · 差 = 支撑点占比 − 忌占比
    //     · 差 ≥ 15 ⇒ **暗藏·轻**（藏而力薄，危害被压缩）
    //     · 差 < 15 ⇒ **暗藏·重**（藏而力不弱，一旦引透即成大害）
    //   依据：使用者 2026-10-01「一要分」；早先「只喜暗藏」定的是"藏则暂安"，
    //   但"藏"内部量级差近十倍（实测：水 3.2% 与 水 28% 同为藏支），故须分档。
    const 支差 = Number((占比[支撑点] - 占比[忌]).toFixed(1));
    const 藏档轻 = 支差 >= 15;
    let 拆点判;
    if (口径矛盾) {
      拆点判 = {
        态: '口径矛盾（未判）',
        因: `传入的 用神=${用神}、忌神=${忌} **自相矛盾**：克${支撑点}者是${克支撑者 ?? '（未定）'}，`
          + `并非所声明的忌神${忌}${用神 === 忌 ? '，且用神与忌神同字' : ''}`
          + ` ⇒ 按规格（七）2「报口径矛盾要求核定」，**不得据此判忌**。`
          + `（**忌神应为"克用神者"**，逐盘不同——本盘用神${用神} ⇒ 忌神应为${克支撑者 ?? '（未能定出）'}。）`,
      };
    } else if (!忌制支撑点 || !支撑有落点 || !忌有落点) {
      拆点判 = {
        态: '拆不到支柱',
        因: `${忌}不克制支撑点${支撑点}，或两者有落点缺失（支撑点落点${支撑落点.length}、忌落点${忌落点.length}）`,
      };
    } else if (制得住支撑) {
      拆点判 = {
        态: '已证',
        因: `${忌}制${支撑点}**制得住**（${制支撑力.程度 ?? ''}${(制支撑力.结论 || '').replace(/\*\*/g, '').slice(0, 50)}）`,
        占比差: 支差,
      };
    } else if (!忌透干) {
      拆点判 = {
        态: 藏档轻 ? '暗藏·轻' : '暗藏·重',
        占比差: 支差,
        分档据: `支撑点${支撑点}占 ${占比[支撑点]}%、忌${忌}占 ${占比[忌]}%（差 ${支差} 个百分点）`
          + `；**阈值 15 为引擎操作化**（与「势不敌」同源）。`,
        因: `${忌}**全在支藏未透干**（${忌落点.map((o) => `${o.宫位}${o.字}(${o.藏})`).join('、')}）、`
          + `占 ${占比[忌]}%（支撑点${支撑点}占 ${占比[支撑点]}%）⇒ `
          + (藏档轻
            ? `**藏而力薄**（差 ${支差} 个百分点）`
            : `**藏而力不弱**（差 ${支差} 个百分点，未过 15）`)
          + `；对${支撑点}**${(制支撑力?.结论 || '无制力记录').replace(/\*\*/g, '')}**`
          + ` ⇒ **当下未能灭火，岁运引透即成害**（藏则暂安、透则转害）`,
      };
    } else {
      // ★★ 2026-10-05 修正（体检表 R3：旧版 138/500＝27.6% 自相矛盾）
      //   旧版此处无条件写「已证 —— 忌已透干且克支撑点」，**不看能不能制住**，
      //   于是同一对象里 `拆点判.态='已证'` 与 `支撑点四途.忌对其制力='不能制／制而不足'`
      //   并存（实测 138/500 盘）——引擎自己两处打脸。
      //   依规格（七）1 的对称原则——「『威胁不到』须『途在 ＋ 力够』两者兼备……
      //   凡引擎判该途**无力**，该途即**不算『有』**」（那里讲的是"有制神≠制得住"，
      //   此处同理：**有克神 ≠ 拆得动**）；规格（八）二亦要求拆点须「**任取其成立者**」。
      //   ⇒ 透干而**制不住**支撑点 ⇒ 拆点**不成立** ⇒ 落「拆不到支柱」，
      //     按 `判忌门槛` **不得径判忌**。（⚠ 暗藏两档仍依（八）二之二判忌——
      //     那是规格给"藏而未发"的**预防性**判据：藏则暂安、透则转害。）
      拆点判 = {
        态: '拆不到支柱',
        占比差: 支差,
        因: `${忌}虽**已透干**（${忌落点.filter((o) => o.层 === '天干').map((o) => `${o.宫位}${o.字}`).join('、')}）`
          + `且与${支撑点}有克关系，但 **canControlOf 判它制不住${支撑点}**：`
          + `${(制支撑力?.结论 || '（无制力记录）').replace(/\*\*/g, '')}`
          + ` ⇒ 依规格（七）1 之对称原则（**有克神 ≠ 拆得动**），本字**拆不到支柱**、`
          + `**不得径判忌**；须调用方按（八）四问人工复核依赖度与替代路。`,
      };
    }

    // 依赖度：规格三档需"剩余解路数"，引擎**无法可靠区分独立解路与同一桥的多条链**
    //   ⇒ 只在"拆点成立（已证／暗藏两档）"时给档；否则明标不适用，不编造（规格 §一之二（八）一）
    const 拆点成立 = 拆点判.态 === '已证' || 拆点判.态 === '暗藏·轻' || 拆点判.态 === '暗藏·重';
    let 依赖度档, 依赖度据;
    if (拆点成立) {
      依赖度档 = (支撑透干 && 支撑落点.filter((o) => o.层 !== '天干').length === 0)
        ? '待定（拆点成立；支撑点仅透干无通根，接近"唯一支柱"——剩余解路数须人工核）'
        : '待定（拆点成立；剩余解路数引擎未判，须人工核）';
      依赖度据 = `拆点成立（**${拆点判.态}**），但**剩余解路数引擎未判**`
        + `（无法可靠区分"独立解路"与"同一桥的多条链"）⇒ 按规格不得径写"唯一支柱"，须人工核。`;
    } else {
      依赖度档 = '不适用（拆点未成立）';
      依赖度据 = `拆点态＝**${拆点判.态}** ⇒ ${拆点判.因}。本档仅在"拆点成立"时才有意义。`;
    }

        // 柱位层面的旁证（**并陈，不作门槛**）
    // ⚠ 2026-10-04 修正：旧实现传 `{受克者宫位:'日干'}`，而 `occupantsOf` 默认**不含"日干"项**，
    //   故受方恒为空、`贴身可直克` **恒为 false（死码）**；今改按**支撑点自身落点**判
    //   「忌神是否贴身克到支撑点」。
    const 柱位旁证 = {
      贴身直克: pathOf(chart, 忌, 支撑点).路.some((x) => x.直接可克 && x.柱差 <= 1),
      注: '柱位贴身与否**不作判据**（五行级相制即可）——使用者 2026-10-01「别太死板」；此处仅作旁证并陈。',
    };

    // ② 本题字＝支撑点本身？⇒ 规格（七）2 的唯一豁免（否则推出"用神即忌神"自毁）
    //    （逐字层按 el 判，见下方 妨主要矛盾 的守卫）

    // ⚠ 旧口径（2026-10-01）：本支的「犯旺＝去激次要矛盾」**已被使用者 2026-10-04 重定义取代**——
    //   新口径＝「旺极之五行被大运／流年冲克」，见 `fanwangOf`。此字段保留供对照，**判据不得引**。
    const 旺序 = [...ELEMENTS].sort((a, b) => 占比[b] - 占比[a]);
    const 主要 = 旺序[0];
    const 次要 = 旺序.find((e) => e !== 忌 && e !== 主要) ?? null;

    // ④ 拆点作用：只判**本函数能证实**的那一种动作＝「忌神克支撑点」；
    //    合／冲／化 在本层未展开（`pathOf` 的 `路` 元素无 `冲` 字段）⇒ 明标 未判，不编造。
    const 拆点作用 = (el) => {
      if (el !== 忌) return { 有: false, 态: '非忌神本字', 动作: '不适用' };
      const 是暗藏 = 拆点判.态 === '暗藏·轻' || 拆点判.态 === '暗藏·重';
      return {
        有: 拆点判.态 === '已证',
        态: 拆点判.态,
        动作: 拆点判.态 === '已证' ? `克（${拆点判.因}）`
          : 是暗藏 ? `克但未透（当下未成害）·${拆点判.态 === '暗藏·重' ? '力不弱' : '力薄'}`
            : '克不到支柱',
        因: 拆点判.因,
        柱位旁证: 柱位旁证.贴身直克 ? '柱位亦贴身直克' : '柱位不贴身（不作判据）',
      };
    };

    const 犯旺 = (el) => {
      if (!次要) return { 有: false, 因: '未能定出次要矛盾' };
      // 犯旺 ＝ 去激次要矛盾（同五行或生它）**且**同时又拆支撑点
      const 激次要 = el === 次要 || SHENG_MAP[el] === 次要;
      const 拆支 = 拆点作用(el).有;
      if (激次要 && 拆支) return { 有: true, 次要, 因: `${el}既激次要矛盾${次要}、又拆支撑点${支撑点}` };
      if (激次要) return { 有: false, 因: `${el}激次要矛盾${次要}，但未拆支撑点` };
      return { 有: false, 因: `${el}与次要矛盾${次要}无激化关系` };
    };

    // ★★ 全盘判忌扫描（2026-10-01 补范围盲区）
    //   问题：本函数的逐字循环只走 **印比**（那是"第 2 条·印比是否有情"的范围）；
    //   但「克用神者」**未必落在印比**。穷举「日主×用神」20 组合，**10 组合**落在
    //   财／官杀／食伤 之外——例：**乙木日主以水为用神**（《穷通宝鉴》申月乙木取癸的常格），
    //   克水者＝**土（财）**，原实现**根本不遍历它** ⇒ 拆了支柱也静默漏判。
    //   规格的忌神定义是「**任一十神皆可**」，故（八）的拆点须**全十神**覆盖，
    //   不能只在印比循环里找。（规格 §一之二（八）一；使用者 2026-10-01「都做」。）
    const 十神一览 = [
      ['比劫', D], ['印', 生我者(D)], ['食伤', SHENG_MAP[D]],
      ['财', KE_MAP[D]], ['官杀', 克我者(D)],
    ];
    const 克用神者十神 = 十神一览.find(([, el]) => el === 克支撑者)?.[0] ?? null;
    const 全盘判忌 = 支撑有落点 && 忌有落点
      ? 十神一览.map(([名, 五行]) => {
        const 点 = occupantsOf(chart, 五行);
        if (!点.length) return null;
        const 是该五行 = 五行 === 支撑点;
        const 是克支撑 = 五行 === 克支撑者 && !是该五行;
        const 即忌神本字 = 五行 === 忌;
        let 状态;
        if (是该五行) 状态 = '即支撑点本身（不判忌，见（七）2 豁免）';
        // ★ 2026-10-05 修正（体检表 R6／新暴露）：标签须与 `判忌门槛` 一致——
        //   旧版对「即忌神本字」**不看闸门**，拆不到支柱／口径矛盾两态也写「本色为忌（…）」，
        //   与同屏「该两态不得径判忌」直接打架。今按 `拆点成立` 分流。
        else if (即忌神本字 && 拆点成立) 状态 = 第1条豁免.has(五行)
          // ★ 2026-10-05 新增（规格（七）1 **同字条款**，`:668-674`）：
          //   同一个字既被第 1 条判「不构成威胁（多多益善）」、又是（八）意义上的拆点
          //   ⇒ **第 1 条优先**，但**须并陈两读**、写明该字身兼两名。
          ? `**第 1 条优先**（并陈：（八）拆点成立＝${拆点判.态}；该字同时承担「财官」与「拆点」两种角色）`
          : `本色为忌（${拆点判.态 === '已证' ? '已证拆到支柱' : 拆点判.态}）`;
        else if (即忌神本字) 状态 = `**不判忌**（拆点未成立：${拆点判.态}）`;
        else if (是克支撑) 状态 = '克支撑点（须并看其制力与替代路）';
        else 状态 = '不涉判忌';
        return {
          十神: 名, 五行,
          落点: 点.map((o) => `${o.宫位}${o.字}${o.藏 ? `(${o.藏})` : ''}／${o.层}`),
          状态,
          在原印比循环内: (名 === '印' || 名 === '比劫'),
          逐字层能否判: (名 === '印' || 名 === '比劫')
            ? '能（在第 2 条逐字循环内）'
            : '**不能**——逐字循环只走印比；本行须由调用方按（八）另判',
          结果: 点.length,
        };
      }).filter(Boolean)
      : [];

    结构分析 = {
      主要矛盾: { 五行: 主要, 占比: 占比[主要] },
      次要矛盾: 次要 ? { 五行: 次要, 占比: 占比[次要] } : null,
      支撑点,
      支撑点来源,
      口径矛盾,
      克用神者十神,
      克用神者在印比之外: !!克用神者十神 && 克用神者十神 !== '印' && 克用神者十神 !== '比劫',
      全盘判忌,
      支撑点四途: {
        落点: 支撑落点.map((o) => `${o.宫位}${o.字}${o.藏 ? `(${o.藏})` : ''}／${o.层}`),
        透干: 支撑透干,
        被合: 支撑被合.length ? 支撑被合 : '无',
        忌对其制力: 制支撑力 ? { 结论: 制支撑力.结论, 程度: 制支撑力.程度 ?? null } : '（未计）',
        制得住支撑,
      },
      拆点判,
      依赖度档,
      依赖度据,
      柱位旁证,
      次要矛盾处理: '**只作次要一条**，须显式标注"次要"，不得篡改主要矛盾结论'
        + '；仅当被激化后新格局确已更大，才据第 1 条重评（见规格 §一之二（八）三）。',
      拆点: 拆点作用,
      犯旺,
      判忌门槛: '**拆点判.态 为「已证」／「暗藏·轻」／「暗藏·重」⇒ 本色为忌**'
        + '（暗藏两档害被压缩，"藏则暂安、透则转害"，仍**不得作喜用**；'
        + '**暗藏·重**者占比不弱，岁运引透之害须重报）；'
        + '**仅「拆不到支柱」与「口径矛盾」不得径判忌**（规格 §一之二（八）一、五）。',
      未判项: [
        '剩余解路数（替代路线计数）——引擎无法可靠区分"独立解路"与"同一桥的多条链"',
        '合绊支撑点（本函数未展开 canBindOf 该方向）',
        '冲支撑点（`pathOf` 的 `路` 元素无 `冲` 字段）',
      ],
      据: '规格 §一之二（八）「拆点与犯旺」；使用者 2026-10-01'
        + '「关于那个水灭火的判据，那个是打个比方，你别太死板」',
    };
  }

  const 逐字 = [];
  for (const [名, el] of [['印', 印], ['比劫', 比]]) {
    for (const o of occupantsOf(chart, el)) {
      // （七）2 的唯一豁免：用神自身不得被判忌（否则推出"用神即忌神"自毁）
      const 是本字即用神 = !!(用神 && el === 用神);
      const 是克用神者 = !!(用神 && el === 克我者(用神));
      // ★（八）：单凭"克用神"不足以免判 ⇒ 还须结构分析证实「确实拆到了支柱」
      //   规格（八）一：拆点「已证」⇒ 本色为忌（重）；
      //   「暗藏·轻／暗藏·重」⇒ **仍属本色为忌**，只是"藏则暂安、透则转害"（使用者 09-28「只喜暗藏」）；
      //     ★ 2026-10-01 按使用者指示**分档**：暗藏·重者占比不弱，引透之害须重报。
      //   只有「拆不到支柱」与「口径矛盾」才不得径判忌。
      const 拆点态 = 结构分析 ? 结构分析.拆点(el).态 : null;
      const 是暗藏态 = 拆点态 === '暗藏·轻' || 拆点态 === '暗藏·重';
      const 结构证实 = 是克用神者
        && !是本字即用神
        && !!结构分析
        && 结构分析.支撑点 !== el          // 拆的是**别人**的支柱，不是自己
        && (拆点态 === '已证' || 是暗藏态);
      const 属暗藏态 = 是暗藏态;
      const 妨主要矛盾 = 是克用神者 && !是本字即用神;
      const 结构未判 = 妨主要矛盾 && !结构证实;
      const 直接 = el === 制忌者;
      const 引化 = el === 化忌者;
            // （七）2 唯一豁免：**用神自身永不得被判忌**（否则推出"用神即忌神、当弃之"自毁结论）
      const 加重 = el === 忌 && !是本字即用神;
      let 结论;
      if (结构证实) {
        const 态名 = 结构分析.拆点(el).态;
        const 重档 = 态名 === '暗藏·重';
        结论 = 属暗藏态
          ? `**忌（${态名}）**：${el}克用神${用神}，且经结构分析证实**确实拆的是对付主要矛盾的那根支柱**`
            + `（支撑点${结构分析.支撑点}；${结构分析.拆点(el).因}）。`
            + (重档
              ? `⇒ **本色为忌，且属"暗藏·重"**：藏而未透、危害被压缩，但**占比不弱**——`
                + `一旦**岁运引透即成大害**，须按重害预判，**不得因"藏"而轻看**。`
              : `⇒ **本色为忌，但属"暗藏·轻"**：**藏而力薄**（占比已明显低于支撑点），`
                + `危害被压缩（"藏则暂安、透则转害"），然**仍不得作喜用**。`)
          : `**忌**：${el}克用神${用神}——**且经结构分析证实：确实拆到了支柱**`
            + `（${结构分析.拆点(el).动作}；支撑点${结构分析.支撑点}；依赖度${结构分析.依赖度档}）。`
            + `虽${el === 忌 ? '本身即忌神' : `能引化${忌}、亦能生身`}，但**灭工具**，故**本色为忌**；`
            + `暗藏时危害被压缩、可顺手化掉一点${忌}，但**不得作喜用**`;
      } else if (结构未判) {
        // ★ 规格（八）四问答不上 ⇒ 不得判忌（不得再写"⇒ 判忌"）
        结论 = `**不得径判忌（结构未证实）**：${el}与用神${用神}确有克关系，`
          + `但按规格 §一之二（八）四问，**引擎判不出它拆到了哪根支柱**——`
          + `支撑点${结构分析 ? 结构分析.支撑点 : '（未算出）'}；`
          + `拆点判定＝${结构分析 ? 结构分析.拆点(el).动作 : '未判'}。`
          + `⇒ **须调用方按（八）人工核"依赖度＋剩余解路数"后方可定性**，不得据"克用神"三字下主结论`
          + `（使用者 2026-10-01：「那是打个比方，别太死板」）。`;
      } else if (直接) 结论 = `**有情**：${el}克${忌}（忌神），直接制住日主之病。`;
      else if (引化) 结论 = `**有情**：${忌}生${el}、${el}生${D}（日主），把忌神之气**引化归身**。`;
      else if (加重) 结论 = `**无情**：${el}**本身即忌神**，加重日主之病，虽为${名}亦不可用。`;
      else 结论 = `**无情／无作用**：${el}对忌神${忌}既不能制、亦不能引化（${名}虽在，于此病无救）。`;
      逐字.push({
        十神: 名, 五行: el, 宫位: o.宫位, 字: o.字, 藏: o.藏, 层: o.层,
        就近: proximityOf(o.宫位, '日干').档,
        角色: 结构证实 ? '拆支撑点（结构已证）'
          : 结构未判 ? '克用神但结构未证实'
            : 直接 ? '制忌神者' : 引化 ? '引化忌神者' : 加重 ? '即忌神' : '无作用',
        结构: 结构分析 ? {
          是克用神者, 是本字即用神, 结构证实, 结构未判,
          拆点: 结构分析.拆点(el), 犯旺: 结构分析.犯旺(el),
        } : null,
        结论,
      });
    }
  }

  const 有情 = 逐字.filter((x) => x.结论.startsWith('**有情**'));

  // ★ 交叉裁决（2026-09-28 补，据使用者复盘）：
  // 「对日主有情」**不等于**「对用神无害」。同一个字完全可能：
  //   对日主是印（生我、且引化官杀），却对用神是**克神**（如水生木、水又克火）。
  // 规格自己立了「护卫是相对的：同一字对甲是护卫、对乙是威胁」，但本条原先只对日主判情，
  // 不查用神——于是出现"第2条说有情、第3条说它是克用神者"的静默矛盾。
  // 故此处须以**用神**为第二参照，并区分**透干／支藏**：
  //   克用神者若已透干 ⇒ 对用神已成直敌；
  //   若全在支藏未透 ⇒ **只宜暗藏，岁运引透即转害**。
  let 与用神的关系 = null;
  let 交叉裁决 = null;
  if (用神) {
    const 克用 = 克我者(用神);          // 克用神者
    const 生用 = 生我者(用神);          // 生用神者
    const 用克 = KE_MAP[用神];          // 用神所克
    const 用生 = SHENG_MAP[用神];       // 用神所生
    const 关系名 = (el) => el === 用神 ? '即用神'
      : el === 克用 ? '克用神者'
        : el === 生用 ? '生用神者'
          : el === 用克 ? '用神所克' : el === 用生 ? '用神所生' : '无涉';
    const 层计 = (list) => ({
      透干: list.filter((x) => x.层 === '天干').length,
      支中本气: list.filter((x) => x.层 === '地支本气').length,
      支中藏干: list.filter((x) => x.层 === '地支藏干').length,
    });
    与用神的关系 = [...new Set([印, 比])].map((el) => {
      const 点 = 逐字.filter((x) => x.五行 === el);
      if (!点.length) return null;   // 局中无此五行者不列，免生"落点 0、0、0"的噪声
      const 层 = 层计(点);
      const 关系 = 关系名(el);
      const 有情否 = 点.some((x) => x.结论.startsWith('**有情**'));
      let 判语;
      let 判语短;
      if (关系 === '克用神者') {
        判语 = 层.透干 > 0
          ? `⚠ **既对日主有情，又是用神之敌**：${el}克用神${用神}，且已**透干**（${点.filter((x) => x.层 === '天干').map((x) => x.宫位 + x.字).join('、')}）——`
            + `对日主之利与对用神之害同时成立，须以制（${用克}）或合羁绊之，不可因其"有情"而重用。`
                   : (结构分析.拆点判.态 === '已证'
            ? `⚠ **本色为忌（已证：确有拆到支撑点）**：${el}对日主有情（${点[0]?.角色 ?? '—'}），却**克用神${用神}**；`
            : /^暗藏/.test(String(结构分析.拆点判.态))
              ? `⚠ **只宜暗藏（${结构分析.拆点判.态}）**：${el}对日主有情（${点[0]?.角色 ?? '—'}），却**克用神${用神}**；`
              : `⚠ **结构未证实（${结构分析.拆点判.态}），不得径判忌**：${el}对日主有情（${点[0]?.角色 ?? '—'}），却**克用神${用神}**；`)
            + `本盘此神**皆藏于支、未透干**（${点.map((x) => `${x.宫位}${x.字}(${x.藏})`).join('、')}）`
            + `⇒ 藏则化${克用}生身，**透则反灭用神**；岁运引透（干见${克用}、或三合成局）即转害。`;
        判语短 = 层.透干 > 0
          ? '对用神已成直敌（须制或合，不可因其能生化而重用）'
          : (结构分析.拆点判.态 === '暗藏·重'
            ? '本色为忌、**暗藏·重**（占比不弱）——引透即成大害，**不得因"藏"而轻看**'
            : 结构分析.拆点判.态 === '暗藏·轻'
               ? '本色为忌、**暗藏·轻**（占比已明显低于支撑点），**不得作喜用**（岁运引透即转害）'
               : 结构分析.拆点判.态 === '已证'
                 ? '本色为忌（**已证**：确有拆到支撑点）'
                 : `**结构未证实（${结构分析.拆点判.态}）⇒ 不得径判忌**，须调用方按（八）四问人工核`);
      } else if (关系 === '生用神者') {
        判语 = `兼为用神之源（${el}生${用神}），对日主与用神同向，无害。`;
        判语短 = '兼为用神之源，无害';
      } else if (关系 === '用神所克' || 关系 === '用神所生') {
        判语 = `${el}为${关系}，与用神不构成生克冲突，但会分用神之力，须并看力度。`;
        判语短 = '与用神不直接冲突，但分其力';
      } else if (关系 === '即用神') {
        判语 = '与用神同五行，算力量时可叠加，不算冲突。';
        判语短 = '与用神同五行，可叠加';
      } else {
        判语 = '与本用神无直接生克。';
        判语短 = '与用神无涉';
      }
      return { 五行: el, 与用神: 关系, 有情否, 落点层次: 层, 判语, 判语短 };
    }).filter(Boolean);
    const 冲突 = 与用神的关系.filter((x) => x.与用神 === '克用神者');
    // ★ 2026-10-05 新增（规格（七）1 **同字条款**，`:668-674`）：
    //   同一个字既被第 1 条判「不构成威胁 ⇒ 多多益善」、又是（八）意义上的拆点 ⇒
    //   **第 1 条优先**（判断层第一准则），但**须并陈两读**，并写明该字身兼两名。
    //   ⚠ 该字若落在**财／官**（第 1 条评的正是它们），它不在 `与用神的关系` 里
    //     （那里只走印比）⇒ 必须**单独成段**，否则顶层【交叉裁决】会误报「未检出冲突」。
    const 态0 = 结构分析?.拆点判?.态;
    const 拆点成立0 = ['已证', '暗藏·轻', '暗藏·重'].includes(态0);
    const 同字冲突 = 用神 ? [...第1条豁免].filter((el) => el === 克用 && 拆点成立0) : [];
    const 段 = [];
    if (同字冲突.length) {
      段.push(`⚠ **同一字冲突（规格 §一之二（七）1「同字条款」）**：**${同字冲突.join('、')}** 既被**第 1 条**评为`
        + `「**威胁不到 ⇒ 多多益善**」（该财官本身可为喜用），又是（八）意义上的**拆点**（态＝**${态0}**）`
        + ` ⇒ 依该条**主结论取第 1 条**；(八) 之判忌**降为并陈**——`
        + `此字**同时承担「财官」与「拆点」两种角色**，不得只报一边。`
        + `⚠ 仅当**第 1 条本身不成立**（主要矛盾另有其人）时，(八) 的拆点判定才独立生效；`
        + `替代路与依赖度仍须调用方按（八）人工核。`);
    }
    if (冲突.length) {
      // ★（八）：不再无条件写「⇒ 判忌」——须逐字层**结构证实**拆到了支柱
      const 已证 = 冲突.filter((x) => 逐字.some((r) => r.五行 === x.五行 && r.结构?.结构证实));
      const 未证 = 冲突.filter((x) => !逐字.some((r) => r.五行 === x.五行 && r.结构?.结构证实));
      if (已证.length) {
                段.push(`${已证.map((x) => x.五行).join('、')}${已证.every((x) => x.五行 === 忌) ? '**本身即忌神**' : `虽能引化${忌}、亦能生身`}，`
          + `却**克用神${用神}**，且经结构分析证实**确实拆到了支柱**（支撑点${结构分析.支撑点}；`
          + `依赖度${结构分析.依赖度档}）⇒ **本色为忌**；${已证.map((x) => x.判语短).join('；')}。`);
      }
      if (未证.length) {
        段.push(`⚠ **${未证.map((x) => x.五行).join('、')}：结构未证实，不得径判忌。**`
          + `${未证.map((x) => x.五行).join('、')}与用神${用神}确有克关系，`
          + `但按规格 §一之二（八）四问，引擎**判不出它拆到了哪根支柱**`
          + `（拆点判定＝${未证.map((x) => 结构分析.拆点(x.五行).动作).join('、')}）`
          + `⇒ **须调用方人工核"依赖度＋剩余解路数"后方可定性**，`
          + `不得据"克用神"三字下主结论（使用者 2026-10-01：「那是打个比方，别太死板」）。`);
      }
    }
    // ★ 2026-10-05：`交叉裁决` 由「段」统一决定——否则"只有同字冲突、无印比冲突"时
    //   会落 null，顶层随之打印「本盘未检出该类冲突」的**假阴性**。
    交叉裁决 = 段.length ? 段.join(' ') : null;
  }

  const 已证拆点 = 逐字.filter((x) => x.结构?.结构证实);
  const 未证克用神 = 逐字.filter((x) => x.结构?.结构未判);
  // ★ 印比之外的拆点（2026-10-01 补范围盲区）：逐字循环只走印比，
  //   故若「克用神者」是财／官杀／食伤，**它根本不在上面两组里**——必须单独补报，
  //   否则出现"结构分析说某某本色为忌、结论却一字不提"的静默漏判。
    // ⚠ 2026-10-04 修正：旧式只认"已证"档，**非印比的暗藏档拆点**（规格 §一之二（八）二之二明定本色为忌）
  //   被排除 ⇒ 既不进结论、也不进交叉裁决（静默漏判）。今纳入暗藏两档，仍排除"口径矛盾／拆不到支柱"。
  const 印外行 = (结构分析?.全盘判忌 ?? []).filter((r) => /^本色为忌（(已证拆到支柱|暗藏·[轻重])）$/.test(String(r.状态)) && !r.在原印比循环内);
  const 印外补报 = 印外行.length
    ? ` ⚠ **印比之外另有拆点**（逐字层不覆盖，须并入断语）：`
      + 印外行.map((r) => `**${r.十神}${r.五行}**（${r.状态}）`).join('、')
      + `——规格忌神定义是「**任一十神皆可**」，故它虽不在印比，仍属本色为忌；`
      + `调用方须按（八）另判其**依赖度与替代路**，**不得因"不是印比"而漏掉**。`
    : '';
  return {
    日主五行: D,
    忌神: 忌,
    口径,
    对治: { 制忌神者: 制忌者, 引化归身者: 化忌者 },
    印五行: 印,
    比劫五行: 比,
    逐字,
    有情的印比: 有情.map((x) => `${x.宫位}${x.字}（${x.十神}·${x.角色}）`),
    用神五行: 用神,
    与用神的关系,
    交叉裁决,
    结构分析,
    印外拆点补报: 印外补报 || null,
    结论: (有情.length
      ? `**${有情.map((x) => `${x.十神}${x.宫位}${x.字}`).join('、')}对日主有情**（${有情[0].角色}）。其余印比于此病无救。`
      : (已证拆点.length
        // ⚠ 逐字是**按落点**迭代的，同一五行可能出现 2–6 次 ⇒ 文案须按五行去重
        //   （旧版实测输出「土、土、土、土、土、土」，见体检表 结论 例）
        ? `**${[...new Set(已证拆点.map((x) => x.五行))].join('、')}本色为忌（结构已证实拆到支柱）**：`
          + `${[...new Map(已证拆点.map((x) => [x.五行, x])).values()].map((x) => `${x.五行}克用神${用神}，${x.结构.拆点.动作}`).join('；')}。`
          + `支撑点${结构分析.支撑点}；依赖度${结构分析.依赖度档}。`
          + `⇒ 依规格「**身弱而印比无情，亦不喜印比**」，不可因"身弱"遂取印比。`
        : (未证克用神.length
          ? `**⚠ 印比中有克用神者，但结构未证实 ⇒ 不得径判忌**：`
            + `${[...new Set(未证克用神.map((x) => x.五行))].join('、')}克用神${用神}，`
            + `但引擎按规格 §一之二（八）四问**判不出其拆到了哪根支柱**。`
            + `⚠ 规格（八）明文凡报"某某克用神⇒判忌"而不报**依赖度与剩余解路数**者，**不合格**。`
            + `⇒ 本条**不构成主结论**，须调用方按（八）人工核定。`
          : `**印比皆无情**：局中印比既不能制忌神${忌}、亦不能引化归身。`
            + `⇒ 依规格「**身弱而印比无情，亦不喜印比**」，不可因"身弱"遂取印比。`)))
      + (交叉裁决 ? ` ⚠ **第 2 条以主要矛盾为准**（使用者 2026-09-28「忌神用神就是看他做了什么」）：${交叉裁决}` : '')
      + 印外补报,
    据: '规格 §一之二「第 2 条 · 印比是否有情」＋ §一之二（八）「拆点与犯旺」；'
      + '使用者「有情＝与日主目标一致，无情＝加重日主的病」；'
      + '★「有情≠对用神无害」为使用者 2026-09-28 复盘所补；'
      + '★ 2026-10-01 使用者「水灭火那个是**打个比方，别太死板**」⇒ 判忌须经结构分析证实，'
      + '不得凭"克用神"三字径判（见 结构分析.据）',
  };
}

/**
 * 护名的统一渲染（**模块级**，供 `protectionOf` 与 `formatTiyong` 共用）。
 * ⚠ `合` 途径的 `合` 是**对象数组**（`combinedAwayOf` 的返回），**直接插值会输出 `[object Object]`**。
 * ⇒ 一切输出口一律经此函数，**不得再直插 `x.合`**。
 */
function 护名字(x) {
  if (x?.途径 === '合') {
    const 合s = Array.isArray(x.合) ? x.合 : [];
    return `合·${合s.map((h) => h.被合者 ?? h.途径 ?? '?').join('、') || '（无）'}`;
  }
  return `${x?.途径 ?? '?'}·${x?.神 ?? ''}${x?.力度档 ? `/${x.力度档}` : ''}`;
}

/**
 * **第 3 条 · 用神的护卫**（规格 §一之二）。
 *
 * 判据：**「克用神者 → 用神」之间有没有通关神**（火为用、水来灭火、中间隔木 ⇒ 木护卫了火）。
 * 三条途径：
 *   ① **隔（通关）**：X ＝ 生[用神]，且 克[用神] 生 X ⇒ X 即护卫
 *   ② **制**：克「克用神者」者 ＝ 用神所生之神，亦为护卫
 *   ③ **合**：合「克用神者」者，绊住凶神
 * 并报**护神自身是否会被坏**（使用者：「除非流年大运把我火灭了」）。
 *
 * @param {object} chart
 * @param {string} 用神五行
 * @param {{岁运?: string}} [opts] 岁运为两字干支，如 '丙寅'
 */
export function protectionOf(chart, 用神五行, opts = {}) {
  const { 岁运 = null } = opts;
  const D = dayMasterOf(chart).element;
  const 克用神者 = 克我者(用神五行);          // 克用神之五行
  const 隔护 = 生我者(用神五行);              // 生用神者
  const 通关成立 = SHENG_MAP[克用神者] === 隔护;
  const 制护 = SHENG_MAP[用神五行];           // 用神所生 ＝ 克「克用神者」者

  const 隔路 = pathOf(chart, 克用神者, 用神五行, { 受克者含日主: 用神五行 === D });
  const 隔落点 = occupantsOf(chart, 隔护);
  const 制落点 = occupantsOf(chart, 制护);
  const 用神落点 = occupantsOf(chart, 用神五行);
  const 忌被合 = combinedAwayOf(chart, 克用神者);
  const r = relationsOf(chart.pillars);
  // 去重：同一支的**不同气**要分开算（年支巳以本气丙当隔护，又以中气庚当制护），
  // 但**同一支同一气**会因多条路径重复入选（旧实现实测年支巳重复 3 次）。
  // 故键取「宫位|字|层|五行」，显示时带上藏干（本丙／中庚），避免读成重复项。
  const 护神表 = new Map();
  for (const [途, list] of [['隔', 隔落点], ['制', 制落点]]) {
    for (const o of list) {
      const k = `${o.宫位}|${o.字}|${o.层}|${o.五行}`;
      if (!护神表.has(k)) 护神表.set(k, { o, 途: [] });
      护神表.get(k).途.push(途);
    }
  }
  const 护神显示 = (o) => `${o.宫位}${o.字}${o.藏 ? `(${o.藏})` : ''}`;
  const 护被坏 = [...护神表.values()].map(({ o, 途 }) => ({
    护神: 护神显示(o), 五行: o.五行, 层: o.层, 藏: o.藏 ?? null, 兼: 途.join('+'),
    受损: 受损Of(r, o.宫位, o.字, o.层),
  })).filter((x) => x.受损.length);

  // 桥列表同样去重（同一宫位同一字会因多条路径重复入选，实测日支巳出现 4 次）
  const 桥去重 = (路) => [...new Set(路.flatMap((x) => x.桥).map((b) => `${b.宫位}${b.字}(${b.形态})`))];
  // ★ 「在位」≠「够力」（规格 §4.6.7「有制神 ≠ 制得住」）：护神自身若为「弱」档，
  // 不足以制／化／合，不能计入「有效护卫」，须单列「在位但不足力」。
  const 隔护力度 = powerOf(chart, 隔护, { 岁运 });
  const 制护力度 = powerOf(chart, 制护, { 岁运 });
  const 够力 = (p) => !!p?.档 && p.档 !== '弱';
  const 有效护卫 = [];
  const 在位但不足力 = [];
  if (隔路.路.some((x) => x.桥.length)) {
    const e = { 途径: '隔（通关）', 神: 隔护, 桥: 桥去重(隔路.路), 力度档: 隔护力度.档, 断语: 隔护力度.断语 };
    (够力(隔护力度) ? 有效护卫 : 在位但不足力).push(e);
  }
  if (制落点.length) {
    const e = {
      途径: '制', 神: 制护, 落点: [...new Set(制落点.map((o) => `${o.宫位}${o.字}`))],
      力度档: 制护力度.档, 断语: 制护力度.断语,
    };
    (够力(制护力度) ? 有效护卫 : 在位但不足力).push(e);
  }
  // 「合」不需要力度门槛（规格 §四：合是牵住他，不是压住他）
  if (忌被合.length) 有效护卫.push({ 途径: '合', 合: 忌被合 });

  const 危 = 隔路.贴身可直克;
  const 护神名 = [...new Set([...隔落点, ...制落点].map(护神显示))];

  // ★ 岁运引克（2026-09-28 补，据使用者复盘「透出来会克用神火，只喜暗藏」）：
  // 原局的「用神自安」常建立在"克用神者皆藏于支、够不着用神"之上。
  // 岁运一旦把克神**引透到天干**（或让克神得本气根／成局），就凭空造出一条直克用神的路径——
  // 原局结论在岁运中不再成立。旧实现只报"护神被牵制"，完全不查这件事。
  let 岁运引克 = null;
  if (岁运) {
    const gz = String(岁运);
    if (gz.length !== 2 || STEMS.indexOf(gz[0]) < 0 || BRANCHES.indexOf(gz[1]) < 0) {
      throw new Error(`protectionOf: 岁运须为两字干支，收到「${岁运}」`);
    }
    const si = STEMS.indexOf(gz[0]);
    const bi = BRANCHES.indexOf(gz[1]);
    const 干五行 = ELEMENTS[STEM_ELEMENT[si]];
    const 支五行 = ELEMENTS[BRANCH_ELEMENT[bi]];
    const 干引 = 干五行 === 克用神者;
    const 支引 = 支五行 === 克用神者;
    const 用神天干落点 = 用神落点.filter((o) => o.层 === '天干').map((o) => `${o.宫位}${o.字}`);
    const rr = gzRelations(chart.pillars, { stemIndex: si, branchIndex: bi });
    // 只算**牵涉岁运**的合／局，否则会把原局内部的合（如巳申合化水）误记到岁运头上
    const 涉岁运 = (s) => String(s ?? '').includes('大运');
    const 成局 = (rr.地支三合 ?? [])
      .filter((x) => 涉岁运(x.positions) && String(x.局 ?? '').includes(克用神者)).map((x) => x.局);
    const 半合 = (rr.地支六合 ?? [])
      .filter((x) => 涉岁运(x.pair) && String(x.化 ?? '').includes(克用神者)).map((x) => x.pair);
    const 条 = [];
    // ⛔ 规格 §四 禁令：「**禁止把「用神合忌神」读成用神被坏**——先辨体用，再定合的方向」。
    // 故岁运干若与用神之干**相合**，不得径判"直克"：须按"用神合忌神＝把忌神锁住＝做功"处理，
    // 并陈《子平真诠》"合而不化，逢吉不为吉"的反对说；只有"冲／无合之克"才作直克。
    const 用神干字 = 用神落点.filter((o) => o.层 === '天干').map((o) => o.字);
    const 用神支字 = 用神落点.filter((o) => o.层 !== '天干').map((o) => o.字);
    // 合/冲只对「岁运干本身就是克用神者」时才有意义（否则合的是别的字，与"用神合忌神"无关）
    const 合对 = 干引 ? (rr.天干五合 ?? []).filter((x) => 涉岁运(x.pair) && 用神干字.some((h) => String(x.pair).includes(h))) : [];
    const 冲对 = 干引 ? (rr.天干相冲 ?? []).filter((x) => 涉岁运(x.pair) && 用神干字.some((h) => String(x.pair).includes(h))) : [];
    if (干引 && 用神干字.length) {
      const 被合 = 合对.map((x) => x.pair);
      const 被冲 = 冲对.map((x) => x.pair);
      if (被合.length) {
        条.push(`岁运天干**${gz[0]}**属${克用神者}、本可克用神之干（${用神干字.join('、')}），`
          + `但见**${被合.join('、')}**——依规格 §四「**用神合忌神＝把忌神锁住＝做功，不算用神被坏**」，`
          + `**不得径判直克**；须并陈《子平真诠》「合而不化则逢吉不为吉」之反对说，另验合化是否成立`);
      } else if (被冲.length) {
        条.push(`岁运天干**${gz[0]}**属${克用神者}，与用神之干见**${被冲.join('、')}**（天干相冲）⇒ **直克用神**：`
          + `原局「用神自安」的结论在 **${gz}** 中不成立`);
      } else {
        条.push(`岁运天干**${gz[0]}**属${克用神者}，与用神天干落点（${用神干字.join('、')}）无合、不成冲 `
          + `⇒ 天干对天干**直克**：原局「用神自安」的结论在 **${gz}** 中不成立`);
      }
      // 若同时另有用神之干被合、另一被冲，须分列（如壬与月干丙相冲、与时干丁相合）
      if (被合.length && 被冲.length) {
        条.push(`**同一岁运干对不同用神干结论相反**：${被冲.join('、')}为冲（直克），${被合.join('、')}为合（做功／须另验化）——须**分别落点分别断**，不可一言蔽之`);
      }
    } else if (干引) {
      条.push(`岁运天干**${gz[0]}**属${克用神者}，用神虽无天干落点（无处被直克），但克神力量仍增`);
    }
    if (支引) {
      const 支合 = (rr.地支六合 ?? []).filter((x) => 涉岁运(x.pair) && 用神支字.some((h) => String(x.pair).includes(h)));
      条.push(`岁运地支**${gz[1]}**属${支五行}＝克用神者${克用神者}得本气之根，克神转旺`
        + (支合.length ? `；但见**${支合.join('、')}**（与用神之支相合）——合则绊住，须另判克力` : ''));
    }
    if (成局.length) 条.push(`与原局成${成局.join('、')}，${克用神者}得局而势增`);
    else if (半合.length) 条.push(`与原局见${半合.join('、')}（是否合化须另判）`);
    if (条.length) {
      const 用神合克 = 干引 && 合对.length > 0 && 冲对.length === 0;
      const 混合 = 干引 && 合对.length > 0 && 冲对.length > 0;
      岁运引克 = {
        岁运: gz, 克用神者, 干引, 支引, 成局, 半合,
        合对: 合对.map((x) => x.pair), 冲对: 冲对.map((x) => x.pair),
        性质: 用神合克 ? '用神合克神（做功，不算被坏）'
          : 混合 ? '混合（有用神干被合、有用神干被冲，须分列）'
            : 干引 ? '克神直克／冲用神'
              : 支引 ? '克神得本气之根，转旺' : '克神得局而势增',
        结论: `⚠ **岁运引动克用神者**：${条.join('；')}。`
          + (用神合克
            ? `⇒ **非「用神被坏」，而是用神合住了克神**（规格 §四：合的目的是让他为我所用）。`
            : 混合
              ? `⇒ 须**分别落点分别断**；不得整体判"用神被坏"，亦不得整体判"做功"。`
              : `⇒ 此即使用者「**只喜暗藏**」之义：藏则可化${克用神者}生身，透则反灭用神${用神五行}。`),
      };
    }
  }
  const 受损汇总 = [...new Set(护被坏.flatMap((x) => 受损文字(x.受损)))];
  return {
    用神: 用神五行,
    用神落点: 用神落点.map((o) => `${o.宫位}${o.字}${o.藏 ? `(${o.藏})` : ''}`),
    克用神者: 克用神者,
    克用神者落点: 隔路.克者落点,
    隔护神: 通关成立 ? 隔护 : `（${克用神者}生${隔护}，但${隔护}不生${用神五行}，无通关可言）`,
    制护神: 制护,
    // ★ 护神在不在局 ≠ 护不护得住：力度见 powerOf
    隔护力度,
    制护力度,
    有效护卫,
    在位但不足力,
    有路可直克用神: 危,
    力弱之直克: 隔路.力弱之直克,
    安危: 危
      ? (有效护卫.length
        ? `**有贴身直克之路，但护卫在位且够力**（${有效护卫.map(护名字).join('、')}）⇒ 用神不被克伤。`
          + (在位但不足力.length ? ` ⚠ 另有护卫**在位但不足力**（${在位但不足力.map((x) => `${x.途径}·${x.神}（${x.力度档}）`).join('、')}），不计入有效护卫。` : '')
        : `**用神有贴身直克之路且无有效护卫 ⇒ 受威胁。**`
          + (在位但不足力.length ? `（护卫虽在但**不足力**：${在位但不足力.map((x) => `${x.途径}·${x.神}（${x.力度档}）`).join('、')}——依规格 §4.6.7「有制神≠制得住」）` : ''))
      : `**无贴身路径可直克用神**（或被通关神引化）${
        隔路.力弱之直克.length ? `；仅有隔位／遥隔之直克（力弱，不计为威胁：${隔路.力弱之直克.join('、')}）` : ''}，用神自安。`,
    护神自身: 护被坏.length
      ? { 有损: true, 明细: 护被坏.map((x) => ({ 护神: x.护神, 兼: x.兼, 受损: 受损文字(x.受损) })) }
      : { 有损: false },
    岁运引克,
    岁运警示: (岁运引克 ? `${岁运引克.结论} ` : '')
      + (护被坏.length
        ? `护卫神 ${护被坏.map((x) => `${x.护神}${x.兼 === '隔+制' ? '(兼隔/制)' : ''}`).join('、')} 在原局已被 ${受损汇总.join('、')} 牵制，`
          + `**护卫效力须打折**；岁运再临冲刑则将护卫彻底灭去。`
          + `（使用者原话举例用的是火：「除非流年大运把我火灭了」——其义为**岁运灭掉护卫者即失护**；`
          + `本盘被灭者即上列的护卫神，与「${用神五行}」为用神是否相同须自辨）`
        : `原局护卫神（${护神名.join('、') || '无'}）未被冲刑合破牵制；`
          + `岁运若冲刑护卫神本身，护卫即失效——其义即使用者「除非流年大运把我火灭了」（原话说的是火，可推及任何用神）。`),
    说明: '护卫只解决**安危**；**压力**须待岁运通关之神到位（规格 §一之二 ②：护卫 ≠ 化解）。'
      + '⚠「有贴身直克之路」说的是**路径存在**，不等于用神已伤——伤否另看 `有效护卫`。'
      + '⚠ `安危` 是**原局**结论；岁运若把「克用神者」引透（干见克神、或成局），原局之安不再成立，'
      + '见 `岁运引克`（使用者「只喜暗藏」之义）。',
    据: '规格 §一之二「第 3 条 · 用神是否有保护」；使用者「火为用神，水来灭火，中间隔着木，木就护卫了火」',
  };
}

/**
 * **护卫链（递归）** —— 使用者：「护卫是**相对**概念……那么**火的护卫是什么**？
 * 就是木来隔水生火。**依此类推**。」
 *
 * 于是护卫不是一层，而是一条**链**：护神自身也会被克，故护神也需要护神。
 *
 * 关键结构：通关护卫 X ＝「**生当前者**」（**母亲**），故沿母亲走恰为五行相生的五步环
 *   `火 ← 木 ← 水 ← 金 ← 土 ← 火`。
 * 故 **珠链是否闭合，取决于这五个"母亲"是否都在局中在位。**
 * （若母亲不在局而儿子在，则改走**制**途，此时容易形成短环而不成完整五行之环。）
 *
 * ⚠ **本函数只报链，绝不把"闭环"等同于"结构稳定"。**
 *   「护卫链闭环 ＝ 结构稳定」是**引擎作者的推断**；使用者 2026-09-27 认
 *   「五行上转一圈，和四柱宫位上有没有关联，**不一定是同一件事**」。
 *   故二者**分开报**：环见本函数，宫位网络见 `structureOf`。
 *
 * @param {object} chart
 * @param {string} 用神五行
 * @param {{最大层数?: number}} [opts]
 */
export function protectionChainOf(chart, 用神五行, opts = {}) {
  const { 最大层数 = 6, 岁运 = null } = opts;
  const 落 = (el) => occupantsOf(chart, el).map((o) => `${o.宫位}${o.字}${o.藏 ? `(${o.藏})` : ''}`);
  const 链 = [];
  const 路径 = [];
  let 结局 = null;
  let 当前 = 用神五行;

  while (链.length < 最大层数) {
    const K = 克我者(当前);      // 威胁当前者
    const X = 生我者(当前);      // 母亲 —— 通关护卫
    const Z = SHENG_MAP[当前];   // 儿子 —— 克"威胁当前者"者
    const X在 = 落(X);
    const Z在 = 落(Z);
    const 取 = X在.length ? '隔（通关）' : Z在.length ? '制' : null;
    链.push({
      层: 链.length, 被护卫者: 当前, 威胁者: K,
      隔护神: X, 隔护落点: X在,
      制护神: Z, 制护落点: Z在,
      采: 取, 护神: 取 === '隔（通关）' ? X : 取 === '制' ? Z : null,
      据: `${K}克${当前}；**隔途**：${X}为生${当前}者（${K}生${X}、${X}生${当前}）；`
        + `**制途**：${Z}为${当前}所生、${Z}克${K}。`,
    });
    路径.push(当前);
    if (!取) {
      结局 = { 类: '断链', 因: `局中既无${X}（生${当前}者）亦无${Z}（克${K}者），**${当前}无护**。`, 链长: 链.length };
      break;
    }
    const 下一 = 取 === '隔（通关）' ? X : Z;
    if (路径.includes(下一)) {
      const 环 = [...路径.slice(路径.indexOf(下一)), 下一];
      const 独异 = [...new Set(环.slice(0, -1))];
      结局 = {
        类: 独异.length === 5 ? '闭环' : '局部循环',
        环, 环上五行数: 独异.length, 链长: 链.length,
      };
      break;
    }
    当前 = 下一;
  }
  if (!结局) 结局 = { 类: '超出层数上限', 链长: 链.length };

  // 宫位校验：环上相邻两环之五行，在四柱中是否**贴身**（柱差 ≤ 1）或同宫。
  // —— 这正是"五行之环 ≠ 宫位关联"的落点。
  let 宫位校验 = null;
  if (结局.类 === '闭环' || 结局.类 === '局部循环') {
    const 环 = 结局.环;
    const 断处 = [];
    for (let i = 0; i < 环.length - 1; i++) {
      const A = occupantsOf(chart, 环[i]);
      const B = occupantsOf(chart, 环[i + 1]);
      const 有贴身 = A.some((a) => B.some((b) => proximityOf(a.宫位, b.宫位).柱差 <= 1));
      if (!有贴身) 断处.push(`${环[i]}—${环[i + 1]}`);
    }
    宫位校验 = {
      全贴身相连: 断处.length === 0,
      不贴身之处: 断处,
      说明: 断处.length
        ? `**五行之环虽闭合，但 ${断处.join('、')} 在四柱宫位上并不贴身**`
          + `——此即「五行有环 ≠ 宫位有关联」，故不得径以闭环判为结构稳定。`
        : '五行之环闭合，且环上各位在四柱宫位中两两贴身（宫位网络与五行之环相合）。',
    };
  }

  // ====================================================================
  // 全景护卫通路评估与剩余有效路数求值（D-041 裁定 · 判据 P-020）
  // ====================================================================
  const K = 克我者(用神五行);
  const X = 生我者(用神五行);     // 隔途通关神（母）
  const Z = SHENG_MAP[用神五行];  // 制途护卫神（子）

  const arb = arbitrateGanzhiForces(chart, { 岁运 });
  const zhicheng = arb.逐支受力 ?? [];

  function 评估通路(el, 途名) {
    const occs = occupantsOf(chart, el);
    const 落点名 = occs.map((o) => `${o.宫位}${o.字}${o.藏 ? `(${o.藏})` : ''}`);
    if (!occs.length) {
      return { 途径: 途名, 护神: el, 状态: '缺失', 有效: false, 落点: [], 力度档: '无', 受损: [] };
    }
    const pwr = powerOf(chart, el, { 岁运 });
    const brOccs = occs.filter((o) => o.层 !== '天干');
    const 受损支 = [];
    for (const bo of brOccs) {
      const match = zhicheng.find((z) => z.字 === bo.字 && bo.宫位.startsWith(z.宫位[0]));
      if (match && match.动摇否) {
        受损支.push({ 支: bo.字, 宫位: bo.宫位, 受力: match.最终受力 });
      }
    }

    if (pwr.档 === '弱') {
      return { 途径: 途名, 护神: el, 状态: '在位但不足力', 有效: false, 落点: 落点名, 力度档: pwr.档, 受损: 受损支 };
    }

    if (brOccs.length > 0 && 受损支.length === brOccs.length) {
      return { 途径: 途名, 护神: el, 状态: '受损动摇', 有效: false, 落点: 落点名, 力度档: pwr.档, 受损: 受损支 };
    }

    return { 途径: 途名, 护神: el, 状态: '畅通有效', 有效: true, 落点: 落点名, 力度档: pwr.档, 受损: 受损支 };
  }

  const 隔途 = 评估通路(X, '隔途通关');
  const 制途 = 评估通路(Z, '制途护卫');

  const 剩余有效路数 = (隔途.有效 ? 1 : 0) + (制途.有效 ? 1 : 0);
  const 状态定性 = 剩余有效路数 === 2 ? '双路齐备' : 剩余有效路数 === 1 ? '独木难支' : '衰竭断链';
  const 替代解 = (隔途.有效 && !制途.有效)
    ? '隔途替代制途'
    : (!隔途.有效 && 制途.有效)
      ? '制途替代隔途'
      : (隔途.有效 && 制途.有效)
        ? '双路齐备无须替代'
        : '无替代解';
  const 衰竭警报 = 剩余有效路数 === 0;
  const 警报说明 = 衰竭警报
    ? '【护卫衰竭警报】用神之隔途与制途双双失陷（缺失、不足力或被冲拔），克神长驱直入无遮挡！'
    : '护卫通路尚存依托，未触发衰竭警报。';

  const 全景通路 = {
    用神: 用神五行,
    克神: K,
    隔途,
    制途,
    剩余有效路数,
    状态定性,
    替代解,
    衰竭警报,
    警报说明,
  };

  return {
    用神: 用神五行,
    链,
    结局,
    宫位校验,
    结构: 结局.类 === '闭环'
      ? `**护卫链闭合**（环：${结局.环.join(' → ')}）——五行之气可循环相生，克者终被引化为生。`
      : 结局.类 === '局部循环'
        ? `**局部循环**（环：${结局.环.join(' → ')}，仅涉 ${结局.环上五行数} 行）`
          + `——非完整五行之环，环外仍有断处。`
        : `**断链**：${结局.因}`,
    全景通路,
    剩余有效路数,
    通路状态: 状态定性,
    衰竭警报,
    说明: '⚠ **本引擎不把"闭环"等同于"结构稳定"**：五行上的环（相生关系）与四柱上的宫位关联'
      + '（合冲刑害破、根是否被动摇）**不是同一件事**，二者**分开报**（宫位网络见 `structureOf`）。'
      + '使用者 2026-09-27 裁「不是同一件事」。故本函数只报链与环，**不作结构判断**。'
      + '⚠ 每层只判护神**在位与否**，未判其力度；须按 `tenGodStrength` 复核（在位者未必有力）。',
    据: '规格 §一之二「★ 护卫是相对概念，且递归」；使用者「依此类推」；决策编号 D-041',
  };
}

/**
 * **干支多重作用力并发优先级四维仲裁法则**（D-030 裁定）
 *
 * 依据四维仲裁法则：
 *   1. 物理贴身律：贴身（同柱/邻柱，柱差 <= 1）力 ＞ 隔位（柱差 = 2）力 ＞ 遥隔（柱差 = 3）力。
 *      贴身合解隔位冲（贪合免冲）；近冲破远合（贴身冲散隔位合）。
 *   2. 能级吞并律：三会(100) ＞ 三合(80) ＞ 六合/自合(60) ＞ 半合/暗合(40) ＞ 六冲(50) ＞ 刑(30) ＞ 穿(25) ＞ 破(20) ＞ 绝(15)。
 *   3. 生克转化律：贪合忘冲、贪生忘克（见印贴身引化则杀气转为顺生）。
 *   4. 受力状态精细化输出：安稳 / 贪合免冲 / 贪生免克 / 冲散破合 / 直克动摇。
 *
 * @param {object} chart
 * @param {{用神五行?: string, 岁运?: string}} [opts]
 */
export function arbitrateGanzhiForces(chart, opts = {}) {
  const { 用神五行 = null, 岁运 = null } = opts;
  const pillars = chart.pillars;
  const posNames = ['年柱', '月柱', '日柱', '时柱'];
  const posShort = ['年', '月', '日', '时'];
  const D = dayMasterOf(chart).element;

  let luckP = null;
  if (岁运 && 岁运.length >= 2) {
    const s = 岁运[0], b = 岁运[1];
    const si = STEMS.indexOf(s), bi = BRANCHES.indexOf(b);
    if (si >= 0 && bi >= 0) luckP = { stemIndex: si, branchIndex: bi };
  }
  const rels = gzRelations(pillars, luckP);

  const branches = pillars.map(branchAt);
  const stems = pillars.map((p) => p.stem);

  const 逐支受力 = [];

  for (let i = 0; i < 4; i++) {
    const b = branches[i];
    const pos = posNames[i];
    const shortPos = posShort[i];
    const label = `${shortPos}${b}`;

    // 1. 六冲
    const chongs = (rels['地支六冲'] ?? []).filter((x) => String(x.pair ?? x.positions ?? '').includes(label)).map((x) => {
      const pairStr = String(x.pair ?? x.positions ?? '');
      const otherLabel = pairStr.split(/[—、]/).map((s) => s.trim()).find((s) => !s.startsWith(shortPos));
      const otherPosIdx = otherLabel ? posShort.indexOf(otherLabel[0]) : -1;
      const dist = otherPosIdx >= 0 ? Math.abs(i - otherPosIdx) : 99;
      return { pair: pairStr, otherLabel, otherPosIdx, dist, note: x.note };
    });

    // 2. 六合与自合
    const liuhes = (rels['地支六合'] ?? []).filter((x) => String(x.pair ?? x.positions ?? '').includes(label)).map((x) => {
      const pairStr = String(x.pair ?? x.positions ?? '');
      const otherLabel = pairStr.split(/[—、]/).map((s) => s.trim()).find((s) => !s.startsWith(shortPos));
      const otherPosIdx = otherLabel ? posShort.indexOf(otherLabel[0]) : -1;
      const dist = otherPosIdx >= 0 ? Math.abs(i - otherPosIdx) : 99;
      return { pair: pairStr, otherLabel, otherPosIdx, dist, 化: x.化 };
    });
    const zihes = (rels['干支自合'] ?? []).filter((x) => x.pillar === shortPos).map((x) => ({
      pair: `${shortPos}柱${x.gz}`,
      otherLabel: `${shortPos}干${x.stem}`,
      otherPosIdx: i,
      dist: 0,
      合: x.合,
    }));
    const hes = [...liuhes, ...zihes];

    // 3. 刑害破绝
    const xings = (rels['地支相刑'] ?? []).filter((x) => String(x.pair ?? x.positions ?? '').includes(label));
    const hais = (rels['地支相害'] ?? []).filter((x) => String(x.pair ?? x.positions ?? '').includes(label));
    const posList = (rels['地支相破'] ?? []).filter((x) => String(x.pair ?? x.positions ?? '').includes(label));
    const jues = (rels['地支相绝'] ?? []).filter((x) => String(x.pair ?? x.positions ?? '').includes(label));

    // 4. 印星贴身引化（贪生忘克）
    let hasYinTransform = false;
    let yinNote = '';
    const bElem = ELEMENTS[BRANCH_ELEMENT[BRANCHES.indexOf(b)]];
    const shengB = 生我者(bElem);
    for (let j = 0; j < 4; j++) {
      if (Math.abs(i - j) <= 1 && j !== i) {
        if (ELEMENTS[STEM_ELEMENT[STEMS.indexOf(stems[j])]] === shengB ||
            ELEMENTS[BRANCH_ELEMENT[BRANCHES.indexOf(branches[j])]] === shengB) {
          hasYinTransform = true;
          yinNote = `${posShort[j]}见${shengB}贴身引化`;
          break;
        }
      }
    }

    // 5. 四维仲裁
    let 最终受力 = '安稳';
    let 仲裁依据 = '原局未见冲刑穿破，受力安稳';
    let 动摇否 = false;

    const minDistChong = chongs.length ? Math.min(...chongs.map((c) => c.dist)) : 999;
    const minDistHe = hes.length ? Math.min(...hes.map((h) => h.dist)) : 999;
    const hasChong = chongs.length > 0;
    const hasHe = hes.length > 0;
    const hasXingHaiPo = (xings.length + hais.length + posList.length + jues.length) > 0;

    if (hasChong && hasHe) {
      if (minDistHe <= 1 && minDistChong >= 2) {
        最终受力 = '贪合免冲';
        仲裁依据 = `贴身相合（柱差${minDistHe}）力大优先，解开隔位相冲（柱差${minDistChong}），字受牵绊合留，贪合忘冲`;
        动摇否 = false;
      } else if (minDistChong <= 1 && minDistHe >= 2) {
        最终受力 = '冲散破合';
        仲裁依据 = `贴身相冲（柱差${minDistChong}）剧烈冲击，近冲破远合，撕裂隔位相合（柱差${minDistHe}），破合动摇`;
        动摇否 = true;
      } else if (minDistChong <= 1 && minDistHe <= 1) {
        最终受力 = '冲散破合';
        仲裁依据 = `冲合俱贴身贴身战克，虽有合象但冲击已至，做功与动摇并见`;
        动摇否 = true;
      } else {
        最终受力 = '贪合免冲';
        仲裁依据 = `合能级优于冲能级，合力羁绊免除动摇`;
        动摇否 = false;
      }
    } else if (hasChong && !hasHe) {
      if (hasYinTransform && minDistChong >= 2) {
        最终受力 = '贪生免克';
        仲裁依据 = `虽有隔位冲克，但得${yinNote}，冲克之气受化，贪生忘克免动摇`;
        动摇否 = false;
      } else {
        最终受力 = '直克动摇';
        仲裁依据 = `原局见相冲（最近柱差${minDistChong}）且无贴身合解救，根基动摇`;
        动摇否 = true;
      }
    } else if (!hasChong && hasXingHaiPo) {
      if (hasHe && minDistHe <= 1) {
        最终受力 = '贪合免冲';
        仲裁依据 = `贴身相合牵住，化解刑穿破害之扰，不作动摇论`;
        动摇否 = false;
      } else {
        最终受力 = '直克动摇';
        仲裁依据 = `受刑穿破害侵扰且无合解，根基动摇`;
        动摇否 = true;
      }
    } else {
      最终受力 = '安稳';
      仲裁依据 = '原局无冲刑穿破，受力安稳';
      动摇否 = false;
    }

    逐支受力.push({
      宫位: pos,
      字: b,
      六冲: chongs,
      相合: hes,
      刑害破绝: { xings, hais, pos: posList, jues },
      最终受力,
      仲裁依据,
      动摇否,
    });
  }

  const 汇总 = {
    安稳数: 逐支受力.filter((x) => x.最终受力 === '安稳').length,
    贪合免冲数: 逐支受力.filter((x) => x.最终受力 === '贪合免冲').length,
    贪生免克数: 逐支受力.filter((x) => x.最终受力 === '贪生免克').length,
    冲散破合数: 逐支受力.filter((x) => x.最终受力 === '冲散破合').length,
    直克动摇数: 逐支受力.filter((x) => x.最终受力 === '直克动摇').length,
  };

  const 总评 = `干支多重作用力四维仲裁完成：`
    + `安稳 ${汇总.安稳数} 支；`
    + `贪合免冲 ${汇总.贪合免冲数} 支；`
    + `贪生免克 ${汇总.贪生免克数} 支；`
    + `冲散破合 ${汇总.冲散破合数} 支；`
    + `直克动摇 ${汇总.直克动摇数} 支。`
    + (汇总.贪合免冲数 > 0 ? '【贴身合解隔位冲】成立；' : '')
    + (汇总.冲散破合数 > 0 ? '【近冲破远合】成立；' : '');

  return {
    法则: '四维物理仲裁（贴身律/能级律/转化律/状态输出）',
    逐支受力,
    汇总,
    总评,
  };
}

/**
 * **第 4 条 · 结构稳定性**（规格 §一之二）。
 *
 * 判据**不是**某一行力量，而是**四柱关联网络是否被切断**：
 * 日主之根、用神之根**所在之支**是否被冲／刑／穿／破（合则另论）。
 * 可传入岁运干支，判该岁运是否**切断根基**。
 *
 * @param {object} chart
 * @param {{用神五行?: string, 岁运?: string}} [opts] 岁运为两字干支，如 '丙寅'
 */
export function structureOf(chart, opts = {}) {
  const D = dayMasterOf(chart).element;
  const { 用神五行 = null, 岁运 = null } = opts;
  const r = relationsOf(chart.pillars);
  const 仲裁 = arbitrateGanzhiForces(chart, opts);
  const 破害键 = [['地支六冲', '冲'], ['地支相刑', '刑'], ['地支相害', '穿'], ['地支相破', '破']];

  const 查根 = (el, 名) => {
    const 根 = occupantsOf(chart, el).filter((o) => o.层 !== '天干');
    return {
      名, 五行: el, 有根: 根.length > 0,
      根: 根.map((o) => {
        const 损 = 受损Of(r, o.宫位, o.字, o.层);
        const 被 = 损.filter((x) => x.途 !== '合');
        const 合 = 损.filter((x) => x.途 === '合');
        const posShort = String(o.宫位)[0];
        const zhicheng = 仲裁.逐支受力.find((z) => z.宫位.startsWith(posShort));
        const 受力状态 = zhicheng?.最终受力 ?? (被.length > 0 ? '直克动摇' : '安稳');
        return {
          宫位: o.宫位, 字: o.字, 藏: o.藏, 层次: o.层, 宫位分量: o.宫位分量,
          被冲刑穿破: 受损文字(被), 被合: 受损文字(合), 被动摇: 被.length > 0,
          受力状态,
          仲裁依据: zhicheng?.仲裁依据 ?? '',
        };
      }),
    };
  };

  const 日主根 = 查根(D, '日主之根');
  const 用神根 = 用神五行 ? 查根(用神五行, '用神之根') : null;

  let 岁运段 = null;
  if (岁运) {
    const gz = String(岁运);
    const stemIndex = STEMS.indexOf(gz[0]);
    const branchIndex = BRANCHES.indexOf(gz[1]);
    if (stemIndex < 0 || branchIndex < 0 || gz.length !== 2) throw new Error(`structureOf: 岁运须为两字干支，收到「${岁运}」`);
    const rr = gzRelations(chart.pillars, { stemIndex, branchIndex });
    const 切 = [];
    for (const [名, root] of [['日主之根', 日主根], ['用神之根', 用神根]].filter((x) => x[1])) {
      for (const g of root.根) {
        const label = `${g.宫位[0]}${g.字}`;
        for (const [k, kind] of 破害键) for (const e of rr[k] ?? []) {
          if (String(e.pair).includes(label) && String(e.pair).includes('大运')) {
            切.push({ 根: `${名}·${g.宫位}${g.字}`, 途: kind, 关系: e.pair });
          }
        }
      }
    }
    const 岁运落点 = [`大运干${gz[0]}`, `大运支${gz[1]}`];
    岁运段 = {
      干支: 岁运, 岁运落点, 与原局关系: rr, 切根: 切,
      结论: 切.length
        ? `**岁运切断根基**：${切.map((x) => `${x.根}被${x.途}（${x.关系}）`).join('、')}`
        : '该岁运未直接冲刑原局之根。',
    };
  }

  // 去重：日主之根与用神之根**常为同一批支**（同一支可同时载日主之气与用神之气，
  // 如寅载甲(木)与丙(火)；用神五行＝日主五行时更是完全同根，如丁火日主取火为用）。
  // 旧实现把两列表直接拼接，导致同一根被计两次、「原局有 N 处根被动摇」数字翻倍（2→4）。
  const 根键 = (x) => `${x.宫位}|${x.字}|${x.层次}`;
  const 动摇根 = (root) => (root?.根 ?? []).filter((g) => g.被动摇);
  const 日主动摇 = 动摇根(日主根);
  const 用神动摇 = 动摇根(用神根);
  const 日主键 = new Set(日主动摇.map(根键));
  const 用神键 = new Set(用神动摇.map(根键));
  const 动摇 = [];
  const 已见 = new Set();
  for (const [名, list] of [['日主之根', 日主动摇], ['用神之根', 用神动摇]]) {
    for (const g of list) {
      const k = 根键(g);
      if (已见.has(k)) continue;
      已见.add(k);
      动摇.push({ ...g, 兼: 名, 同根: 日主键.has(k) && 用神键.has(k) });
    }
  }
  const 动摇数 = {
    日主之根: 日主键.size,
    用神之根: 用神键.size,
    同根: [...日主键].filter((k) => 用神键.has(k)).length,
    合计: 动摇.length,
  };
  const 名短 = { 日主之根: '日主', 用神之根: '用神' };

  // ★（一）「合」计入动根 —— 使用者 2026-09-28 裁「**算**，但是要看谁去合谁」。
  // 三层合看：①被合者身份（日主之根／用神之根…）②合的方向（外来合走 / 合入家中）③合方本身对全局之吉凶。
  // 特例：忌神来合用神 ≠ 用神被坏，而是"用神锁住忌神、发挥了作用"（但用神自身被占用，仍有代价）。
  const 合判 = [];
  const 合已见 = new Set();
  const 内外 = (宫) => (String(宫).startsWith('年') || String(宫).startsWith('月')) ? '外' : '内';
  const 六合对 = r.地支六合 ?? [];
  for (const [名, list] of [['日主之根', 日主根.根], ['用神之根', 用神根?.根 ?? []]]) {
    for (const g of list) {
      const 本 = `${String(g.宫位)[0]}${g.字}`;                 // 如「年巳」
      for (const h of 六合对) {
        const pair = String(h.pair ?? '');
        if (!pair.includes(本)) continue;
        const parts = pair.split('—').map((s) => s.trim());
        const 他 = parts.find((p) => p !== 本) ?? '';
        const 他支 = 他.slice(-1);
        const bi = BRANCHES.indexOf(他支);
        if (bi < 0) continue;
        const 他五行 = ELEMENTS[BRANCH_ELEMENT[bi]];
        const 他处 = 他.startsWith('大运') ? '大运' : (他.startsWith('年') || 他.startsWith('月') ? '外' : '内');
        const key = `${名}|${g.宫位}${g.字}|${他}`;
        if (合已见.has(key)) continue;
        合已见.add(key);
        const 对日主 = 他五行 === 克我者(D) ? '克我(官杀)' : 他五行 === 生我者(D) ? '生我(印)' : 他五行 === SHENG_MAP[D] ? '我生(食伤)' : 他五行 === KE_MAP[D] ? '我克(财)' : '同我(比劫)';
        let 判;
        if (名 === '日主之根' && 他五行 === 克我者(D)) {
          判 = `⚠ 日主之根被**官杀（${他五行}）**合走 ⇒ 按使用者「卯被申合走」之例，**不吉**`;
        } else if (名 === '日主之根' && 他五行 === 生我者(D)) {
          判 = `日主之根与**印（${他五行}）**相合（${他处}方），「外来喜神被合入家中」之型 ⇒ **偏吉**，仍须看该神对全局吉凶`;
        } else if (名 === '用神之根' && 用神五行 && 他五行 === 克我者(用神五行)) {
          判 = `⚠ 用神之根被**克用神者（${他五行}）**合走 ⇒ 用神之根被动摇`;
        } else if (名 === '用神之根' && 用神五行 && 他五行 === KE_MAP[用神五行]) {
          判 = `用神之根与**用神所克者（${他五行}）**相合 ⇒ 正是「**火去合克金**」之型：用神合忌神＝做功，`
            + `**但用神之根被牵住、须标代价**（使用者例：壬合丁，丁发挥作用、丙不受伤，但"会有影响"）`;
        } else if (名 === '用神之根' && 用神五行 && 他五行 === 生我者(用神五行)) {
          判 = `用神之根与**生用神者（${他五行}）**相合 ⇒ 用神之源被牵住，**做功但须标代价**（使用者：「发挥了作用……但是会有影响」）`;
        } else {
          判 = `见合（${pair}）：计入动根；吉凶须按合方（${他五行}·${对日主}）对全局之角色定，引擎不预判`;
        }
        合判.push({
          被合者: `${名}·${g.宫位}${g.字}`, 合方: 他, 合方五行: 他五行, 合方与日主: 对日主,
          内外: `${内外(g.宫位)}×${他处}`, 化: h.化 ?? null, 判语: 判,
        });
      }
    }
  }

  const 结语 = [];
  if (!日主根.有根) {
    结语.push(`⚠ **日主${D}地支无根**（四支藏干皆无${D}）——`
      + `此即规格 §二所指「从」的前提（日主无一丝生扶）；**须先走特殊格局排查**，不可径以正格论强弱。`);
  }
  if (动摇.length) {
    const 角色 = 动摇数.同根
      ? `（日主之根 ${动摇数.日主之根} 处、用神之根 ${动摇数.用神之根} 处，其中 **${动摇数.同根} 处为日主与用神同根**）`
      : `（日主之根 ${动摇数.日主之根} 处、用神之根 ${动摇数.用神之根} 处）`;
    结语.push(`原局有 ${动摇.length} 处根被动摇${角色}：`
      + `${动摇.map((x) => `${名短[x.兼]}${x.同根 ? '·同根' : ''}${x.宫位}${x.字}`).join('、')}。`
      + `⚠ **「根被冲刑」不等于结构即破**：合与冲并见（如巳申既六合又相破）、或冲而逢合救，`
      + `须并陈两说，不得径判结构已破。`);
  }
  if (合判.length) {
    结语.push(`另有 **${合判.length} 处根被「合」**（使用者 2026-09-28 裁：**合亦计入动根，但须辨谁合谁**）：`
      + 合判.map((x) => `${x.被合者}—${x.合方}[${x.内外}${x.化 ? `化${x.化}` : ''}]${x.判语}`).join('；'));
  }
  if (岁运段?.切根.length) {
    结语.push(岁运段.结论 + `（所切者：${岁运段.切根.map((x) => `${x.根}·${x.途}`).join('、')}）`);
  }
    if (!结语.length) {
    结语.push(用神根
      ? '原局日主之根与用神之根皆未被冲刑穿破，结构未见切断。'
      : '原局**日主之根**未见冲刑穿破；⚠ **用神未声明 ⇒ 用神之根未算**，故本节不含用神之根的结论。');
  }

  if (仲裁?.总评) {
    结语.push(`【干支受力仲裁】${仲裁.总评}`);
  }

  return {
    日主五行: D,
    原局关联: r,
    多重仲裁: 仲裁,
    日主之根: 日主根,
    用神之根: 用神根,
    岁运: 岁运段,
    动摇之根: 动摇.map((x) => `${x.宫位}${x.字}（${x.同根 ? '日主与用神同根；' : ''}${x.被冲刑穿破.join('、')}；受力：${x.受力状态 ?? '直克动摇'}）`),
    动摇计数: { 合计: 动摇.length, ...动摇数 },
    受力汇总: 仲裁.汇总,
    合之动根: 合判,
    结论: 结语.join(' '),
    说明: '本节只报**关联网络**与**根是否被动摇**，不代判格局成败；'
      + '"护卫链闭环 ＝ 结构稳定"是引擎作者的推断、**非使用者原话**，故不写入本函数结论（规格 §一之二 复盘第 3 条）。',
    据: '规格 §一之二「第 4 条 · 根基」；《滴天髓》通关章；D-030 干支多重作用力并发四维仲裁法则',
  };
}

/**
 * **承载重估** —— 使用者 2026-09-28：「官杀是好是坏，看**日主能否承载**」；
> 而承载**随运可升**：大运／流年若补根（比劫、印之本气）则承载升 ⇒ 官杀由"杀"转"贵"；出运复原。
 * ★ **夺根降级与动态重估（D-040 / P-019 落地）**：本函数已实现岁运六冲夺根检测，
 *   若日主本气通根被冲拔，判定为「夺根降级」；尚余本气根则判「动摇降级」；出运复原。
 *
 * 口径并陈：**实战派**——中气、余气不算正式根气；**子平**——另计通根深浅。本表两层都报。
 *
 * @param {object} chart
 * @param {{岁运?: string}} [opts] 指定某一步岁运；缺省则逐大运全列
 */
export function chengzaiReassess(chart, opts = {}) {
  const D = dayMasterOf(chart).element;
  const 同党 = [D, 生我者(D)];                 // 比劫 + 印
  const 官杀 = 克我者(D);
  const 原 = threatOf(chart).分组条件 ?? {};
  const 原得地 = 原.得地 ?? [];
  const 原得势 = 原.得势 ?? [];
  const 原可任 = (原得地.length > 0 || 原得势.length > 0);
  const 评一运 = (gz, 标签) => {
    const s = String(gz);
    const si = STEMS.indexOf(s[0]);
    const bi = BRANCHES.indexOf(s[1]);
    if (s.length !== 2 || si < 0 || bi < 0) return null;
    const 干五行 = ELEMENTS[STEM_ELEMENT[si]];
    const 支本五行 = ELEMENTS[BRANCH_ELEMENT[bi]];
    const 支藏 = HIDDEN_STEMS_SPEC[bi].map(([字, 层]) => ({ 字, 层, 五行: ELEMENTS[STEM_ELEMENT[STEMS.indexOf(字)]] }));
    const 补势 = 同党.includes(干五行);
    const 支本党 = 同党.includes(支本五行);
    const 支中本气党 = 支藏.filter((h) => h.层 === '本' && 同党.includes(h.五行));
    const 余中气党 = 支藏.filter((h) => h.层 !== '本' && 同党.includes(h.五行));
    const 得地 = 支本党 || 支中本气党.length > 0;

    // 夺根检测（P-019 / D-040）：岁运地支是否六冲原局日主通根之支
    const 被冲之根 = [];
    const 未冲之根 = [];
    for (const r of 原得地) {
      const 根支 = r.位.replace(/^[年月日時]支/, '');
      const 冲对 = s[1] + 根支;
      const 冲对反 = 根支 + s[1];
      const 是六冲 = BRANCH_CLASH.includes(冲对) || BRANCH_CLASH.includes(冲对反);
      if (是六冲) 被冲之根.push(r);
      else 未冲之根.push(r);
    }
    const 有夺根 = 被冲之根.length > 0;
    const 尚余本气 = 未冲之根.some((x) => x.层 === '本气');
    let 降级定性 = '无';
    let 夺根说明 = '未见岁运冲拔通根';
    if (有夺根) {
      if (!尚余本气) {
        降级定性 = '夺根降级';
        夺根说明 = `此运${s[1]}冲拔原局${被冲之根.map((x) => x.位).join('、')}，通根拔动尽失，日主承载断崖式下跌，官杀由"贵"转"凶煞攻身"`;
      } else {
        降级定性 = '动摇降级';
        夺根说明 = `此运${s[1]}冲损原局${被冲之根.map((x) => x.位).join('、')}，通根受损动摇，日主承载减弱`;
      }
    }

    const 判 = 原可任
      ? 降级定性 === '夺根降级'
        ? `**夺根降级**（${夺根说明}）`
        : 降级定性 === '动摇降级'
          ? `**动摇降级**（${夺根说明}）`
          : '可任（原局已可任，运不改前提）'
      : 得地
        ? '**可任**（此运补根 ⇒ 官杀由"杀"转"贵"，须"供起来：不可伤"）'
        : 补势
          ? '偏可任但**根未补**（此运只补势——实战派口径中余气/透干不算正式根气，故仍以"不可任"为准；子平口径另计通根，并陈）'
          : 有夺根
            ? `仍不可任（此运未补根势，且${s[1]}冲拔${被冲之根.map((x) => x.位).join('、')}，雪上加霜）`
            : '仍不可任（此运未补根势）';

    return {
      标签, 干支: s,
      干: `${s[0]}(${干五行})${补势 ? '＝同党' : ''}${干五行 === 官杀 ? '＝官杀' : ''}`,
      支: `${s[1]}(${支本五行})`,
      支藏: 支藏.map((h) => `${h.字}(${h.五行}·${h.层})`),
      补势, 补根: 得地,
      补根据: 支本党 ? '支本气即同党' : 支中本气党.length ? `支中本气藏${支中本气党.map((h) => h.字).join('、')}`
        : 余中气党.length ? `仅中/余气藏${余中气党.map((h) => h.字).join('、')}（不算正式根气）` : '无',
      夺根: {
        有夺根,
        被冲根: 被冲之根.map((x) => `${x.位}(${x.层})`),
        未冲根: 未冲之根.map((x) => `${x.位}(${x.层})`),
        降级定性,
        说明: 夺根说明,
      },
      判, 结论: `${标签}${s}：${判}`,
    };
  };
  const 逐运 = (chart.luck?.pillars ?? []).map((lp) => 评一运(lp.gz, `第${lp.step}步大运 `)).filter(Boolean);
  const 指定 = opts.岁运 ? 评一运(opts.岁运, '指定岁运 ') : null;
  const 首补 = 逐运.find((x) => /^\*\*可任\*\*/.test(x.判));   // 只认"补根"那一档；「偏可任但根未补」不算
  const 首夺 = 逐运.find((x) => x.夺根?.降级定性 === '夺根降级');
  return {
    原局判: 原可任 ? '可任' : '不可任',
    原局据: `得地 ${原得地.length}／得势 ${原得势.length}`,
    指定岁运: 指定,
    逐运,
    首个补根之运: 首补 ?? null,
    首个夺根之运: 首夺 ?? null,
    结论: 指定 ? 指定.结论 : 原可任
      ? 首夺
        ? `原局已可任；但行至 ${首夺.干支} 运夺根降级（${首夺.夺根.说明}）⇒ 官杀反转为"凶煞"，出运后方复原。`
        : '原局已可任 ⇒ 官杀为贵气，不因运改前提（仍须防运中**制伏太过**）。'
      : 首补
        ? `原局不可任；**至 ${首补.干支} 运补根，承载转"可任"** ⇒ 自该运起官杀由"杀"转"贵"，`
          + `须改按"供起来：不可伤"论；此前诸运仍按"须制化"论。**出运后复原。**`
        : '原局不可任，且所列大运**皆未补根** ⇒ 官杀始终为"杀"，一路须制化。',
    注: '承载随运双向动态重估：① 运逢比劫印绶本气则补根上升（杀转为贵）；'
      + '② 运支六冲拔原局通根则夺根降级（贵反转为凶煞攻身，落实判据 P-019）。出运后复原。',
  };
}

/**
 * **相战择手段** —— 使用者 2026-09-28：「**通关先看能不能解决主要矛盾**（比如木日主，金克木，水来通关），
 * 或是**财印两战，比劫通关**。**哪种手段最好用用哪个**。」
 *
 * ⇒ **不以"通关优先"或"压制优先"为定则**：对每个候选手段（通关／制／化／泄／帮）逐个评两件事——
 * ① 能否**真解决**主要矛盾；② 会不会**造成新的更大矛盾**；**净效果最好者胜**，不选者并陈代价。
 *
 * 相战来源有二：① `tongguanOf` 的对称强神相战（12% 阈值）；② **官杀（或财）与日主**这一对——
 * 后者常被阈值漏掉，却是"先保命"所指的正主。
 *
 * @param {object} chart
 * @param {{用神五行?: string}} [opts]
 */
export function xiangzhanOf(chart, opts = {}) {
  const D = dayMasterOf(chart).element;
  const 病 = 克我者(D);      // 克日主者（官杀）
  const 耗 = KE_MAP[D];      // 耗日主者（财）
  const tg = tongguanOf(chart);
  const 占比 = tg.五行占比;
  const 主要病 = (占比[病] ?? 0) >= (占比[耗] ?? 0) ? 病 : 耗;
  const 落 = (el) => occupantsOf(chart, el).map((o) => `${o.宫位}${o.字}${o.藏 ? `(${o.藏})` : ''}`);
  const 评 = (手段, el) => {
    const 位 = 落(el);
    if (!位.length) return { 手段, 五行: el, 在局: false, 净判: '不在局（须待岁运）' };
    const 力 = powerOf(chart, el);
    const 解主矛 = el === 克我者(主要病);
    const 新病 = [];
    if (el === 主要病 || SHENG_MAP[el] === 主要病) 新病.push(`助长**主要病神（${主要病}）**`);
    if (opts.用神五行 && el === 克我者(opts.用神五行)) 新病.push(`**克用神${opts.用神五行}**（灭工具）`);
    const 净判 = 解主矛 && !新病.length ? '**最好用**'
      : 解主矛 ? '能解主矛，但有代价' : !新病.length ? '无益无害' : '**不好用**';
    return {
      手段, 五行: el, 在局: true, 落点: 位, 力度档: 力.档,
      能否解主要矛盾: 解主矛, 会否造成新的更大矛盾: 新病.length ? 新病 : '否', 净判,
    };
  };
  const 秩 = { '**最好用**': 0, '能解主矛，但有代价': 1, '无益无害': 2, '**不好用**': 3, '不在局（须待岁运）': 4 };
  const 对 = [];
  const 见 = new Set();
  const 装 = (甲, 乙, X, 源) => {
    const k = `${甲}克${乙}`;
    if (见.has(k)) return;
    见.add(k);
    const 手段 = [
      评('通关（甲生X、X生乙）／泄甲', X),
      评('制甲（克甲者）', 克我者(甲)),
      评('帮乙（受克者）', 乙),
    ];
    const 候选 = 手段.filter((m) => m.在局).sort((a, b) => (秩[a.净判] ?? 9) - (秩[b.净判] ?? 9));
    const 优 = (候选[0] && (秩[候选[0].净判] ?? 9) <= 1) ? 候选[0] : null;
    对.push({
      相战: `${甲}克${乙}`, 来源: 源, 甲: `${甲}(${占比[甲] ?? '—'}%)`, 乙: `${乙}(${占比[乙] ?? '—'}%)`,
      通关神: X, 手段, 择优: 优,
      结论: 优
                ? `${优.净判 === '**最好用**' ? '本对**最好用**的手段' : '本对**最优（但有代价）**的手段'}＝**${优.五行}**（${优.手段}，${优.净判}）；`
          + `其余${手段.filter((m) => m !== 优).map((m) => `${m.五行}（${m.净判}）`).join('、')}。`
        : `本对**无好用手段**（${候选.length ? 候选.map((m) => `${m.五行}：${m.净判}`).join('、') : '候选皆不在局'}）`
          + `⇒ 须并陈各自代价，或待岁运引通之神到位。`,
      说明: `不以"通关优先"为定则：逐个评"能否真解主要矛盾 × 会否造成新的更大矛盾"，净效果最好者胜。`,
    });
  };
  for (const x of tg.相战 ?? []) 装(x.甲方.五行, x.乙方.五行, x.通关神, '对称强神相战（12% 阈值）');
  装(病, D, SHENG_MAP[病], '★ 官杀／财 与日主（"先保命"所指之正主，常被阈值漏掉）');
  const 总择优 = 对.map((p) => p.择优).filter(Boolean);
  return {
    主要病神: 主要病,
    口径: '主要病神暂取"克日主者(官杀)与耗日主者(财)中占比更高者"，**须调用方核定**',
    相战: 对,
    总择: 总择优.length
      ? `全盘择优：${[...new Set(总择优.map((m) => m.五行))].join('、')}`
        + `（${总择优.map((m) => `${m.手段}=${m.五行}·${m.净判}`).join('；')}）`
      : '全盘无好用手段 ⇒ 只有并陈代价、或待岁运。',
    说明: tg.说明,
    注: '两神相战本身未必是病；通关只是候选之一（使用者 2026-09-28：「哪种手段最好用用哪个」）。',
  };
}

/**
 * **犯旺** —— 使用者 2026-10-04 重定义：
 * 「命局中某种五行**已经达到旺极的状态**，大运流年又来**冲克**这个五行，就叫犯旺。**注意是旺极**。」
 *
 * 三步（缺一不可）：
 *   ① **旺极**：`powerOf(该五行).档 === '极'`（**引擎操作化**，非古籍明文）
 *   ② **岁运来犯**：该步岁运**克**（岁运干／支克之）或**冲**（岁运支与旺极之支相冲）该五行
 *   ③ **只作次要一条**，不得篡改主要矛盾结论
 * ⚠ **犯旺是岁运之事** ⇒ **未给岁运者不报**。
 * ⚠ 与 `qingOf.结构分析.犯旺`（旧口径＝本局某字激次要矛盾）**不是一回事**，勿互相代入。
 *
 * @param {object} chart
 * @param {{岁运?: string}} [opts]
 */
export function fanwangOf(chart, opts = {}) {
  const { 岁运 = null } = opts;
  const 据 = '使用者 2026-10-04 原话（见 体用路线法.md §一之二（八）三）；'
    + '「旺极」取 `powerOf` 档「极」为**引擎操作化**。';
  if (!岁运) {
    return {
      有: false, 岁运: null, 旺极者: [], 命中: [], 逐五行: [],
      结论: '未给岁运 ⇒ 按 体用路线法.md §一之二（八）三，**犯旺是岁运之事，不报**。',
      注: '要判犯旺须传岁运（大运或流年干支）。',
      据,
    };
  }
  const gz = String(岁运);
  if (gz.length !== 2 || STEMS.indexOf(gz[0]) < 0 || BRANCHES.indexOf(gz[1]) < 0) {
    throw new Error(`fanwangOf: 岁运须为两字干支，收到「${岁运}」`);
  }
  const si = STEMS.indexOf(gz[0]);
  const bi = BRANCHES.indexOf(gz[1]);
  const 干五行 = ELEMENTS[STEM_ELEMENT[si]];
  const 支五行 = ELEMENTS[BRANCH_ELEMENT[bi]];
  const 一览 = ELEMENTS.map((el) => {
    const 落点 = occupantsOf(chart, el);
    if (!落点.length) return null;
    const p = powerOf(chart, el);
    const 支落 = [...new Set(落点.filter((o) => o.层 !== '天干').map((o) => o.字))];
    const 被冲 = 支落.filter((z) => { const i = BRANCHES.indexOf(z); return i >= 0 && (i + 6) % 12 === bi; });
    const 途径 = [];
    if (KE_MAP[干五行] === el) 途径.push(`岁运干${gz[0]}（${干五行}）**克**${el}`);
    if (KE_MAP[支五行] === el) 途径.push(`岁运支${gz[1]}（${支五行}）**克**${el}`);
    if (被冲.length) 途径.push(`岁运支${gz[1]}与 ${被冲.join('、')} 相**冲**`);
    return {
      五行: el, 档: p.档, 占比: p.占比,
      落点: 落点.map((o) => `${o.宫位}${o.字}${o.藏 ? `(${o.藏})` : ''}`),
      旺极: p.档 === '极', 途径,
    };
  }).filter(Boolean);
  const 极者 = 一览.filter((x) => x.旺极);
  const 命中 = 极者.filter((x) => x.途径.length);
  return {
    有: 命中.length > 0,
    岁运: gz,
    岁运五行: { 干: 干五行, 支: 支五行 },
    旺极者: 极者.map((x) => `${x.五行}（占比 ${x.占比}%，落点 ${x.落点.join('、')}）`),
    逐五行: 一览,
    命中: 命中.map((x) => ({ 五行: x.五行, 档: x.档, 途径: x.途径 })),
    结论: 命中.length
      ? `⚠ **犯旺**（**只作次要一条**）：${命中.map((x) => `**${x.五行}**已旺极（档「${x.档}」），而${x.途径.join('、')}`).join('；')}。`
        + '⇒ 按使用者 2026-10-04 口径，**旺极之神不可犯，犯之则激**；但**不得篡改主要矛盾结论**。'
      : (极者.length
        ? `本步岁运 **${gz}** 未冲克局中旺极之五行（${极者.map((x) => x.五行).join('、')}）⇒ **不成犯旺**。`
        : '局中**无「旺极」之五行**（`powerOf` 档皆非「极」）⇒ 按新口径**不成犯旺**。'),
    注: '⚠ 与 `qingOf.结构分析.犯旺`（旧口径＝本局某字激次要矛盾）**不是一回事**，勿互相代入。'
      + '只作次要一条；⚠ 仅当被犯后新格局**确已更大**，才据第 1 条重评主要矛盾'
      + '（须落本盘事实四途重查，或明确挂"待岁运验证"），否则并入忌神、**不得倒推成"主要矛盾变了"**。',
    据,
  };
}

/**
 * **干支自合与地支暗合判定**（P-015 · D-029 裁定）
 *
 * 识别七大干支自合柱与三大地支通合，输出结构化判定枚举与做功解读。
 *
 * @param {object} chart
 * @param {{岁运?: string}} [opts]
 */
export function selfHiddenCombineOf(chart, opts = {}) {
  let luckP = null;
  if (opts.岁运 && opts.岁运.length >= 2) {
    const s = opts.岁运[0], b = opts.岁运[1];
    const si = STEMS.indexOf(s), bi = BRANCHES.indexOf(b);
    if (si >= 0 && bi >= 0) luckP = { stemIndex: si, branchIndex: bi };
  }
  const rels = gzRelations(chart.pillars, luckP);
  const zfs = rels['干支自合'] ?? [];
  const ahs = rels['地支暗合'] ?? [];
  const riZihe = zfs.find((x) => x.pillar === '日') ?? null;
  const taZihe = zfs.filter((x) => x.pillar !== '日');

  let 判定 = '无暗合';
  if (riZihe && ahs.length > 0) {
    判定 = '自合兼暗合';
  } else if (riZihe && ahs.length === 0) {
    判定 = '日柱自合';
  } else if (!riZihe && taZihe.length > 0 && ahs.length > 0) {
    判定 = '自合兼暗合';
  } else if (!riZihe && taZihe.length > 0 && ahs.length === 0) {
    判定 = '他柱自合';
  } else if (zfs.length === 0 && ahs.length > 0) {
    判定 = '地支暗合';
  }

  const 说明条 = [];
  if (riZihe) {
    说明条.push(`日柱【${riZihe.gz}】自坐暗合（${riZihe.合}，暗藏${riZihe.藏干}）：同柱干支自合自绊，情向内敛，吉凶受全局主要矛盾与用忌统率`);
  }
  for (const tz of taZihe) {
    说明条.push(`${tz.pillar}柱【${tz.gz}】自合（${tz.合}，暗藏${tz.藏干}）：同柱干支相引自合，情向内敛`);
  }
  for (const ah of ahs) {
    说明条.push(`地支【${ah.pair}】暗合（${ah.合}）：${ah.note}`);
  }
  if (说明条.length === 0) {
    说明条.push('局中无干支自合柱，亦无地支暗合，纯以正五行明见刑冲生克论做功');
  }

  return {
    判定,
    日柱自合: riZihe,
    他柱自合: taZihe,
    地支暗合: ahs,
    自合明细: zfs,
    说明: 说明条.join('；'),
    据: 'P-015 判据 / D-029 裁定：干支自合七柱与地支暗合三组识别法则',
  };
}

