/**
 * **全天干地支作用关系《双轨意象矩阵与动态输出系统》**（D-031 裁定）
 *
 * 根据命盘的主要矛盾与用忌统率，对全局检出的物理关系动态定性为【为喜】、【为忌】或【中性】，
 * 并分别映射建设性喜象与破坏性忌象。
 *
 * @param {object} chart
 * @param {{主要矛盾?: object, 用神五行?: string, 岁运?: string}} [opts]
 */
export function dualImageMatrixOf(chart, opts = {}) {
  const { 主要矛盾 = null, 用神五行 = null, 岁运 = null } = opts;
  const D = dayMasterOf(chart).element;
  const dayStem = dayMasterOf(chart).stem;
  const luBranch = LUSHEN ? LUSHEN[dayStem] : null;

  // 1. 确定全局用神五行
  let yongEl = 用神五行 ? 五行字(用神五行) : null;
  if (!yongEl && 主要矛盾?.四之二_取用定案?.改判用神) {
    yongEl = 五行字(主要矛盾.四之二_取用定案.改判用神);
  }
  if (!yongEl) {
    yongEl = 五行字(tiaohouAssessment(chart)?.用神);
  }

  // 2. 确定局中忌神/凶党五行
  let jiElList = [];
  if (yongEl) {
    jiElList.push(克我者(yongEl));
  }
  if (主要矛盾?.官杀吉凶?.日主担力 === '不可任') {
    jiElList.push(克我者(D));
  }
  const 占比 = elementStrength(chart.pillars, branchAt(chart.pillars[1]), kingOf(chart)).percent;
  const 旺序 = [...ELEMENTS].sort((a, b) => 占比[b] - 占比[a]);
  if (旺序[0] && 占比[旺序[0]] >= 35 && 旺序[0] !== yongEl && 旺序[0] !== D) {
    jiElList.push(旺序[0]);
  }
  jiElList = [...new Set(jiElList.filter(Boolean))];

  // 3. 提取原局关系
  let luckP = null;
  if (岁运 && 岁运.length >= 2) {
    const s = 岁运[0], b = 岁运[1];
    const si = STEMS.indexOf(s), bi = BRANCHES.indexOf(b);
    if (si >= 0 && bi >= 0) luckP = { stemIndex: si, branchIndex: bi };
  }
  const rels = gzRelations(chart.pillars, luckP);

  const 关系条目 = [];

  const extractChars = (pairStr) => {
    const m = String(pairStr).match(/[甲乙丙丁戊己庚辛壬癸子丑寅卯辰巳午未申酉戌亥]/g);
    return m ? [...new Set(m)] : [];
  };

  const judgeRelation = (类别, pair, note, extra = {}) => {
    const chars = extractChars(pair);
    const lib = DUAL_IMAGE_LIBRARY[类别] ?? {
      喜象: '成全顺遂、转化生辉',
      忌象: '相战损伤、阻滞内耗',
      出处: '体用路线法干支双轨意象法则',
    };

    let 定性 = '中性';
    let 依据 = '吉凶参半，随岁运引化而定';
    let 动态应象 = `${lib.喜象}（喜）／${lib.忌象}（忌）`;

    const els = chars.map((ch) => 此字五行(ch)).filter(Boolean);
    const hasYong = els.includes(yongEl);
    const hasJi = els.some((el) => jiElList.includes(el));
    const hasLu = luBranch && chars.includes(luBranch);

    const isDestructive = /冲|克|穿|刑|破|绝|反吟/.test(类别);
    const isCohesive = /合|自合|鸳鸯/.test(类别);

    if (isDestructive) {
      if (hasJi && !hasYong && !hasLu) {
        定性 = '为喜';
        依据 = `破坏方制裁削弱局中忌神（${jiElList.join('、')}），去浊扬清`;
        动态应象 = lib.喜象;
      } else if (hasYong || hasLu) {
        定性 = '为忌';
        依据 = `破坏方直接损伤全局用神【${hasYong ? yongEl : ''}】或日主禄根【${hasLu ? luBranch : ''}】，破基伤用`;
        动态应象 = lib.忌象;
      } else {
        定性 = '中性';
        依据 = '两相对峙，未直犯要穴，喜忌双轨并陈';
        动态应象 = `${lib.喜象}（喜）／${lib.忌象}（忌）`;
      }
    } else if (isCohesive) {
      if (hasJi && !hasYong) {
        定性 = '为喜';
        依据 = `合绊局中忌党（${jiElList.join('、')}），使凶煞失威为我所用`;
        动态应象 = lib.喜象;
      } else if (hasYong && !hasJi) {
        定性 = '为忌';
        依据 = `用神【${yongEl}】逢合受绊，失去施展自由，贪合忘做功`;
        动态应象 = lib.忌象;
      } else {
        定性 = '为喜';
        依据 = '干支天地相纽，聚气有情，相安为利';
        动态应象 = lib.喜象;
      }
    }

    关系条目.push({
      类别,
      pair,
      定性,
      字: chars.join(''),
      动态应象,
      喜象: lib.喜象,
      忌象: lib.忌象,
      依据,
      出处: lib.出处,
      note: note || '',
      ...extra,
    });
  };

  for (const item of (rels['天干五合'] ?? [])) {
    judgeRelation('天干五合', item.pair, item.化 ? `合化${item.化}` : '');
  }
  for (const item of (rels['天干相克'] ?? [])) {
    judgeRelation('天干相克', item.pair, item.type || '');
  }
  for (const item of (rels['地支六合'] ?? [])) {
    judgeRelation('地支六合', item.pair, item.化 ? `合化${item.化}` : '');
  }
  for (const item of (rels['地支半合'] ?? [])) {
    judgeRelation('地支半合', item.pair, `${item.type}（${item.拱 ? '拱' + item.拱 : ''}化${item.化}）`);
  }
  for (const item of (rels['地支六冲'] ?? [])) {
    judgeRelation('地支六冲', item.pair, item.note || '');
  }
  for (const item of (rels['地支相刑'] ?? [])) {
    const pairStr = item.pair ?? `${item.positions}（${item.members}）`;
    const noteStr = `${item.刑 ?? item.kind ?? '相刑'}（${item.口径 ?? item.type ?? ''}）`;
    judgeRelation('地支相刑', pairStr, noteStr);
  }
  for (const item of (rels['地支相害'] ?? [])) {
    judgeRelation('地支相害', item.pair, item.note || '');
  }
  for (const item of (rels['地支相破'] ?? [])) {
    judgeRelation('地支相破', item.pair, item.note || '');
  }
  for (const item of (rels['地支相绝'] ?? [])) {
    judgeRelation('地支相绝', item.pair, item.绝 || '');
  }
  for (const item of (rels['干支自合'] ?? [])) {
    judgeRelation('干支自合', `${item.pillar}柱${item.gz}`, item.合 || '');
  }
  for (const item of (rels['鸳鸯合'] ?? [])) {
    judgeRelation('天地鸳鸯合', item.pair, `${item.天合}且${item.地合}`);
  }
  for (const item of (rels['反吟'] ?? [])) {
    judgeRelation('反吟', item.pair, `${item.天干}且${item.地支}`);
  }

  const 喜项统计 = 关系条目.filter((r) => r.定性 === '为喜').length;
  const 忌项统计 = 关系条目.filter((r) => r.定性 === '为忌').length;
  const 中性统计 = 关系条目.filter((r) => r.定性 === '中性').length;

  const 总评 = `全局检出 ${关系条目.length} 组干支作用力：`
    + `成全用神/制化忌神为喜 ${喜项统计} 项；`
    + `损伤用神/动摇根气为忌 ${忌项统计} 项；`
    + `吉凶参半双轨中性 ${中性统计} 项。`
    + `任何关系绝非单向定吉凶，一切以命局主要矛盾与用忌统率为归宿。`;

  return {
    总评,
    条目数: 关系条目.length,
    关系条目,
    喜项统计,
    忌项统计,
    中性统计,
    用神参考: yongEl,
    忌神参考: jiElList,
    法理说明: 'D-031 全天干地支作用关系双轨意象法则：拒绝单向低俗定吉凶，喜忌双轨输出。',
  };
}

/**
 * **乙体系推演大脑覆盖率检视与认怂出口**（D-037 裁定 · 宪法第五条第三款）
 *
 * 践行立宪底线誓言：
 * 《AGENTS.md》§0「乙体系未覆盖的局面 ⇒ 只并陈，明写『本体系未覆盖，暂不判断』，不硬答」。
 *
 * 触发认怂（covered = false）场景：
 *   1. 显式声明未覆盖：opts.未覆盖 === true 或 opts.covered === false；
 *   2. 极端死结相战：四柱无通关枢纽，两神极战均停（各占35%以上且差距<=3%）且无通关之神，从正两难；
 *   3. 虚妄用神：所声明用神在局中全无根气与生源，与主要矛盾完全相反。
 *
 * @param {object} chart
 * @param {object} [opts]
 */
export function coverageOf(chart, opts = {}) {
  // 1. 显式声明未覆盖
  if (opts.未覆盖 === true || opts.covered === false) {
    return {
      covered: false,
      判定: '本体系未覆盖，暂不判断',
      结论: '本体系未覆盖，暂不判断',
      原因: opts.原因 || '调用方或命局标记为本体系暂未覆盖之复杂外格/未知相战',
      依据: '《AGENTS.md》§0「乙体系未覆盖的局面 ⇒ 只并陈，明写『本体系未覆盖，暂不判断』，不硬答」；《规矩/宪法.md》',
    };
  }

  // 2. 极端死结相战
  const D = dayMasterOf(chart).element;
  const percent = elementStrength(chart.pillars, branchAt(chart.pillars[1]), kingOf(chart)).percent;
  const 旺序 = [...ELEMENTS].sort((a, b) => percent[b] - percent[a]);
  const e1 = 旺序[0], e2 = 旺序[1];
  const isDirectClash = KE_MAP[e1] === e2 || KE_MAP[e2] === e1;
  const bridgeElem = KE_MAP[e1] === e2 ? 生我者(e2) : 生我者(e1);
  const bridgeOccupants = bridgeElem ? occupantsOf(chart, bridgeElem) : [];

  if (percent[e1] >= 30 && percent[e2] >= 30 && (percent[e1] + percent[e2] >= 70) && isDirectClash && bridgeOccupants.length === 0) {
    const 特殊 = specialGejuOf(chart).成立者 ?? [];
    if (!特殊.some((x) => /从|专旺|化气/.test(String(x)))) {
      return {
        covered: false,
        判定: '本体系未覆盖，暂不判断',
        结论: '本体系未覆盖，暂不判断',
        原因: `局中两神（${e1}与${e2}）极战均停（合占 ${(percent[e1] + percent[e2]).toFixed(1)}%）且无通关之神（${bridgeElem}），两神交战死结，已超出现行普通格与特殊格判据覆盖范畴`,
        依据: '《AGENTS.md》§0「乙体系未覆盖的局面 ⇒ 只并陈，明写『本体系未覆盖，暂不判断』，不硬答」；《规矩/宪法.md》',
      };
    }
  }

  return {
    covered: true,
    判定: '本体系已覆盖',
    结论: '命局在体用路线法宪法判据体系覆盖之内，正常输出推演研判',
    原因: '命局主要矛盾与五行流通路线明确，有法可依',
    依据: '《规矩/判据.md》P-001～P-015；《规矩/体用路线法.md》',
  };
}

/**
 * **从儿格见比劫判定与流通归宿研判**（D-032 / 判据 P-016）。
 *
 * 典籍法理（《滴天髓》《千里命稿》）：
 *   ① 「从儿不管身强弱，只要我儿又见儿」：以食伤为用，顺生流通；
 *   ② 比劫顺生食伤通常为喜（比劫生食伤，秀气有源，不悖从儿之势）；
 *   ③ 印绶破格（枭神夺食）为第一大忌；
 *   ④ 官杀相战（伤官见官）为忌；
 *   ⑤ 若局中比劫与财星贴身直克（柱差 <= 1）且无食伤在两者之间通关，
 *      判定为「越位夺财为忌」（虽从儿亦有争财破耗之害）。
 *
 * @param {object} chart
 * @param {object} [opts]
 * @returns {object}
 */
export function congErAnalysisOf(chart, opts = {}) {
  const pillars = chart.pillars;
  const D = dayMasterOf(chart).element;
  const monthBranch = branchAt(pillars[1]);
  const s = elementStrength(pillars, monthBranch, kingOf(chart));
  const 占比 = s.percent;
  const tgs = tenGodStrength(chart);
  const byGod = Object.fromEntries((tgs.各十神 ?? []).map((x) => [x.十神, x]));
  const sg = specialGejuOf(chart);
  const 特殊成立 = sg.成立者 ?? [];

  const 食伤五行 = SHENG_MAP[D];
  const 财星五行 = KE_MAP[D];
  const 官杀五行 = 克我者(D);
  const 印星五行 = 生我者(D);
  const 比劫五行 = D;

  const 食伤占比 = 占比[食伤五行] ?? 0;
  const 印星占比 = 占比[印星五行] ?? 0;
  const 月令五行 = ELEMENTS[BRANCH_ELEMENT[BRANCHES.indexOf(monthBranch)]];
  const 月令食伤 = 月令五行 === 食伤五行;

  const R = ['极', '强', '中', '弱'];
  const 食伤力 = Math.min(R.indexOf(byGod['食神']?.级别 ?? '弱'), R.indexOf(byGod['伤官']?.级别 ?? '弱'));
  const 印星力 = Math.min(R.indexOf(byGod['正印']?.级别 ?? '弱'), R.indexOf(byGod['偏印']?.级别 ?? '弱'));

  const 标记从儿 = 特殊成立.includes('从儿');
  const 属于从儿 = 标记从儿 || (月令食伤 && 食伤占比 >= 30 && 印星力 >= 2 && 印星占比 < 12);

  if (!属于从儿) {
    return {
      属于从儿: false,
      说明: '局中食伤未达从儿独旺标准，或印星有力破格，不入从儿格',
    };
  }

  // 1. 印绶检验
  const 印落点 = occupantsOf(chart, 印星五行).filter((o) => o.层 === '天干' || o.层 === '地支本气');
  const 印破格 = 印落点.length > 0 && 印星占比 >= 10;
  const 印绶判定 = {
    角色: 印破格 ? '枭印破格' : '无破格之虞',
    说明: 印破格
      ? `局中见${印星五行}（印绶）有力透藏，枭神夺食犯旺逆势，破从儿之格`
      : `局中无印绶破格，或印星衰绝无力，从儿气势得以保全`,
  };

  // 2. 官杀检验
  const 官杀落点 = occupantsOf(chart, 官杀五行).filter((o) => o.层 === '天干' || o.层 === '地支本气');
  const 财落点 = occupantsOf(chart, 财星五行).filter((o) => o.层 === '天干' || o.层 === '地支本气');
  const 有官杀 = 官杀落点.length > 0;
  const 官杀相战 = 有官杀 && (占比[官杀五行] ?? 0) >= 10 && 财落点.length === 0;
  const 官杀判定 = {
    角色: 官杀相战 ? '相战为忌（伤官见官）' : '无相战之害',
    说明: 官杀相战
      ? `局中见${官杀五行}（官杀）透藏，与食伤直接相战，伤官见官局势动荡`
      : (有官杀 ? `官杀有财星通关转化，不直接冲犯食伤` : `局无官杀相犯，气势专一`),
  };

  // 3. 比劫角色判定（P-016 核心重点）
  const 比劫落点 = occupantsOf(chart, 比劫五行).filter((o) => o.性质 !== '日主自身');
  let 比劫判定;
  if (比劫落点.length === 0) {
    比劫判定 = {
      角色: '无透藏',
      说明: '局中无比劫透藏，日主全神贯注于食伤',
    };
  } else {
    const 食伤落点 = occupantsOf(chart, 食伤五行);
    let 存在越位夺财 = false;
    let 夺财细节 = '';

    for (const b of 比劫落点) {
      for (const c of 财落点) {
        const prox = proximityOf(b.宫位, c.宫位);
        if (prox.柱差 <= 1) {
          let hasTongGuan = false;
          if (prox.柱差 === 0) {
            // 同柱直克（盖头截脚）：通关之神必须在同柱（同柱藏有或透出食伤）
            hasTongGuan = 食伤落点.some((s) => s.宫位[0] === b.宫位[0]);
          } else {
            // 邻柱直克（柱差1）：若同为天干直克，须天干透出食伤或同柱引化
            hasTongGuan = 食伤落点.some((s) => {
              const p1 = proximityOf(s.宫位, b.宫位);
              const p2 = proximityOf(s.宫位, c.宫位);
              if (p1.柱差 > 1 || p2.柱差 > 1) return false;
              if (b.层 === '天干' && c.层 === '天干') {
                return s.层 === '天干' || s.宫位[0] === b.宫位[0] || s.宫位[0] === c.宫位[0];
              }
              return true;
            });
          }
          if (!hasTongGuan) {
            存在越位夺财 = true;
            夺财细节 = `${b.宫位}${b.字}与${c.宫位}${c.字}贴身直克（柱差${prox.柱差}），中间无食伤通关`;
            break;
          }
        }
      }
      if (存在越位夺财) break;
    }

    if (存在越位夺财) {
      比劫判定 = {
        角色: '越位夺财为忌',
        说明: `比劫与财星贴身直克（${夺财细节}），比劫越位夺财，虽从儿亦有争财破耗之害`,
      };
    } else {
      比劫判定 = {
        角色: '顺生为喜',
        说明: '比劫顺生食伤，秀气有源，不悖从儿之势（《滴天髓》「不论身强弱，四柱虽有比劫仍去生助食伤也」）',
      };
    }
  }

  // 4. 流通归宿
  const 见儿 = 财落点.length > 0 && (占比[财星五行] ?? 0) >= 10;
  const 流通归宿 = 见儿
    ? `食伤生财，秀气流行，以食伤为用、财星为归宿（我儿又见儿）`
    : `食伤独旺泄秀，以食伤为用（局中财弱，纯粹泄秀）`;
  const 所从之势 = 见儿 ? 财星五行 : 食伤五行;

  const 综合结论 = `从儿格成立，以【${食伤五行}】为用；比劫【${比劫判定.角色}】；${流通归宿}`;

  return {
    属于从儿: true,
    用神: 食伤五行,
    所从之势,
    流通归宿,
    比劫判定,
    印绶判定,
    官杀判定,
    综合结论,
    依据: '《规矩/判据.md》P-016；《滴天髓》从儿章；《千里命稿》从儿格',
  };
}

/**
 * 获取地支藏干十神列表
 */
function branchHiddenWithTenGod(branchChar, dStem) {
  const bi = BRANCHES.indexOf(branchChar);
  if (bi < 0) return [];
  const si = STEMS.indexOf(dStem);
  const spec = HIDDEN_STEMS_SPEC[bi] || [];
  return spec.map(([hStem, layer]) => {
    const hsi = STEMS.indexOf(hStem);
    const god = tenGod(si, hsi);
    const elem = ELEMENTS[STEM_ELEMENT[hsi]];
    return { 字: hStem, 层: layer === '本' ? '本气' : (layer === '中' ? '中气' : '余气'), 十神: god, 五行: elem };
  });
}

/**
 * 八格定格与格神提取
 */
function determineGeju(chart) {
  const dStem = dayMasterOf(chart).stem;
  const dsi = STEMS.indexOf(dStem);
  const mb = branchAt(chart.pillars[1]);
  const hidden = branchHiddenWithTenGod(mb, dStem);

  // 天干透出的十神（年、月、时）
  const openStems = [
    { stem: stemAt(chart.pillars[0]), pos: '年干', tenGod: chart.pillars[0].tenGod ?? tenGod(dsi, STEMS.indexOf(stemAt(chart.pillars[0]))) },
    { stem: stemAt(chart.pillars[1]), pos: '月干', tenGod: chart.pillars[1].tenGod ?? tenGod(dsi, STEMS.indexOf(stemAt(chart.pillars[1]))) },
    { stem: stemAt(chart.pillars[3]), pos: '时干', tenGod: chart.pillars[3].tenGod ?? tenGod(dsi, STEMS.indexOf(stemAt(chart.pillars[3]))) },
  ];

  // 1. 检查月令藏干透出
  const ben = hidden.find((h) => h.层 === '本气');
  const touBen = ben && openStems.find((o) => o.stem === ben.字);
  const otherHidden = hidden.filter((h) => h.层 !== '本气');
  const touOther = otherHidden.map((h) => ({ hidden: h, open: openStems.find((o) => o.stem === h.字) })).filter((x) => x.open);

  let 格神字 = null;
  let 格神十神 = null;
  let 透干 = false;

  if (touBen) {
    格神字 = ben.字;
    格神十神 = ben.十神;
    透干 = true;
  } else if (touOther.length > 0) {
    格神字 = touOther[0].hidden.字;
    格神十神 = touOther[0].hidden.十神;
    透干 = true;
  } else if (ben) {
    格神字 = ben.字;
    格神十神 = ben.十神;
    透干 = false;
  }

  // 映射到八格名称
  let 格局 = '普通格';
  if (格神十神 === '正官') 格局 = '正官格';
  else if (格神十神 === '七杀') 格局 = '七杀格';
  else if (格神十神 === '正财') 格局 = '正财格';
  else if (格神十神 === '偏财') 格局 = '偏财格';
  else if (格神十神 === '正印') 格局 = '正印格';
  else if (格神十神 === '偏印') 格局 = '偏印格';
  else if (格神十神 === '食神') 格局 = '食神格';
  else if (格神十神 === '伤官') 格局 = '伤官格';
  else if (格神十神 === '比肩') 格局 = '建禄格';
  else if (格神十神 === '劫财') 格局 = '阳刃格';

  return {
    格局,
    格神字,
    格神十神,
    透干,
    月令本气: ben ? ben.字 : null,
    月令地支: mb,
    hidden,
    openStems,
  };
}

/**
 * **子平八格成破救应全矩阵研判**（D-042 / 判据 P-021）。
 *
 * 典籍法理：《子平真诠·论用神成败》《子平真诠·论用神救应》
 *   - 以月令为纲，格神透干优先；
 *   - 矩阵输出：成格、破格、败中有救；
 *   - 严格对应破格因与救应因。
 *
 * @param {object} chart
 * @param {object} [opts]
 * @returns {object}
 */
export function gejuChengPoOf(chart, opts = {}) {
  const ge = determineGeju(chart);
  const dStem = dayMasterOf(chart).stem;
  const dElem = dayMasterOf(chart).element;
  const pillars = chart.pillars;
  const openStems = ge.openStems;

  const 透出十神 = new Set(openStems.map((o) => o.tenGod));
  const hasTou = (tg) => 透出十神.has(tg);

  const branches = pillars.map(branchAt);
  const rels = gzRelations(pillars, null);

  const STEM_COMBINES = {
    '甲': '己', '己': '甲',
    '乙': '庚', '庚': '乙',
    '丙': '辛', '辛': '丙',
    '丁': '壬', '壬': '丁',
    '戊': '癸', '癸': '戊',
  };
  const dsi = STEMS.indexOf(dStem);
  const 天干合 = [];
  for (let i = 0; i < 4; i++) {
    for (let j = i + 1; j < 4; j++) {
      const s1 = stemAt(pillars[i]);
      const s2 = stemAt(pillars[j]);
      if (STEM_COMBINES[s1] === s2) {
        const tg1 = i === 2 ? '日主' : (pillars[i].tenGod ?? tenGod(dsi, STEMS.indexOf(s1)));
        const tg2 = j === 2 ? '日主' : (pillars[j].tenGod ?? tenGod(dsi, STEMS.indexOf(s2)));
        天干合.push({ s1, s2, i, j, tg1, tg2 });
      }
    }
  }

  const mb = ge.月令地支;
  const monthClash = (rels['地支六冲'] ?? []).filter((c) => String(c.pair ?? c.positions ?? '').includes(`月支${mb}`) || String(c.pair ?? c.positions ?? '').includes(mb));
  const monthHe = (rels['地支六合'] ?? []).filter((c) => String(c.pair ?? c.positions ?? '').includes(`月支${mb}`) || String(c.pair ?? c.positions ?? '').includes(mb));
  const hasMonthClash = monthClash.length > 0;
  const hasMonthHe = monthHe.length > 0;

  const allBranchStr = branches.join('');
  const hasWoodBureau = (allBranchStr.includes('卯') && (allBranchStr.includes('未') || allBranchStr.includes('亥')))
    || (allBranchStr.includes('寅') && (allBranchStr.includes('午') || allBranchStr.includes('戌')));

  const isJinShuiShangGuan = (dElem === '金' && (ge.格局 === '伤官格' || branches[1] === '子' || branches[1] === '亥'));

  let 状态 = '成格';
  let 成格因 = '';
  let 破格因 = '';
  let 救应因 = '';
  const 法理出处 = '《子平真诠·论用神成败救应》';

  switch (ge.格局) {
    case '正官格': {
      const 伤克官 = hasTou('伤官') || (dElem === '水' && hasWoodBureau);
      const 官逢冲 = hasMonthClash;
      const 官杀混 = hasTou('正官') && hasTou('七杀');

      if (伤克官) {
        const 透印 = hasTou('正印') || hasTou('偏印');
        const 伤被合 = 天干合.some((h) => (h.tg1 === '伤官' || h.tg2 === '伤官') && h.tg1 !== '日主' && h.tg2 !== '日主');
        破格因 = '官逢伤官克破';
        if (透印) {
          状态 = '败中有救';
          救应因 = '天干透印制伤护官';
        } else if (伤被合) {
          状态 = '败中有救';
          救应因 = '天干相合合去伤官存官';
        } else {
          状态 = '破格';
        }
      } else if (官逢冲) {
        破格因 = '官星坐支逢地支刑冲';
        if (hasMonthHe) {
          状态 = '败中有救';
          救应因 = '地支得六合贪合免冲以解刑冲';
        } else {
          状态 = '破格';
        }
      } else if (官杀混) {
        破格因 = '官杀混杂';
        const 合杀 = 天干合.some((h) => (h.tg1 === '七杀' || h.tg2 === '七杀'));
        const 制杀 = hasTou('食神');
        if (合杀 || 制杀) {
          状态 = '败中有救';
          救应因 = 合杀 ? '合杀留官取清' : '食神制杀留官取清';
        } else {
          状态 = '破格';
        }
      } else {
        状态 = '成格';
        成格因 = (hasTou('正财') || hasTou('偏财') || hasTou('正印') || hasTou('偏印'))
          ? '官逢财印相资，无刑冲破害'
          : '正官得禄当权，无刑冲破害成格';
      }
      break;
    }

    case '偏财格':
    case '正财格': {
      const 财透杀 = hasTou('七杀');
      const 财逢劫 = hasTou('比肩') || hasTou('劫财');

      if (财透杀) {
        破格因 = '财带七杀泄财党杀';
        const 透食 = hasTou('食神') || hasTou('伤官');
        const 合杀 = 天干合.some((h) => (h.tg1 === '七杀' && (h.tg2 === '劫财' || h.tg2 === '比肩'))
          || (h.tg2 === '七杀' && (h.tg1 === '劫财' || h.tg1 === '比肩')));
        if (合杀) {
          状态 = '败中有救';
          救应因 = '劫刃合杀存财成格';
        } else if (透食) {
          状态 = '败中有救';
          救应因 = '食神制杀护身存财';
        } else {
          状态 = '破格';
        }
      } else if (财逢劫) {
        破格因 = '财轻比劫分夺';
        const 透官 = hasTou('正官');
        const 透食伤 = hasTou('食神') || hasTou('伤官');
        if (透官) {
          状态 = '败中有救';
          救应因 = '透官制劫护财';
        } else if (透食伤) {
          状态 = '败中有救';
          救应因 = '透食伤化劫生财';
        } else {
          状态 = '破格';
        }
      } else {
        状态 = '成格';
        成格因 = hasTou('正官') ? '财旺生官成格' : '财星通门户，无刑冲分夺成格';
      }
      break;
    }

    case '七杀格': {
      const 杀逢财 = hasTou('正财') || hasTou('偏财');
      const 杀逢食制 = hasTou('食神') || hasTou('伤官');
      const 枭印夺食 = 杀逢食制 && hasTou('偏印');

      if (枭印夺食) {
        破格因 = '食神制杀逢枭神夺食';
        const 透财制枭 = hasTou('正财') || hasTou('偏财');
        if (透财制枭) {
          状态 = '败中有救';
          救应因 = '财星制枭护食以制杀';
        } else {
          状态 = '破格';
        }
      } else if (杀逢财 && !杀逢食制) {
        破格因 = '杀重逢财党杀';
        const 透印化杀 = hasTou('正印') || hasTou('偏印');
        if (透印化杀) {
          状态 = '败中有救';
          救应因 = '透印化杀生身';
        } else {
          状态 = '破格';
        }
      } else if (!杀逢食制 && !(hasTou('正印') || hasTou('偏印'))) {
        破格因 = '七杀无制无化';
        状态 = '破格';
      } else {
        状态 = '成格';
        成格因 = 杀逢食制 ? '身强七杀逢食神制伏成格' : '杀透印化，杀印相生成格';
      }
      break;
    }

    case '正印格':
    case '偏印格': {
      const 印逢财 = hasTou('正财') || hasTou('偏财');
      if (印逢财) {
        破格因 = '印轻逢财星克破（贪财坏印）';
        const 透劫制财 = hasTou('劫财') || hasTou('比肩');
        const 合财 = 天干合.some((h) => (h.tg1 === '正财' || h.tg1 === '偏财' || h.tg2 === '正财' || h.tg2 === '偏财'));
        if (透劫制财) {
          状态 = '败中有救';
          救应因 = '天干透比劫制财护印';
        } else if (合财) {
          状态 = '败中有救';
          救应因 = '天干相合合财存印';
        } else {
          状态 = '破格';
        }
      } else {
        状态 = '成格';
        成格因 = (hasTou('正官') || hasTou('七杀')) ? '官印双全（杀印相生）成格' : '印绶纯粹有气，得食伤泄秀成格';
      }
      break;
    }

    case '食神格': {
      const 逢枭 = hasTou('偏印');
      const 生财透杀 = (hasTou('正财') || hasTou('偏财')) && hasTou('七杀');

      if (逢枭) {
        破格因 = '食神逢枭神夺食';
        const 透财制枭 = hasTou('正财') || hasTou('偏财');
        if (透财制枭) {
          状态 = '败中有救';
          救应因 = '天干透财制枭护食成格';
        } else {
          状态 = '破格';
        }
      } else if (生财透杀) {
        破格因 = '食神生财而透杀党杀';
        const 合杀 = 天干合.some((h) => (h.tg1 === '七杀' || h.tg2 === '七杀'));
        if (合杀) {
          状态 = '败中有救';
          救应因 = '天干合杀存财成格';
        } else {
          状态 = '破格';
        }
      } else {
        状态 = '成格';
        成格因 = (hasTou('正财') || hasTou('偏财')) ? '食神生财成格' : '食神吐秀制杀成格';
      }
      break;
    }

    case '伤官格': {
      const 见官 = hasTou('正官') || branches.some((b, i) => i !== 1 && branchHiddenWithTenGod(b, dStem).some((h) => h.十神 === '正官'));
      if (见官 && !isJinShuiShangGuan) {
        破格因 = '伤官见官非金水破格';
        const 透印制伤 = hasTou('正印') || hasTou('偏印');
        const 财星通关 = hasTou('正财') || hasTou('偏财');
        if (透印制伤) {
          状态 = '败中有救';
          救应因 = '天干透印制伤护官';
        } else if (财星通关) {
          状态 = '败中有救';
          救应因 = '财星通关化伤生官';
        } else {
          状态 = '破格';
        }
      } else if (isJinShuiShangGuan && 见官) {
        状态 = '成格';
        成格因 = '金水伤官喜见官成格';
      } else {
        状态 = '成格';
        成格因 = (hasTou('正印') || hasTou('偏印')) ? '伤官佩印成格' : '伤官生财成格';
      }
      break;
    }

    case '建禄格':
    case '阳刃格': {
      const 透官 = hasTou('正官');
      const 透伤 = hasTou('伤官');
      const 透杀 = hasTou('七杀');
      if (透官 && 透伤) {
        破格因 = '禄刃用官逢伤官克破';
        const 透印 = hasTou('正印') || hasTou('偏印');
        if (透印) {
          状态 = '败中有救';
          救应因 = '透印制伤护官成格';
        } else {
          状态 = '破格';
        }
      } else if (ge.格局 === '阳刃格' && !透官 && !透杀) {
        破格因 = '阳刃无官杀驾驭';
        const 透食伤 = hasTou('食神') || hasTou('伤官');
        if (透食伤) {
          状态 = '成格';
          成格因 = '阳刃透食伤吐秀成格';
        } else {
          状态 = '破格';
        }
      } else {
        状态 = '成格';
        成格因 = ge.格局 === '阳刃格' ? '阳刃驾杀（逢官杀）成格' : '建禄逢财官成格';
      }
      break;
    }

    default: {
      状态 = '成格';
      成格因 = '气象纯粹成格';
      break;
    }
  }

  return {
    格局: ge.格局,
    格神字: ge.格神字,
    格神十神: ge.格神十神,
    月令本气: ge.月令本气,
    透干: ge.透干,
    状态,
    成格因: 状态 === '成格' ? 成格因 : null,
    破格因: 状态 !== '成格' ? 破格因 : null,
    救应因: 状态 === '败中有救' ? 救应因 : null,
    法理出处,
    说明: `依据《子平真诠·论用神成败救应》：月令取【${ge.格局}】（格神${ge.格神字}·${ge.格神十神}），`
      + `研判结论为【${ge.格局} · ${状态}】`
      + (状态 === '败中有救' ? `（因${破格因}，赖${救应因}）` : (状态 === '破格' ? `（因${破格因}）` : `（${成格因}）`)),
  };
}

/**
 * **体用路线四条的汇总入口** —— 一次算齐，供工具侧调用。
 *
 * @param {object} chart
 * @param {{用神五行?: string, 忌神五行?: string, 岁运?: string}} [opts]
 */
export function tiyongRouteOf(chart, opts = {}) {
  const { 用神五行 = null, 忌神五行 = null, 岁运 = null } = opts;
  const D = dayMasterOf(chart).element;   // 日主五行（裸 chart 亦可）
  // ⚠ 用神必须归一到**五行**：《穷通宝鉴》调候表给的是**干支字**（甲／丙／癸…），
  //   若原样下传，`克我者(甲)` 会返回 undefined，致（八）结构分析、护卫、结构三条全失效。
  //   实测：`--tiyong`（不声明用神）时 用神＝甲 ⇒ 旧代码报「克甲者是 undefined」。
  const declaredYong = 用神五行 ? 五行字(用神五行) : null;
  let 用神 = declaredYong;
  let 用神暂取 = null;
  if (!用神) {
    const tha = tiaohouAssessment(chart);
    用神暂取 = tha?.用神 ?? null;              // 原样保留干支字，供显示
    用神 = 用神暂取 ? 五行字(用神暂取) : null;  // 归一为五行，供计算
  }
  const 用神来源 = declaredYong ? '调用方声明'
    : 用神暂取 ? `引擎按《穷通宝鉴》调候表暂取（原表作「${用神暂取}」，归一为五行「${用神}」；**待调用方核定**）`
      : '（未能取得）';
  // ★ 先算第 1 条（财官是否威胁）——下面「主要矛盾 → 候选用神 → 取用定案」全靠它。
  const 第一 = threatOf(chart);
  // ★（二）主要矛盾 → 用神（使用者 2026-09-28：「用神不是两个，而是很多个……判别哪个最重要，
  // 就是抓住八字的主要矛盾，什么才是最需要优先解决的事情（先保命），再考虑其他的」）。
  // 故汇总须先摆矛盾，再列各路候选用神，最后说谁当家；不得把某个来源的用神当唯一定论。
  const 占比 = elementStrength(chart.pillars, branchAt(chart.pillars[1]), kingOf(chart)).percent;
  const 旺序 = [...ELEMENTS].sort((a, b) => 占比[b] - 占比[a]);
  const 得地 = 第一.分组条件?.得地 ?? [];
  const 得势 = 第一.分组条件?.得势 ?? [];
  const 立得住 = 得地.length > 0 || 得势.length > 0;
  const 候选 = [];
  let 取用定案 = null;
  const 官杀五行c = 克我者(D);
  {
    // ★★ 2026-10-04 使用者口径：候选**不再按固定序生成**，改为「先看官杀担力 → 再逐路验可行性」。
    //   使用者原话：「杀多也不能制吗？」「（通关与制取舍）看哪个可行」「选 ③ 都验」。
    //   规则：
    //     ① 官杀担力 可任 ⇒ 官杀是**贵气·位** ⇒ 宜"化"，但**不禁止"制"**（只是不宜制过头）
    //        不可任 ⇒ 官即是**杀·灾** ⇒ 制化皆可
    //     ② 两条路**各自验**（不设硬序）：制路须「势足以敌 ∧ 制得其宜」；化路须「印在局 ∧ 源头有力」
    //     ③ 只一条可行⇒取那条；多条可行⇒**并列报出**；全不可行⇒转克／泄／耗兜底
    //   ⚠「杀多」本身**不是判据**——它只让"制"更难通过两关，不直接判其出局。
    const 官杀位c = occupantsOf(chart, 官杀五行c);
    const 同党c = (占比[D] ?? 0) + (占比[生我者(D)] ?? 0);
    // P-002 官杀承载判定：检查日主通根是否被多重冲拔
    const relsForDanli = gzRelations(chart.pillars, null);
    const chongsForDanli = relsForDanli['地支六冲'] ?? [];
    const 冲拔支c = new Set();
    for (const c of chongsForDanli) {
      for (const d of 得地) {
        const bName = d.位 ? d.位.slice(-1) : '';
        if (c.pair && c.pair.includes(bName)) 冲拔支c.add(d.位);
      }
    }
    const 根被冲拔c = 得地.length > 0 && 得地.every((d) => 冲拔支c.has(d.位));
    const 担力c = (根被冲拔c && 第一.官杀?.构成威胁) ? '不可任'
      : (得地.length > 0 || 得势.length > 0 || 同党c >= 40) ? '可任'
      : (得地.length === 0 && 得势.length === 0 && 同党c < 25) ? '不可任' : '两可';
    const 官杀重 = 官杀位c.length > 0;

    const 制 = 克我者(旺序[0]);
    // ★★ 化路（通关）须对准**有害的字**，不是对准"最旺"（2026-10-04 实测修正）。
    //   原式 `引=SHENG_MAP[旺序[0]]; 化 = SHENG_MAP[引]===D ? 引 : null` **只认两段链**
    //     「最旺 → X → 日主」。
    //   本式改为：对每个**有害于日主**者取桥 ＝ 「有害者所生、且该桥生日主」。
    //     ⚠ 当官杀为害时，桥＝**印**（官杀生印、印生日主）；若**印之五行恰为日主本行**，
    //       则第二步「桥生日主」表现为「桥＝日主」，此退化情形**仅在有实际压迫时**才有效。
    const 有害者 = [];
    if (第一.官杀?.构成威胁) 有害者.push(官杀五行c);
    if (第一.财?.构成威胁) 有害者.push(克我者(生我者(D)));   // 财＝日主所克
    if (!有害者.length) 有害者.push(旺序[0]);
    const 有害确有压 = !!第一.官杀?.构成威胁 || !!第一.财?.构成威胁;
    //   ⚠⚠ 2026-10-04 二次修正（自审查出，重要）：退化条件 `b === 日主` **只可在有害者确实压日主时用**。
    //   实测反证 `庚寅 戊寅 癸酉 辛酉`（日主水、最旺＝金＝**印**、官杀土**不威胁**）：
    //     有害者退化取 [最旺]＝金，金生水＝**印生身，本无冲突**；
    //     退化条件却让「水」通过 ⇒ 推出"化＝水（＝日主本行）"这一**错误候选**。
    //     本机 200 盘中「最旺＝印」者 **29 盘全被误推**（实测分布：日主84／印29／官杀34／财30／食伤23）。
    const 化列表 = [...new Set(有害者.map((h) => SHENG_MAP[h]))]
      .filter((b) => b && (
        SHENG_MAP[b] === dayMasterOf(chart).element
        || (有害确有压 && b === dayMasterOf(chart).element)
      ));
    const 调 = tiaohouAssessment(chart)?.用神 ?? null;

    // —— 制路可行性：势足以敌（不被反克） ∧ 制得其宜（不过不及）——
    let 制可行 = null, 制据 = null;
    if (制) {
      const 制p = powerOf(chart, 制);
      const 被制p = powerOf(chart, 旺序[0]);
      const 不虚 = !制p.真正虚浮;
            const 势敌 = (被制p.占比 - 制p.占比) < 15;
      // ★ 2026-10-04（使用者裁「加」）：「制得其宜」须**两头都管**——旧实现只查"制不及"，
      //   不查规格 §一之二 一之三 ①「不宜制过头」。今按档位序差**对称**判：
      //     档序（引擎操作化，沿用 tenGodStrength 四档）：弱 0 ／ 中 1 ／ 强 2 ／ 极 3
      //     档差 ≥ +2 ⇒ **制太过**（不宜制过头）；档差 ≤ −2 ⇒ **制不及**（奴欺主）
      const 档序 = { 弱: 0, 中: 1, 强: 2, 极: 3 };
      const 档差 = (档序[制p.档] ?? 1) - (档序[被制p.档] ?? 1);
      const 制太过 = 档差 >= 2;
      const 势敌且有根透干 = 势敌 && (制p.本气根数 ?? 0) > 0 && (制p.透干 ?? []).length > 0;
      const 制不及 = 档差 <= -2 && !势敌且有根透干;
      const 宜 = !制不及 && !制太过;
      // ⛔ 守卫（2026-10-04 实测补，且**须限定条件**）：候选**不得就是"正在威胁日主的官杀"**。
      //   ⚠ 初版守卫写成「候选 === 官杀即拒」，**过宽**——实测 `辛卯 癸巳 戊申 壬戌`
      //     （日主土、最旺＝土＝日主自己、官杀木**不威胁**且**担力可任**）：
      //     此时「木」正是「**给过剩之日主派活**」的正解（官克身），却被误判自毁。
      //   ⇒ 只在**官杀确实构成威胁**时拒。
      const 自毁 = 官杀五行c === 制 && !!第一.官杀?.构成威胁;
      制可行 = !自毁 && 不虚 && 势敌 && 宜;
      制据 = 自毁 ? `⚠ **候选即正在威胁日主的官杀**（${制}）⇒ **不得取**（否则"制"的是日主自己）`
        : (官杀五行c === 制 ? `⚠ 候选即官杀（${制}）——但该官杀**不威胁**（担力${担力c}）⇒ 可作"给过剩日主派活"之官，**非自毁**；`
          + `制者档「${制p.档}」；势${势敌 ? '可敌' : '不敌'}；${宜 ? '制得其宜' : 制太过 ? '**制之太过（不宜制过头）**' : '**制之不及**'}`
          : `制者${制}档「${制p.档}」${不虚 ? '' : '／**真正虚浮**'}；势${势敌 ? '可敌' : '不敌（反被反克）'}；`
            + `${宜 ? '制得其宜' : 制太过 ? '**制之太过（不宜制过头）**' : '**制之不及（奴欺主）**'}`);
    }
    // —— 化路可行性：印自身站得住（＝不得「真正虚浮」）——
    //   ⚠ 2026-10-04 修正：旧写法用 `源头在局 || 根数>0`，与 `powerOf.真正虚浮` **两把尺子**
    //   （`真正虚浮` ＝ 无自根 ∧ **源头亦无力**，比"有无落点"宽）。三处判据今统一为 `!真正虚浮`。
    const 化条目 = 化列表.map((化) => {
      const 化p = powerOf(chart, 化);
      const 可行 = !化p.真正虚浮;
      return {
        路线: '引化归身（通关）', 字或五行: 化, 来源类: '化', 可行,
        可行性: `桥${化}档「${化p.档}」；自根 ${化p.根数} 处／其源头${化p.源头五行 ?? '—'}${化p.源头有力 ? '有力' : '无力'}；`
          + `${可行 ? '可化' : '**真虚浮（无自根且源头无力）⇒ 化不动**'}`,
        说明: `有害者 ${有害者.join('、')} 生 ${化}、${化}生${D}（日主${化 === D ? '——**退化：桥即日主本行**' : ''}）`,
      };
    });

    if (制) 候选.push({
      路线: '制最旺之五行（病药）', 字或五行: 制, 来源类: '制',
      可行: 制可行, 可行性: 制据, 说明: `制${旺序[0]}（${占比[旺序[0]]}%）`,
    });
    for (const e of 化条目) 候选.push(e);
    if (调) 候选.push({ 路线: '调候（《穷通宝鉴》）', 字或五行: 调, 来源类: '调候', 说明: '月令寒暖燥湿所需' });
        // ⚠ 2026-10-04 修正：`制` 是**五行名**、`调` 是调候表原样的**干支字**，旧式 `制 === 调`
    //   永不相等（如 '木' === '甲' 为假）⇒ 该候选**从不产出**（死码）。今按五行归一后比较。
    if (制 && 调 && 制 === 五行字(调)) {
      const 同归可行 = 制可行;
      候选.push({
        路线: '★ 两路同归',
        字或五行: 制,
        来源类: '同归',
        可行: 同归可行,
        可行性: 同归可行 ? `病药与调候皆指向「${制}」，势足以敌且制得其宜 ⇒ 两路同归首选` : `两路同归但力量不足`,
        说明: `病药与调候皆指向「${制}」——主要矛盾的解与气候所需同字，此类盘最不易取错`,
      });
    }

    const 可行者 = 候选.filter((x) => x.可行 === true);
    const 可行五行集0 = [...new Set(可行者.map((x) => 五行字(x.字或五行)).filter(Boolean))];
    const 皆不可行 = 官杀重 && 候选.some((x) => x.可行 === false) && 可行者.length === 0;
    取用定案 = {
      官杀担力: 官杀重 ? 担力c : null,
      官杀为: !官杀重 ? '局中无官杀' : (担力c === '可任' ? '**贵气·位**（宜化，不宜制过头）' : '**杀·灾**（制化皆可）'),
      宜: !官杀重 ? '直接论用神（《五言独步》「有煞只论煞，无煞方论用」）'
        : (担力c === '可任' ? '**化**（通关）优先；制**不禁止**，但不宜制过头' : '**制化皆可**'),
      可行候选: 可行者.map((x) => `${x.字或五行}（${x.来源类}）`),
      判: 可行者.length === 0
        ? (皆不可行 ? '⚠ **两条路皆不可行** ⇒ 转「**克／泄／耗**」兜底取用' : '（未生成可比对的候选）')
        : 可行五行集0.length === 1
          ? `只「${(可行者.find((x) => x.来源类 === '同归') || 可行者[0]).字或五行}（${可行者.map((x) => x.来源类).join('／')}）」可行 ⇒ 取之`
          : `${可行五行集0.length} 种五行皆可行 ⇒ **并列报出**，各自代价见"可行性"，**不替使用者定**`,
    };
  }
  // ★ 官杀优先（使用者 2026-09-28：「先保命的意思其实就是**优先处理官杀**（有杀先论杀），
  // 看这个官杀究竟是好是坏（**日主能否承载**），是否需要**供起来**（比如日主强旺、时上一位贵）。
  // 官和杀都是相对的（对弱的日主来说，官就是杀，反之杀为偏官）。官杀构成威胁究竟是什么？
  // **就是看这个官杀对我来说是好是坏**」）。
  // 典据：《三命通会》引《五言独步》「**有煞只论煞，无煞方论用**」；
  // 《三命通会·论七煞》「**有制谓之偏官，无制谓之七煞**」；
  // 《滴天髓·官杀》「官杀混杂来问我，有可有不可……**日主旺相可混也，日主休囚不可混也**」；
  // 《神峰通考·时上一位贵》「若日干生旺，时上有杀，则用之为时上一位贵；若日干弱，时上杀旺……主贫贱」。
  const 官杀五行 = 克我者(D);
  const 官杀位 = occupantsOf(chart, 官杀五行);
  const 官杀力度 = powerOf(chart, 官杀五行);
  const 官杀藏透 = {
    透干: 官杀位.filter((o) => o.层 === '天干').map((o) => `${o.宫位}${o.字}`),
    支中: 官杀位.filter((o) => o.层 !== '天干').map((o) => `${o.宫位}${o.字}(${o.藏})`),
  };
  const 同党占比0 = (占比[D] ?? 0) + (占比[生我者(D)] ?? 0);
  const 冲拔支 = new Set();
  for (const c of (gzRelations(chart.pillars, null)['地支六冲'] ?? [])) {
    for (const d of 得地) {
      const bName = d.位 ? d.位.slice(-1) : '';
      if (c.pair && c.pair.includes(bName)) 冲拔支.add(d.位);
    }
  }
  const 根被冲拔 = 得地.length > 0 && 得地.every((d) => 冲拔支.has(d.位));
  const 担力 = (根被冲拔 && 第一.官杀?.构成威胁) ? '不可任'
    : (得地.length > 0 || 得势.length > 0 || 同党占比0 >= 40) ? '可任'
    : (得地.length === 0 && 得势.length === 0 && 同党占比0 < 25) ? '不可任' : '两可';
  // 时上一位贵：时干透一位官杀、日主健旺、不重见、不混杂（《神峰通考》2.9、《渊海子平》五言独步）
  const 时干 = chart.pillars[3].stem;
  const 时干支十神 = chart.pillars[3].tenGod;
  const 官杀重见 = 官杀位.filter((o) => o.层 === '天干').length > 1;
  const 时上一位贵 = 时干支十神 === '七杀' || 时干支十神 === '正官';
  const 官杀吉凶 = 官杀位.length === 0
    ? {
      有官杀: false,
      判: '局中**无官杀** ⇒ 依《五言独步》「有煞只论煞，**无煞方论用**」，可直接论用神，不必先处理官杀。',
    }
    : {
      有官杀: true, 官杀五行, 落点: 官杀位.map((o) => `${o.宫位}${o.字}${o.藏 ? `(${o.藏})` : ''}`),
      透干: 官杀藏透.透干, 支中: 官杀藏透.支中, 力度档: 官杀力度.档,
      日主担力: 担力, 担力据: `得地 ${得地.length}／得势 ${得势.length}／同党(日主＋印) ${同党占比0.toFixed(1)}%${根被冲拔 ? '（通根受冲拔）' : ''}`,
      可任: 担力 === '可任' && 官杀力度.档 !== '极',
      判: (担力 === '可任' && 官杀力度.档 !== '极')
        ? `官杀为**贵气**（日主能任）⇒ 须**供起来**：**不可伤**（忌制伏太过——《滴天髓》「与其制杀太过，不若官杀混杂之美」）、`
          + `忌混杂（《滴天髓》「日主旺相可混」）、喜生扶护卫；此为"**有制谓之偏官**"之侧（《三命通会》）。`
        : (担力 === '不可任'
          ? `官杀**对日主为杀**（不能承载）⇒ 须**制化**（食伤制／印化／合去），否则「**杀重身轻非贫即夭**」（《滴天髓》）；`
            + `此时"官"亦是杀——《三命通会》「**有制谓之偏官，无制谓之七煞**」，官杀之别在**名**（阴阳），好坏在**承载**。`
          : `日主担力**两可**、官杀力度【${官杀力度.档}】⇒ **须并陈两读**：可任则官为贵（供之不可伤）、`
            + `不可任则官即为杀（须制化）；引擎不代判，请以日主根气与大运补根为验。`),
      时上一位贵: 时上一位贵
        ? { 成立否: 担力 === '可任' && !官杀重见,
          依据: '《神峰通考》2.9「若日干生旺，时上有杀，则用之为时上一位贵」；'
            + '《渊海子平》五言独步「时上一位贵……**日主要刚强**，名利方有气」',
          条件: `时干${时干}为${时干支十神}；官杀重见于天干 ${官杀重见 ? '是' : '否'}；日主担力 ${担力}`,
          忌: '年月日重见、身弱、官煞混杂、**制伏太过**（《三命通会》：时上偏官"只一位为妙"）' }
        : { 成立否: false, 说明: `时干${时干}为${时干支十神}，非官杀 ⇒ 本盘不涉"时上一位贵"` },
    };
  const 主要矛盾 = {
    一_先保命: `**有煞只论煞，无煞方论用**（《三命通会》引《五言独步》）——`
      + `先处理**官杀**：${官杀吉凶.判}`
      + `　〔辅〕日主两端（极端才动旺衰）：同党[日主＋印] ${同党占比0.toFixed(1)}%、得地 ${得地.length}／得势 ${得势.length}——`
      + (!立得住 && 同党占比0 <= 20
        ? '**极弱且无依归**（如木已无"养"之必要）⇒ 不必以旺衰取用，须先裁「从／不从」；'
        : 同党占比0 >= 55 ? '**太强**⇒ 须先裁「顺其强势」还是「克／泄／耗之以使其长得更好」；'
          : '不强不弱之间 ⇒ **不以旺衰定调**。')
      + '此步只定**前提**，不给日主强弱打分',
    官杀吉凶,
    二_主要矛盾: `最旺之五行＝**${旺序[0]}**（占 ${占比[旺序[0]]}%）` + (() => {
      const 关 = 旺序[0] === 克我者(D) ? '＝官杀，直接克日主'
        : 旺序[0] === KE_MAP[D] ? '＝财，耗日主' : '';
      return 关 ? `，对日主${关}` : '';
    })(),
    三_次要矛盾: `${旺序[1]}（占 ${占比[旺序[1]]}%）`,
    四_候选用神: 候选,
    四之二_取用定案: 取用定案,
    五_判据: '候选来源（格局／通关／病药／扶抑／调候）**无先后尊卑**，谁解决「二_主要矛盾」谁当家；'
      + '且须以规格 ★（五）复验：该字是否**真在帮主要矛盾**——帮不到者，纵"生我"亦不为喜。'
      + '　★ 2026-10-04 补充：候选**先过可行性**（制路须「势足以敌 ∧ 制得其宜」；化路须「印在局 ∧ 源头有力」），'
      + '并据**官杀担力**定宜制宜化（可任⇒宜化、不宜制过头；不可任⇒制化皆可）；'
      + '**「杀多」本身不是判据**，只令"制"更难过关。',
  };

  // ══════════════════════════════════════════════════════════════════
  // ★★ 接线修正（体检表 R2：旧版 53/500＝10.6% 自相矛盾）
  //   旧版把**调候暂取值**下传给第二/三/四条，而「④之二 取用定案」另算一套候选，
  //   两者不接线 ⇒ 同一份输出里，定案说「只 X 一条可行 ⇒ 取之」，
  //   第 2 条又说「X 本色为忌」（实测 53/500 盘如此）。
  //   依据：规格 §一之二（二）——「用神＝解决『主要矛盾』的那个字；格局／通关／病药／
  //   扶抑／调候只是**候选来源**，谁解决主要矛盾谁当家」；§一之二 一之三 ③——
  //   「只一条可行 ⇒ 取那条」。
  //   ⇒ 故此处**按定案接线**：调用方声明 ＞ 定案唯一可行候选 ＞ 调候暂取（兜底）。
  //     ⚠ 多条并列／全不可行 ⇒ **不替调用方定**，仍回落调候暂取并标「待核定」（规格 ③）。
  //     ⚠ 调用方显式声明者**一律不覆盖**（AGENTS.md 附·第 5 步：用神由调用方选定）。
  //   ⚠ 这只是**接线**，不改任何子判据；四条自身的算法一行未动。
  // ══════════════════════════════════════════════════════════════════
  const 定案可行者 = 候选.filter((x) => x.可行 === true);
  const 可行五行集 = [...new Set(定案可行者.map((x) => 五行字(x.字或五行)).filter(Boolean))];
  const 首选条目 = 定案可行者.find((x) => x.来源类 === '同归') || 定案可行者[0];
  const 定案采用 = (!declaredYong && 可行五行集.length === 1 && 首选条目)
    ? { 五行: 可行五行集[0], 原字: 首选条目.字或五行, 来源类: 首选条目.来源类 }
    : null;
  const 采用用神 = declaredYong ?? 定案采用?.五行 ?? 用神;
  const 采用用神来源 = declaredYong ? 用神来源
    : 定案采用 ? `按「④之二 取用定案」：唯一可行候选「${定案采用.原字}（${定案采用.来源类}）」⇒ 采用为四条用神`
      + `（引擎按调候表暂取的原值为「${用神暂取 ?? '—'}」→「${用神 ?? '—'}」，**仅供对照**；**待调用方核定**）`
      : 用神来源;
  const 用神接线 = 定案采用
    ? `**已接线**：定案唯一可行候选「${定案采用.原字}（${定案采用.来源类}）」⇒ 采用为用神；`
      + `调候暂取值「${用神 ?? '—'}」仅列作对照。`
    : declaredYong ? '调用方已声明用神，引擎不覆盖。'
      : `**未接线**（${定案可行者.length === 0 ? '定案无可行候选' : 可行五行集.length > 1 ? `定案有 ${可行五行集.length} 条不同五行并列可行，不替调用方定` : '定案候选无法归一到五行'}）`
        + `⇒ 四条仍按调候表暂取值「${用神 ?? '—'}」计算，**须调用方核定后再用**。`;

  // ★ 第 2 条须同时以**用神**为参照：同一字可"对日主有情、对用神却是克神"，
  // 此时只宜暗藏、不宜引透（使用者 2026-09-28 复盘）。
  const 第二 = qingOf(chart, {
    ...(忌神五行 ? { 忌神五行 } : {}),
    ...(采用用神 ? { 用神五行: 采用用神 } : {}),
    // ★（七）1 同字条款：把第 1 条判「不构成威胁」的财／官字透传下去（`:668-674`）
    ...(() => {
      const 免 = [];
      if (第一.官杀?.构成威胁 === false) 免.push(克我者(D));
      if (第一.财?.构成威胁 === false) 免.push(KE_MAP[D]);
      return 免.length ? { 第1条不威胁: 免 } : {};
    })(),
    // 把「是否调用方声明」「调候原表值」「是否取自定案」透传给 qingOf，供（八）结构分析标注来源
    ...(declaredYong ? {} : { 用神声明: false }),
    ...(用神暂取 ? { 用神暂取 } : {}),
    ...(定案采用 ? { 用神来自定案: `④之二 取用定案之唯一可行候选「${定案采用.原字}（${定案采用.来源类}）」` } : {}),
  });
  const 第三 = 采用用神 ? protectionOf(chart, 采用用神, { 岁运 }) : null;
  const 第四 = structureOf(chart, { 用神五行: 采用用神, 岁运 });

  // ★（三）从格＝顺从气势（使用者 2026-09-28）：成立时四条**不是失效，而是改判**——
  // 用神＝所从之势本身、忌神＝逆此势者、岁运同理。此处只给**改判方向与口径**，
  // "所从之神"取「占比最旺」还是「十神力度最强」两说并列，待使用者核定。
  //   ⚠ 此处**不写死任何本的数值**（早先注里写「金 39.6%」既属某盘专属、且实测已漂成 39.2%）——
  //     两说的实际数值由 `congGeOf` 运行时算出，并列于 `所从之势_两说`。
  const sg = specialGejuOf(chart);
  const 特殊成立 = (sg.成立者 ?? []).filter((x) => /从|专旺|化气|两神/.test(String(x)));

  // P-003: 极弱顺从与从格闸门判定（五阴从势无情义，局无生扶，逆势之杂质受制）
  const dObj = dayMasterOf(chart);
  const isYinStem = STEM_YANG[STEMS.indexOf(dObj.stem)] === false;
  let p003从势 = false;
  if (isYinStem && !特殊成立.some((x) => x.includes('从'))) {
    const 印 = 生我者(D);
    const 印透干 = chart.pillars.some((p) => ELEMENTS[STEM_ELEMENT[p.stemIndex]] === 印);
    const 印占 = 占比[印] ?? 0;
    const 旺占 = 占比[旺序[0]] ?? 0;
    const 当令 = ELEMENTS[BRANCH_ELEMENT[BRANCHES.indexOf(branchAt(chart.pillars[1]))]] === 旺序[0];
    if (!印透干 && 印占 < 10 && (旺占 >= 40 || 当令)) {
      // 检查微根是否合化或受制（含三合半合、六合、六冲、相刑、穿害）
      const allBranches = chart.pillars.map(branchAt);
      const isBanHe = (br) => [
        ['申', '子', '辰'],
        ['亥', '卯', '未'],
        ['寅', '午', '戌'],
        ['巳', '酉', '丑'],
      ].some((grp) => grp.includes(br) && allBranches.some((ob) => grp.includes(ob) && ob !== br));

      const 微根受制或合化 = 得地.length === 0 || 得地.every((d) => {
        const b = d.位 ? d.位.slice(-1) : '';
        const rels = gzRelations(chart.pillars, null);
        const pairs = [
          ...(rels['地支六冲'] ?? []),
          ...(rels['地支三合'] ?? []),
          ...(rels['地支六合'] ?? []),
          ...(rels['地支相刑'] ?? []),
          ...(rels['地支相害'] ?? []),
        ];
        return isBanHe(b) || pairs.some((p) => p.pair?.includes(b) || (p.positions && p.positions.includes(b)));
      });
      if (微根受制或合化) {
        特殊成立.push('从势');
        p003从势 = true;
      }
    }
  }

  // ★（D）从格须验「杂质」与「流通路线」（使用者 2026-09-28 与 D-015 裁定）：
  // 「从格必须要所从的五行气势旺盛，不见杂质（破坏这个五行的五行）；如果有杂质，
  //   杂质必须无力，或有通关神引化流通（食生财、财生杀，顺流归宿汇于官杀，食伤非杂质）。
  //   若直克无通关则杂质有力破从；若三者均停则以财星通关和解从势。」
  const 从格杂质检验 = (() => {
    if (!特殊成立.length) return null;
    const 级序0 = { 极: 3, 强: 2, 中: 1, 弱: 0 };
    const 最强 = (tenGodStrength(chart).各十神 ?? [])
      .slice().sort((a, b) => (级序0[b.级别] ?? -1) - (级序0[a.级别] ?? -1))[0];
    const 验 = (神五行, 口径) => {
      if (!神五行) return null;
      const 杂质 = 克我者(神五行);                       // 破坏所从之势者
      const 在局 = occupantsOf(chart, 杂质).length > 0;
      const 杂质被重冲 = (gzRelations(chart.pillars, null)['地支六冲'] ?? []).filter((c) => {
        const 杂质字 = occupantsOf(chart, 杂质).map((o) => o.字);
        return 杂质字.some((z) => c.pair.includes(z));
      }).length >= 1;
      const 档 = powerOf(chart, 杂质).档;

      // D-015 体用路线通关检验：若克我者（杂质）与神五行之间存在通关神（生我者 且 杂质所生者），且通关神有力，
      // 则杂质顺生通关神、通关神再生神五行，气势连环流通，杂质化为生助源泉，不作破势杂质论
      const 通关神 = 生我者(神五行);
      const 能通关 = 通关神 && (SHENG_MAP[杂质] === 通关神);
      const 通关神在局 = 能通关 && occupantsOf(chart, 通关神).length > 0;
      const 通关神档 = 通关神在局 ? powerOf(chart, 通关神).档 : '弱';

      // 桥须两头贴身且有力量（本气或透干，藏干余气不得作桥）：相战双方之处必须有通关神同时贴身引化
      const 本气透干 = (o) => o.性质 === '本气' || o.性质 === '透干';
      const 杂质落点 = occupantsOf(chart, 杂质).filter(本气透干);
      const 神落点 = occupantsOf(chart, 神五行).filter(本气透干);
      const 通关落点 = 能通关 ? occupantsOf(chart, 通关神).filter(本气透干) : [];
      const 未通关之直克 = 杂质落点.some((z) =>
        神落点.some((s) => {
          const 直克 = proximityOf(z.宫位, s.宫位).柱差 <= 1;
          if (!直克) return false;
          const 有此通关桥 = 通关落点.some((t) =>
            proximityOf(t.宫位, z.宫位).柱差 <= 1 && proximityOf(t.宫位, s.宫位).柱差 <= 1
          );
          return !有此通关桥;
        })
      );
      const 通关有效 = 通关神在局 && 通关神档 !== '弱' && !未通关之直克;

      const 有力 = 在局 && 档 !== '弱' && !杂质被重冲 && !通关有效;

      // 使用者：「从格必须要所从的五行**气势旺盛**」——故先验所从之势自身够不够旺
      const 占比神 = 占比[神五行] ?? 0;
      const 当令 = ELEMENTS[BRANCH_ELEMENT[BRANCHES.indexOf(branchAt(chart.pillars[1]))]] === 神五行;
      const 旺盛 = 占比神 >= 30 || 当令;
      return {
        口径, 所从: 神五行, 所从占比: 占比神, 所从当令: 当令,
        杂质, 杂质在局: 在局, 杂质力度: 档,
        通关神: 能通关 ? 通关神 : null,
        通关有效,
        判: !旺盛
          ? `**不成从**（所从之势自身不旺：占 ${占比神}%、${当令 ? '当令' : '不当令'}——不合"气势旺盛"之要）`
          : 有力 ? '**不成从**（杂质有力相攻且无通关引化）'
            : (在局 ? (通关有效 ? '**成从**（杂质顺生通关神化为助势之源，势顺流通）' : '**可成假从**（杂质虽在但无力，待岁运祛除则假从变真从）') : '**成从**（势旺且局中无杂质）'),
      };
    };
    const 两说 = [验(旺序[0], '占比最旺'), 验(最强?.五行 ?? null, '十神力度最强')].filter(Boolean);
    const 有不成 = 两说.some((x) => /不成从/.test(x.判));
    return {
      判据: '使用者 2026-09-28 与 D-015：「从格必须要所从的五行气势旺盛，不见杂质；'
        + '顺生则非杂质，直克为杂质；若有杂质，杂质必须无力或有通关神引化（假从变真从）。」',
      两说,
      综合: 有不成
        ? '⚠ **所从之势有本气得力之杂质且无通关引化** ⇒ 本盘**不足以论从**；四项按普通格判据适用'
        : (两说.every((x) => /成从/.test(x.判)) ? '无杂质或通关顺化 ⇒ 从格成立' : '有杂质但无力 ⇒ 假从，待岁运祛除'),
    };
  })();
  const 从格成立 = !!(从格杂质检验 && (从格杂质检验.综合.includes('从格成立') || 从格杂质检验.综合.includes('假从')));
  const 适用前提 = 特殊成立.length
    ? (从格成立
      ? `⚠ **前提风险**：引擎判「${特殊成立.join('、')}」成立且过杂质检验，而体用四项是**非从格**判据——`
        + `从格中「印比有情」与「日主之根」含义相反。故四项结论**仅在"不从"前提下成立**；`
        + `从格成立时须改用 ` + '`从格改判`' + ` 之口径（用神＝所从之势本身、忌神＝逆势者）。`
      : `引擎原判「${特殊成立.join('、')}」成立，但按使用者 2026-09-28 与 D-015 的**杂质检验**（${从格杂质检验?.综合 ?? ''}）`
        + `⇒ **本盘不足以论从**，四项仍按**普通格**判据适用。`)
    : '未检出从／专旺／化气等特殊格局，四项按普通格判据适用。';

  const 级序 = { 极: 3, 强: 2, 中: 1, 弱: 0 };
  const 各神 = tenGodStrength(chart).各十神 ?? [];
  const 最强者 = 各神.slice().sort((a, b) => (级序[b.级别] ?? -1) - (级序[a.级别] ?? -1))[0];

  // D-015: 确定最终所从之势与流通归宿
  let 裁定所从 = 旺序[0];
  let 流通格局 = '从旺于大党';
  let 流通路线 = `顺从大势五行【${旺序[0]}】`;
  let 通关枢纽 = null;

  const D_EL = dayMasterOf(chart).element;
  const 食伤 = SHENG_MAP[D_EL];
  const 财星 = KE_MAP[D_EL];
  const 官杀 = 克我者(D_EL);
  const 印星 = 生我者(D_EL);
  const 比劫 = D_EL;

  const 有食伤 = (occupantsOf(chart, 食伤) || []).length > 0;
  const 有财星 = (occupantsOf(chart, 财星) || []).length > 0;
  const 有官杀 = (occupantsOf(chart, 官杀) || []).length > 0;
  const 财档 = powerOf(chart, 财星)?.档 ?? '弱';
  const 财有力 = 有财星 && 财档 !== '弱';

  const isCongWang = 特殊成立.some((x) => /专旺|从旺|从强|曲直|炎上|稼穑|从革|润下/.test(String(x)));

  if (isCongWang) {
    const 比占 = 占比[比劫] ?? 0;
    const 印占 = 占比[印星] ?? 0;
    if ((occupantsOf(chart, 印星) || []).length > 0 && (occupantsOf(chart, 食伤) || []).length > 0 && (occupantsOf(chart, 比劫) || []).length > 0) {
      流通格局 = '从旺泄秀格';
      裁定所从 = 比劫;
      通关枢纽 = 比劫;
      流通路线 = '印生比劫、比劫生食伤，秀气流行，以比劫为通关枢纽';
    } else {
      流通格局 = 比占 >= 印占 ? '从旺格' : '从强格';
      裁定所从 = 比占 >= 印占 ? 比劫 : 印星;
      流通路线 = '印比相资，气势纯粹专一';
    }
  } else {
    // 从弱局面（从杀、从财、从儿、复合从势）
    if (有食伤 && 有官杀 && 财有力) {
      const 食占 = 占比[食伤] ?? 0;
      const 财占 = 占比[财星] ?? 0;
      const 杀占 = 占比[官杀] ?? 0;
      const maxVal = Math.max(食占, 财占, 杀占);
      const minVal = Math.min(食占, 财占, 杀占);
      const 三者均停 = (maxVal - minVal <= 18) && (minVal >= 18);
      if (三者均停) {
        流通格局 = '复合从势格';
        裁定所从 = 财星;
        通关枢纽 = 财星;
        流通路线 = '食伤、财星、官杀三者并旺均停，以财星为通关和解枢纽';
      } else {
        流通格局 = '从杀格（食财杀顺生）';
        裁定所从 = 官杀;
        通关枢纽 = 财星;
        流通路线 = '食伤生财、财生官杀，气聚于官杀，食伤非杂质，财为通关护卫';
      }
    } else if (有食伤 && 有财星 && !有官杀) {
      流通格局 = '从财格（食伤生财）';
      裁定所从 = 财星;
      流通路线 = '食伤顺生于财，能量汇聚于财星';
    } else if (有财星 && 有官杀 && !有食伤) {
      流通格局 = '从杀格（财旺生杀）';
      裁定所从 = 官杀;
      流通路线 = '财星顺生官杀，能量汇聚于官杀';
    } else if (旺序[0] === 最强者?.五行) {
      裁定所从 = 旺序[0];
      流通格局 = `真从格（${最强者?.十神 ?? 旺序[0]}）`;
      流通路线 = `五行占比最旺与十神力度最强完全一致，局势纯粹顺从【${旺序[0]}】`;
    } else {
      裁定所从 = 最强者?.五行 ?? 旺序[0];
      流通格局 = `从格（从${最强者?.十神 ?? 旺序[0]}）`;
      流通路线 = `以月令提纲组织核心【${最强者?.十神 ?? 旺序[0]}】为统率`;
    }
  }

  const 从格改判 = 特殊成立.length ? {
    成立者: 特殊成立,
    适用性: 从格成立
      ? '本盘从格成立 ⇒ 四项**须改按此口径**'
      : `本盘经杂质检验**不足论从** ⇒ 下列改判口径**仅供参考**（四项仍按普通格判）`,
    改判: '**用神＝所从之势本身；忌神＝逆此势者；岁运同理**（顺之者吉、逆之者凶）——'
      + '四条不失效，但「印比有情」「日主之根」等普通格结论一律改按此读。',
    所从之势: 裁定所从,
    流通格局: 流通格局,
    流通路线: 流通路线,
    通关枢纽: 通关枢纽,
    改判用神: 裁定所从,
    改判忌神: 克我者(裁定所从),
    所从之势_两说: [
      { 口径: '占比最旺', 五行: 旺序[0], 值: `${占比[旺序[0]]}%` },
      { 口径: '十神力度最强', 五行: 最强者?.五行 ?? null, 值: 最强者 ? `${最强者.十神}【${最强者.级别}】` : null },
    ],
    裁定说明: `依据 D-015 体用路线流通归宿与通关仲裁法则裁定：${流通路线}，所从之势定为【${裁定所从}】。`,
    日主特性: `${dayMasterOf(chart).stem}为**${dayMasterOf(chart).yinYang}干**——`
      + (dayMasterOf(chart).yinYang === '阳'
        ? '阳干从格难成（《滴天髓》「**五阳从气不从势**，五阴从势无情义」；使用者 2026-09-28 亦指出丙火等不易从）'
        : '阴干相对易从（《滴天髓》「五阴从势无情义」）'),
  } : null;

  const 从儿分析 = congErAnalysisOf(chart, opts);
  if (从格改判 && 从儿分析.属于从儿) {
    从格改判.从儿分析 = 从儿分析;
    从格改判.流通路线 += `；从儿比劫【${从儿分析.比劫判定.角色}】（${从儿分析.比劫判定.说明}）`;
  }

  const 交叉 = [];
  if (第二?.交叉裁决) 交叉.push(第二.交叉裁决);
  if (第三?.岁运引克) 交叉.push(第三.岁运引克.结论);
  if (!交叉.length) {
    交叉.push('四条的参照点不同（第1/2条以**日主**为参照，第3条以**用神**为参照，第4条以**宫位网络**为参照）——'
      + '同一个字在两条里角色相反是常态，须并陈，不得择一。**本盘未检出该类冲突**。');
  }

  // ★ 补两项（2026-09-28）——原先这两个函数写好了却没人调用，属"规则与工具脱节"：
  //   · `youJiuOf`：判**所声明用神本身有没有救**。用神再好，若无根无气则"有救但力减"甚至不成器，
  //     故它必须与"用神是否到位／护卫是否有效"并看。判据出自《千里命稿》身强构成。
  //   · `siXiangOf`：由月支定**四象**（太阴/太阳/少阳/少阴），是体用路线"大势"一层的第 0 步；
  //     本身即**两套法并列并标冲突**，与本法"并陈不择一"的口径一致。
  const 用神首五行 = (() => {
    const m = String(采用用神 ?? '').match(/[木火土金水]/);
    return m ? m[0] : null;
  })();
  const 用神有救 = 用神首五行 ? youJiuOf(chart, 用神首五行) : null;
  const 四象 = siXiangOf(branchAt(chart.pillars[1]));

  const out = {
    题: '体用路线法四项（规格 §一之二）',
    日主五行: D,
    月令最大: `月支${branchAt(chart.pillars[1])}（宫位分量 ${GONG_WEIGHT.月支}，**全局最大**）`,
    宫位分量: GONG_WEIGHT,
    宫位分量序: GONG_RANK,
    宫位分量说明: GONG_WEIGHT_NOTE,
    作用力度: '同柱／邻柱＝贴身（1.00）；隔一柱＝隔位（0.55）；隔两柱＝遥隔（0.25）。桥须两头贴身。',
    四象,
    用神五行: 采用用神,
    用神来源: 采用用神来源,
    用神原表值: 用神暂取,
    用神接线,
    定案采用: 定案采用 ? { 五行: 定案采用.五行, 原字: 定案采用.原字, 来源类: 定案采用.来源类 } : null,
    用神有救,
    适用前提,
    从格杂质检验,
    主要矛盾,
    从格改判,
    从儿分析,
    格局成破: gejuChengPoOf(chart),
    第一_财官威胁: 第一,
    第二_印比有情: 第二,
    第三_用神护卫: 第三,
    第三之链_护卫链: 采用用神 ? protectionChainOf(chart, 采用用神, { 岁运 }) : null,
    第四_结构稳定: 第四,
    承载重估: chengzaiReassess(chart, { 岁运 }),
    相战择优: xiangzhanOf(chart, { 用神五行: 采用用神 }),
    犯旺: fanwangOf(chart, { 岁运 }),
    自合暗合: selfHiddenCombineOf(chart, { 岁运 }),
    双轨意象: dualImageMatrixOf(chart, { 主要矛盾, 用神五行: 采用用神, 岁运 }),
    交叉裁决: 交叉,
    覆盖: coverageOf(chart, { 主要矛盾, 用神五行: 采用用神, 岁运, ...opts }),
    判定: coverageOf(chart, { 主要矛盾, 用神五行: 采用用神, 岁运, ...opts }).covered ? '正常推演' : '本体系未覆盖，暂不判断',
    结论: coverageOf(chart, { 主要矛盾, 用神五行: 采用用神, 岁运, ...opts }).covered ? '命局在体用路线法宪法判据覆盖之内' : '本体系未覆盖，暂不判断',
    // 三者须并看，缺一即不闭环：用神本身有没有救（youJiuOf）、有没有护卫（第三）、
    // 结构稳不稳（第四）。引擎只报，不合并成单一结论。
    用神三重校验说明: '**用神须过三重**：① 自身有救（《千里命稿》身强构成分档）'
      + '② 有护卫（第三_用神护卫）③ 结构不动摇（第四_结构稳定）。'
      + '三者相互独立——用神当令有根（有救）仍可能被克无护，或所依之根被动摇。**须并陈，不得以一项代三项。**',
    禁令: [
      '禁止把「用神合忌神」读成用神被坏——**合的目的是让他为我所用**（做功与被坏方向相反，见规格 §四）',
      '**禁止以力度大小作"合"的门槛**：合是牵住他，不是压住他；合住与否只看有没有合',
      '禁止以旺衰作判据（旺衰只作分组条件与入手次序的建议）',
      '引擎不作绝对吉凶判断，只报「相对所声明者」的成全或破坏',
      '护卫 ≠ 化解：有护卫则不怕被克，压力仍须待岁运通关之神',
      '分歧并陈，不选边、不折中；凡宣称须附可复核出处',
    ],
  };
  return out;
}


function main() {
  const argv = process.argv.slice(2);
  const args = parseArgs(argv);
  if (args.help || (!args.birth && !args.solarterms)) {
    console.log(`八字推演 · 体用路线法 CLI
用法：
  node tiyong.mjs --birth "1990-05-20 14:30" [选项]

选项：
  -b, --birth     出生公历时间 "YYYY-MM-DD HH:MM"（缺时间按 12:00 计）
  -g, --gender    性别，男｜女，默认 男
  -l, --luck      大运干支，可重复（如 -l 辛巳 -l 壬午）
      --transit   岁运作用：给定大运或流年干支（如 --transit 壬辰）
      --longitude 出生地东经
      --yongshen X  声明用神（五行：木火土金水；或干支字如 丙/巳）
      --jishen X    声明忌神（同上）
      --json      输出完整 JSON 结构
  -h, --help      显示帮助
`);
    process.exit(args.help ? 0 : 1);
  }
  let birth = parseBirth(args.birth);
  const luckPillars = args.luck.map((gz) => ({ gz, startAge: null, startYear: null }));
  const chart = castChart({ ...birth, gender: args.gender, luckPillars: luckPillars.length ? luckPillars : undefined });

  const 用神五行 = 五行字(args.yongshen);
  const 忌神五行 = 五行字(args.jishen);
  if (args.yongshen != null && !用神五行) throw new Error(`--yongshen 只接受五行（木火土金水）或干支字（如 丙、巳、丙寅），收到「${args.yongshen}」`);
  if (args.jishen != null && !忌神五行) throw new Error(`--jishen 只接受五行（木火土金水）或干支字（如 庚、申、庚申），收到「${args.jishen}」`);

  const out = tiyongRouteOf(chart, { 用神五行, 忌神五行, 岁运: args.transit ?? null });
  if (args.format === 'json') console.log(JSON.stringify({ chart, tiyong: out }, null, 2));
  else console.log(formatTiyong(out));
}

const isMain = (() => {
  try { return process.argv[1] && import.meta.url === new URL(`file://${process.argv[1].replace(/\\/g, '/')}`).href; }
  catch { return false; }
})();
if (isMain) main();
